/* incident title / reason / timeline line: the coded message, else a recognised stored sentence, else AR() */
const incTitleH=i=>{ const m=incCode(i,'title')||satMsgOf(i.type,i); return (m&&msgText(m,true))??ARh(i.type); };
const incTitleT=i=>{ const m=incCode(i,'title')||satMsgOf(i.type,i); return (m&&msgText(m,false))??AR(i.type); };
