async function api(path, opt={}){
  const r = await fetch('/sawn-demo/api/'+path, {credentials:'same-origin', cache:'no-store', ...opt, headers:{'Content-Type':'application/json', ...(opt.headers||{})}});
  let j=null; try{ j=await r.json(); }catch(e){}
  if(r.status===401 && CORE.user){ CORE.user=null; location.reload(); }
  if(!r.ok){ const e=new Error(AR((j&&(j.error||(typeof j.detail==='string'&&j.detail)))||('HTTP '+r.status))); e.status=r.status; throw e; }
  return j;
}
