/* re-render only when nobody is typing or has a dialog open */
function safeRender(){
  if(edit||rem||document.querySelector('.modal-bg')) return;
  const a=document.activeElement; if(a&&/INPUT|TEXTAREA|SELECT/.test(a.tagName)&&a.closest('#page')) return;
  const y=window.scrollY; render(); window.scrollTo(0,y);
}

/* ---------- mapping the platform's data onto this interface ---------- */
