const KIND_AR={staff:'موظف', contractor:'متعاقد', visitor:'زائر'};
const CARD_AR={active:['ok','فعّالة'], suspended:['warn','موقوفة'], revoked:['crit','ملغاة'], lost:['crit','مفقودة']};
