  const who=s.live==='other'?`${esc_(s.other||'')}`:s.employee?`${esc_(s.employee)} · <span class="num" dir="ltr">${esc_(s.empNo||'')}</span>`:'';
  return `<span class="gface ${L[0]}">${s.image?`<a href="/sawn-demo/api/facerec/evidence/${encodeURIComponent(s.image)}" target="_blank" rel="noopener"><img src="/sawn-demo/api/facerec/evidence/${encodeURIComponent(s.image)}" alt="صورة كاميرا الوجه" loading="lazy"></a>`:`<span class="gface-ph">${ico('user',22)}</span>`}<span class="gface-m"><b>${L[1]}</b>${who?`<span>${who}</span>`:''}${s.similarity!=null?`<span>التطابق <b class="num">${n(s.similarity)}</b> · الحيوية <b class="num">${n(s.liveness)}</b></span>`:''}${s.camera?`<small>${esc_(s.camera)}</small>`:''}</span></span>`;
