    coreLast=r; logEvt({kind:'act', what:'تمرير بطاقة في البوابة A', target:i.badge}); coreSoon(); render();
    toast(`القرار: ${{ok:'سماح',no:'مرفوض',ref:'تحقق يدوي'}[CRES[r.result]]||r.result}`);
