const sensorsOn = () => ((LIVE.status&&LIVE.status.sensors)||[]).filter(s=>s.online!==false).length;
/* gate "latest passages": live NFC card presentations from the reader + card-swipe decisions, newest first */
const RMAP_PASS={identified:'ok','suspect-clone':'no','enrolled-after-tap':'ref',unlinked:'ref','not-eligible':'ref'};
/* The platform's lock decision for a reader tap wins over the credential state when present. */
const GATE_REASON={ok:'مسموح', metal:'معادن', 'unknown-card':'بطاقة غير مسجّلة', 'inactive-card':'بطاقة غير فعّالة', 'not-level5':'دون المستوى 5', 'cloned-card':'بطاقة منسوخة', 'metal-not-checked':'لم يُفحص للمعادن', 'wireless-device':'جهاز لاسلكي غير مصرّح', 'airspace-offline':'حسّاس الأجهزة غير متصل', 'device-check':'جهاز يحتاج فحصاً يدوياً', 'remote-open':'فتح عن بُعد', 'not-cached':'ليست في النسخة المحلية', 'no-clock':'ساعة البوابة غير مضبوطة', error:'خطأ في المنصة'};
const readerPassR = e => e.decision==='granted'?'ok':e.decision==='denied'?'no':(RMAP_PASS[e.credentialState]||'ref');
/* one reader event → a passage row (used by the live table and the full history) */
