/* ================= language: Arabic (default) or English =================
   Pages written for the platform use TX(ar, en). The rest of the interface is written in Arabic;
   in English every Arabic text on the page is looked up in EN_DICT (numbers are kept as they are). */
const AR_RE=/[؀-ۿ]/;
const EN_MAP=(()=>{ const m=new Map(); try{ for(const [k,v] of Object.entries(typeof EN_DICT==='object'?EN_DICT:{})) m.set(k,v); }catch(e){} return m; })();
const NUM_RE=/\d+(?:[.,:]\d+)*/g;
const enMiss=new Set();
function enText(t){
  const s=t.replace(/\s+/g,' ').trim(); if(!s||!AR_RE.test(s)) return null;
  let v=EN_MAP.get(s); if(v!=null) return v===s?null:v;
  const nums=s.match(NUM_RE)||[], key=s.replace(NUM_RE,'#');
  v=EN_MAP.get(key); if(v!=null){ let i=0; return v.replace(/#/g,()=>nums[i++]??''); }
  /* sentences joined with " · " or "، ": translate each part */
  for(const sep of [' · ','، ',' — ',': ']){ if(s.includes(sep)){ const parts=s.split(sep).map(x=>enText(x)??x); if(parts.some((x,i)=>x!==s.split(sep)[i])) return parts.join(sep==='، '?', ':sep); } }
  enMiss.add(key); return null;
}
const EN_ATTR=['placeholder','aria-label','title','alt','label'];
function enTree(root){
  if(LANG!=='en'||!root) return;
  if(root.nodeType===3){ const v=enText(root.nodeValue); if(v!=null&&!AR_RE.test(v)) root.nodeValue=root.nodeValue.replace(/\S[\s\S]*\S|\S/,v); return; }
  if(root.nodeType!==1) return;
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);
  let n=root;
  do{
    if(n.nodeType===3){ if(AR_RE.test(n.nodeValue)){ const v=enText(n.nodeValue); if(v!=null&&!AR_RE.test(v)) n.nodeValue=n.nodeValue.replace(/\S[\s\S]*\S|\S/,v); } }
    else { if(n.tagName==='SCRIPT'||n.tagName==='STYLE') continue; for(const a of EN_ATTR){ const x=n.getAttribute&&n.getAttribute(a); if(x&&AR_RE.test(x)){ const v=enText(x); if(v!=null&&v!==x&&!AR_RE.test(v)) n.setAttribute(a,v); } } }
  } while((n=w.nextNode()));
}
let enObs=null;
function enStart(){
  if(LANG!=='en') return;
  document.documentElement.lang='en'; document.documentElement.dir='ltr';
  document.querySelectorAll('[dir="rtl"]').forEach(e=>e.setAttribute('dir','ltr'));
  document.querySelectorAll('[lang="ar"]').forEach(e=>e.setAttribute('lang','en'));
  document.title='SAWN';
  enTree(document.body);
  enObs=new MutationObserver(list=>{ for(const m of list){ if(m.type==='characterData') enTree(m.target); else if(m.type==='attributes') enTree(m.target); else m.addedNodes.forEach(enTree); } });
  enObs.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:EN_ATTR});
}
/* Arabic: text that reaches the page in English (server messages, device types, 3D labels) is
   looked up in the shared Arabic dictionary; names and IDs with no entry stay as they are. */
function arStart(){
  if(LANG!=='ar') return;
  const LAT=/[A-Za-z]{2}/;
  const doN=n=>{
    const el=n.parentElement; if(!el||el.closest('script,style,code,textarea,[data-noar]')) return;
    const v=n.nodeValue; if(!LAT.test(v)) return;
    const core=v.trim(); let t; try{ t=window.SAWN_AR(core); }catch(e){ return; }
    if(t&&t!==core) n.nodeValue=v.replace(core,t);
  };
  const walk=r=>{ if(r.nodeType===3) return doN(r); if(r.nodeType!==1) return; const w=document.createTreeWalker(r,NodeFilter.SHOW_TEXT); let n; while((n=w.nextNode())) doN(n); };
  const run=()=>{ walk(document.body); new MutationObserver(list=>{ for(const m of list){ if(m.type==='characterData') doN(m.target); else m.addedNodes.forEach(walk); } }).observe(document.body,{childList:true,subtree:true,characterData:true}); };
  if(window.SAWN_AR) run(); else window.addEventListener('sawn-shared',run,{once:true});
}
function setLang(l){ try{ localStorage.setItem('sawn.lang',l); }catch(e){} location.reload(); }
window.SAWN_MISSING=()=>[...enMiss];
/* ================= platform pages, native in this interface (connected mode) ================= */
const TX = (a,e) => LANG==='en' ? e : a;
const SH = () => window.SAWN_SH || {};
function ago(t){ if(!t) return TX('أبداً','never'); const m=Math.round((Date.now()-t)/60000); if(m<1) return TX('الآن','just now'); if(m<60) return TX(`قبل ${m} د`,`${m} min ago`); const h=Math.round(m/60); if(h<48) return TX(`قبل ${h} س`,`${h} h ago`); const d=Math.round(h/24); return TX(`قبل ${d} يوم`,`${d} days ago`); }
const dShort = t => { if(!t) return '—'; const d=new Date(t),p=n=>String(n).padStart(2,'0'); return `${p(d.getDate())}/${p(d.getMonth()+1)}/${d.getFullYear()}`; };
const loading = () => `<div class="muted-s" style="padding:18px">${TX('جارٍ التحميل…','Loading…')}</div>`;
const emptyRow = (n,t) => `<tr><td colspan="${n}"><div class="empty" style="padding:24px"><span>${t}</span></div></td></tr>`;
/* fetch once per visit, keep the last answer, re-render when it arrives */
const PG = {};
function pgLoad(key, paths, force){
  const c=PG[key]; if(c&&!force&&(c.busy||Date.now()-c.at<8000)) return c.data;
  PG[key]={...(c||{}), busy:true, at:Date.now()};
  Promise.all(paths.map(p=>api(p).catch(e=>({__err:e.message})))).then(r=>{ PG[key]={data:r, at:Date.now(), busy:false}; safeRender(); });
  return c&&c.data;
}
const pgDrop = k => { delete PG[k]; };
/* a small form dialog in this interface's style; resolves to the values or null */
function askForm(title, fields, ok){
  return new Promise(res=>{
    document.querySelectorAll('.core-ask').forEach(x=>x.remove());
    const w=document.createElement('div'); w.className='modal-bg core-ask';
    const sel=f=>`<select class="inp" name="${f.name}"${f.person?` aria-label="${esc_(f.label)}"`:''}>${f.options.map(([v,t])=>`<option value="${esc_(v)}" ${String(f.value)===String(v)?'selected':''}>${t}</option>`).join('')}</select>`;
    // a person dropdown (f.person: how its value names a person) keeps a "View employee details" button beside it
    const fld=f=>f.type==='select'?(f.person?`<div class="mf"><span>${f.label}</span>${f.help?`<small class="mf-help">${f.help}</small>`:""}<div class="row-c pv-row">${sel(f)}${pViewBtn(`.core-ask select[name="${f.name}"]`,f.person)}</div></div>`:`<label class="mf"><span>${f.label}</span>${f.help?`<small class="mf-help">${f.help}</small>`:""}${sel(f)}</label>`)
      : f.type==='textarea'?`<label class="mf"><span>${f.label}</span>${f.help?`<small class="mf-help">${f.help}</small>`:""}<textarea class="inp" name="${f.name}" rows="3" ${f.required?'required':''} maxlength="1000">${esc_(f.value||'')}</textarea></label>`
      : f.type==='check'?`<label class="mck"><input type="checkbox" name="${f.name}" ${f.value?'checked':''}> ${f.label}</label>`
      : `<label class="mf"><span>${f.label}</span>${f.help?`<small class="mf-help">${f.help}</small>`:""}<input class="inp" name="${f.name}" type="${f.type||'text'}" value="${esc_(f.value??'')}" ${f.required?'required':''} ${f.attrs||''}></label>`;
    w.innerHTML=`<form class="modal ed" role="dialog" aria-modal="true" aria-label="${esc_(title)}"><div class="m-h"><div><h3>${title}</h3></div></div><div class="m-b">${fields.map(fld).join('')}</div><div class="m-f"><button type="button" class="btn" data-x>${TX('إلغاء','Cancel')}</button><button class="btn pri" type="submit">${ok||TX('حفظ','Save')}</button></div></form>`;
    document.body.appendChild(w);
    const done=v=>{ w.remove(); res(v); };
    w.querySelector('[data-x]').onclick=()=>done(null);
    w.onkeydown=e=>{ if(e.key==='Escape') done(null); };
    w.querySelector('form').onsubmit=e=>{ e.preventDefault(); const o={}; fields.forEach(f=>{ const el=w.querySelector(`[name="${f.name}"]`); o[f.name]=f.type==='check'?el.checked:f.type==='number'?(el.value===''?null:+el.value):el.value.trim(); }); done(o); };
    const first=w.querySelector('input,select,textarea'); if(first) first.focus();
  });
}
function confirmAsk(title, ok){ return askForm(title, [], ok||TX('تأكيد','Confirm')).then(v=>!!v); }
async function act(promise, okMsg, keys){
  try{ const r=await promise; if(r&&r.pending) toast(TX('أُرسل الطلب لموافقة شخص ثانٍ','Sent for a second person’s approval')); else if(okMsg) toast(okMsg); (keys||[]).forEach(pgDrop); coreSoon(); safeRender(); return r; }
  catch(e){ toast(e.message); return null; }
}
/* buttons only for people who have the permission */
