const HS2={ok:'ok',warn:'warn',down:'off',unconfigured:'mut',sim:'sim'}, HST=()=>({ok:TX('يعمل','Connected and healthy'),warn:TX('متدهور','Degraded'),down:TX('منقطع','Disconnected'),unconfigured:TX('غير متصل بعد','Not connected yet'),sim:TX('محاكاة','Simulated')});
