  const cont=`<div class="ralive">${[
    tile(TX('قرارات البوابة','Gate decisions'),gateSt,[c.centralLinkDown?TX('الدليل المركزي غير متاح، والبوابة A تقرر من نسختها المحلية','Central directory unreachable: Gate A decides from its local copy'):TX('متصل: البوابة A تتحقق من الدليل المركزي','Online: Gate A checks the central directory'), c.directory?TX(`النسخة المحلية: <span class="num">${c.directory.people}</span> شخص · ${ago(c.directory.syncedAt)}`,`Local copy: <span class="num">${c.directory.people}</span> people · ${ago(c.directory.syncedAt)}`):TX('لا توجد نسخة محلية بعد','No local copy yet')], pbtn('system.control','data-rd="sync"',TX('تحديث النسخة المحلية','Refresh local copy'))),
    tile(TX('مستشعر المجال الجوي','Airspace sensor'),(H['AS-1']||{}).status||'warn',[ARh((H['AS-1']||{}).detail||'—')]),
    tile(TX('التنبيهات بدون شاشة مفتوحة','Alerts without a console'),(H.consoles||{}).status==='ok'?'ok':'warn',[ARh((H.consoles||{}).detail||'')]),
    tile(TX('النسخ الاحتياطي','Backups'),(H.backup||{}).status||'warn',[ARh((H.backup||{}).detail||'—')], pbtn('system.control','data-rd="backup"',TX('نسخ احتياطي الآن','Back up now'))),
  ].join('')}</div>`;
  const hc=mp(TX('الفحوص الآلية','Automated checks'),`<div class="rsum">${[['ok',TX('يعمل','Working')],['warn',TX('يحتاج نظرة','Needs a look')],['down',TX('متوقف','Stopped')],['unconfigured',TX('لم يتصل بعد','Not connected yet')]].map(([k,t])=>`<span class="rsum-i ${k}"><b class="num">${R.health.filter(h=>h.real!==false&&h.status===k).length}</b>${t}</span>`).join('')}</div>${chkGroups}<details class="rlog" ${rLog?'open':''}><summary>${TX('آخر التغييرات','Recent changes')}</summary>${xl((R.log||[]).slice(0,12).map(l=>({lead:`<span class="dotst ${HS2[l.status]||'warn'}"></span>`,t:ARh(l.detail||''),s:`<bdi>${esc_(l.component)}</bdi> · ${audTime(l.t)}`})))}</details>`,tg(issues?'warn':'ok',issues?TX(`${issues} تحتاج متابعة`,`${issues} need attention`):TX('كل الفحوص سليمة','All checks pass')),'','pulse');
  const signsBy=k=>R.signs.filter(s=>k.includes(s.kind));
