  const pl=mp(TX('طبقات الحماية المادية · من الخارج إلى الداخل','Defence in depth · outside in'),`<div class="rlay">${R.layers.map((ly,i)=>{const st=ly.controls.map(([id])=>ctl(id)), w=st.includes('down')?'down':st.includes('warn')?'warn':st.includes('unconfigured')?'unconfigured':'ok'; return `<div style="--i:${i}"><span class="num">${i+1}</span><div><b>${ARh(ly.name)}</b><small>${ARh(ly.goal)}</small><div class="row-c" style="gap:6px;flex-wrap:wrap;margin-top:6px">${ly.controls.map(([id,lab],k)=>`<span class="mtag ${HS2[st[k]]==='off'?'crit':HS2[st[k]]}">${ARh(lab)}</span>`).join('')}</div></div>${dotS(w,ST[w])}</div>`;}).join('')}</div>`,'','','shield');
