  const au=!ZD?'…':!ok?NA:auths.length?auths.map(a=>{ const s=ZS[a.status]||['mut',a.status]; return `<div class="pdw-row"><div class="row-c" style="gap:6px;flex-wrap:wrap"><b>${zn(a.zoneId)}</b>${types&&types[a.zoneId]?ztBadge(types[a.zoneId]):''}${XB(s[0],s[1])}</div>${kv([[TX('النطاق','Scope'),a.subjectType==='person'?TX('تفويض شخصي لهذه المنطقة','Personal, this zone only'):TX(`عبر المجموعة ${esc_(a.subjectName)}`,`Via group ${esc_(a.subjectName)}`)],[TX('الغرض','Purpose'),`<span dir="auto">${esc_(a.reason)}</span>`],[TX('منحه','Granted'),`${esc_(a.grantedBy)} · ${d(a.grantedAt)}`],[TX('ينتهي','Expires'),a.expiresAt?d(a.expiresAt):TX('بلا تاريخ انتهاء','No end date')],[TX('آخر مراجعة','Last reviewed'),a.lastReviewedAt?`${d(a.lastReviewedAt)} · ${esc_(a.lastReviewedBy||'')}`:TX('لم يُراجع بعد','Not reviewed yet')],[TX('المراجعة مستحقة','Review due'),d(a.reviewDueAt)],...(a.revokedAt?[[TX('سُحب','Revoked'),`${d(a.revokedAt)} · ${esc_(a.revokedBy||'')}: ${esc_(a.revokeReason||'')}`]]:[])])}</div>`; }).join(''):`<p class="muted-s">${TX('لا توجد تفويضات مناطق','No zone authorizations')}</p>`;
  const gr=!ZD?'…':!ok?NA:groups.length?`<div class="row-c" style="gap:6px;flex-wrap:wrap">${groups.map(g=>`<span class="pill">${esc_(g.name)}</span>`).join('')}</div>`:`<p class="muted-s">${TX('لا توجد عضويات في مجموعات وصول','No access group memberships')}</p>`;
  const cards=(p.cards||[]).map(c=>{ const full=(LIVE.cards||[]).find(x=>x.id===c.id)||{}, s=CT[c.status]||['mut',c.status]; return `<span class="row-c" style="gap:6px;flex-wrap:wrap"><span class="num">${esc_(c.id)}</span>${XB(s[0],s[1])}${full.pinSet?tg('ok','PIN'):''}${c.physicalCredential?tg('mut',TX('بطاقة NFC مربوطة','NFC card linked')):''}</span>`; }).join('');
