const TEAM_T = () => ({security:TX('الأمن','Security'), safety:TX('السلامة','Safety (HSE)'), emergency:TX('الطوارئ','Emergency response')});
const TASK_T = () => ({assigned:TX('مُسند · بانتظار القبول','Assigned · waiting for acceptance'), accepted:TX('مقبول','Accepted'), on_scene:TX('في الموقع','On scene'), resolved:TX('عولج من المستجيب','Resolved by responder'), declined:TX('مرفوض من المستجيب','Declined')});
