const incStatusT = i => i&&i.phase==='expired'?TX('انتهت نافذة المرور المتوقعة','Predicted pass window ended'):(ST_T()[i&&i.status]||(i&&i.status)||'—');
const ST_T = () => ({new:TX('جديد','New'),ack:TX('مستلم','Acknowledged'),escalated:TX('مصعّد','Escalated'),confirmed:TX('مؤكد','Confirmed'),dismissed:TX('إنذار كاذب','Dismissed')});
const SRC_T = () => ({airspace:TX('مستشعر المجال الجوي','Airspace sensor'), gate:TX('نقطة تفتيش البوابة A','Gate A checkpoint'), health:TX('الفحوص الآلية','Health checks'), analysis:TX('تحليل السلوك','Behaviour analysis'), simulator:TX('سيناريو تدريبي','Training scenario'), vision:TX('الكاميرات الذكية','AI cameras')});
