function vResponseCore(p){
  const X=SH(), d=pgLoad('rs',['response/summary']), s=(d&&d[0]&&!d[0].__err)?d[0]:null, TM=TEAM_T(), TK=TASK_T(), me=CORE.user&&CORE.user.username;
  const met=i=>X.responseMetrics?X.responseMetrics(i):{overdue:false,toFirstResponse:null,deadline:0};
  const all=LIVE.inc.slice().sort((a,b)=>(coreOpen(b)-coreOpen(a))||(met(b).overdue-met(a).overdue)||(CSEV[b.sev]??1)-(CSEV[a.sev]??1)||b.createdAt-a.createdAt);
  const F={open:all.filter(coreOpen), over:all.filter(i=>coreOpen(i)&&met(i).overdue), un:all.filter(i=>coreOpen(i)&&!i.assignee), mine:all.filter(i=>coreOpen(i)&&i.assignee===me), done:all.filter(i=>!coreOpen(i))};
  const k=[['alert',TX('متأخرة عن المهلة','Overdue'),s?s.overdue:F.over.length],['user',TX('بدون مستجيب','Unassigned'),s?s.unassigned:F.un.length],['key',TX('مهامي','My tasks'),s?s.myTasks:F.mine.length],['clock',TX('وسيط أول استجابة (24 س)','Median first response (24 h)'),s?dur(s.medianFirstResponse24h):'—'],['check',TX('وسيط الإغلاق (24 س)','Median close (24 h)'),s?dur(s.medianClose24h):'—']];
  const kp=`<div class="mkp">${k.map(([i,t,n])=>`<div><span class="mkp-i">${ico(I[i]?i:'clock',15)}</span><div><small>${t}</small><b class="num">${n}</b></div></div>`).join('')}</div>`;
  const teams=s?`<div class="row-c" style="gap:8px;flex-wrap:wrap;margin:0 0 12px">${Object.entries(s.openByTeam||{}).map(([t,n])=>`<span class="mtag ${n?'warn':'mut'}">${TM[t]||esc_(t)} · <b class="num">${n}</b></span>`).join('')}</div>`:'';
  const tabs=`<div class="mtabs">${[['open',TX('المفتوحة','Open')],['over',TX('المتأخرة','Overdue')],['un',TX('بدون مستجيب','Unassigned')],['mine',TX('مهامي','Mine')],['done',TX('المغلقة','Closed')]].map(([x,t])=>`<button data-rsf="${x}" aria-pressed="${rsF===x}">${t} <span class="num">${F[x].length}</span></button>`).join('')}</div>`;
  const list=F[rsF]||[], sel=rsSel&&LIVE.inc.find(i=>i.ref===rsSel);
  const rows=list.map(i=>{const m=met(i); return `<tr class="${sel&&sel.ref===i.ref?'sel':''}" data-rs="${i.ref}" tabindex="0"><td>${sev(SEVK(i))}</td><td class="num"><b>${i.ref}</b></td><td><b>${incTitleH(i)}</b><div class="muted-s">${ARh(i.zone)}</div></td><td>${TM[i.team]||'—'}</td><td>${i.assignee?`<b>${esc_(i.assignee)}</b><div class="muted-s">${TK[i.taskStatus]||''}</div>`:`<span class="muted-s">${TX('لا أحد','nobody')}</span>`}</td><td>${coreOpen(i)?(m.overdue?XB('no',TX('متأخرة','Overdue')):m.toFirstResponse==null?XB('open',TX(`المهلة ${Math.round(m.deadline/60000)} د`,`deadline ${Math.round(m.deadline/60000)} min`)):XB('ok',dur(m.toFirstResponse))):XB('mut',incStatusT(i))}</td></tr>`;}).join('')||emptyRow(6,TX('لا توجد حوادث','No incidents'));
  const table=mp(TX('الحوادث','Incidents'),`<table class="tbl"><thead><tr><th>${TX('الخطورة','Severity')}</th><th>${TX('الرقم','Ref')}</th><th>${TX('الحادثة','Incident')}</th><th>${TX('الفريق','Team')}</th><th>${TX('المستجيب','Responder')}</th><th>${TX('الاستجابة','Response')}</th></tr></thead><tbody>${rows}</tbody></table>`,'','flush','bolt');
  return mh(p,'','',`<span class="live"><i></i>${TX('مباشر','Live')}</span>`)+kp+teams+tabs+`<div class="ggrid"><div class="gmain">${table}</div><aside class="gside">${sel?rsPanel(sel):mp(TX('التفاصيل','Details'),`<div class="muted-s" style="padding:18px">${TX('اختر حادثة','Select an incident')}</div>`,'','','doc')}</aside></div>`;
}
function rsPanel(i){
  const X=SH(), m=X.responseMetrics?X.responseMetrics(i):{}, TM=TEAM_T(), TK=TASK_T(), open=coreOpen(i), me=CORE.user&&CORE.user.username, mine=i.assignee===me, lead=coreCan('incidents.assign');
  const team=open&&lead?`<select id="rsTeam">${Object.entries(TM).map(([k,t])=>`<option value="${k}" ${k===i.team?'selected':''}>${t}</option>`).join('')}</select>`:(TM[i.team]||'—');
  const steps=open&&i.assignee&&(mine||lead)?[i.taskStatus==='assigned'?`<button class="btn sm pri" data-tk="accept">${TX('قبول','Accept')}</button><button class="btn sm" data-tk="decline">${TX('اعتذار','Decline')}</button>`:'', i.taskStatus==='accepted'?`<button class="btn sm" data-tk="on_scene">${TX('في الموقع','On scene')}</button>`:'', ['accepted','on_scene'].includes(i.taskStatus)?`<button class="btn sm pri" data-tk="resolved">${TX('تمت المعالجة','Resolved')}</button>`:''].join(''):'';
  const ev=[...(i.ev||[]),...(i.evx||[])];
  return mp(`<span class="num">${i.ref}</span> · ${incTitleH(i)}`,`<div style="padding:14px 16px">
    ${m.overdue?`<div class="mban">${ico('alert',14)} ${TX(`لم يستجب أحد خلال ${Math.round(m.deadline/60000)} د، وتم تنبيه المشرفين`,`Nobody responded within ${Math.round(m.deadline/60000)} min; supervisors alerted`)}</div>`:''}
    ${kv([[TX('الفريق','Team'),team],[TX('المستجيب','Responder'),i.assignee?`${esc_(i.assignee)}${mine?TX(' (أنت)',' (you)'):''} · ${TK[i.taskStatus]||'—'}`:TX('لا أحد','Nobody assigned')],[TX('أول استجابة','First response'),m.toFirstResponse==null&&open?TX(`بالانتظار · المهلة ${Math.round((m.deadline||0)/60000)} د`,`Waiting · deadline ${Math.round((m.deadline||0)/60000)} min`):dur(m.toFirstResponse)],...(i.assignedAt?[[TX('القبول بعد','Accepted after'),dur(m.toAccept)]]:[]),...(m.toClose!=null?[[TX('الإغلاق بعد','Closed after'),dur(m.toClose)]]:[])])}
    ${open&&(lead||steps)?`<div class="row-c" style="gap:6px;flex-wrap:wrap;margin:10px 0">${steps}${lead?`<button class="btn sm" id="rsAssign">${i.assignee?TX('إعادة إسناد','Reassign'):TX('إسناد لمستجيب','Assign')}</button>`:''}</div>`:''}
    ${i.reason?`<div class="sub-h">${TX('سبب التنبيه','Why it was flagged')}</div><p class="muted-s" style="margin:0">${incReasonH(i)}</p>`:''}
    ${ev.length?`<div class="sub-h">${TX('الأدلة','Evidence')}</div>${xl(ev.map(e=>({lead:`<span class="xi">${ico('eye',13)}</span>`,t:incEvH(i,e)})))}`:''}
    ${(i.images||[]).length?`<div class="row-c" style="gap:8px;flex-wrap:wrap;margin-top:8px">${i.images.map(im=>`<figure style="margin:0"><img src="/sawn-demo/api/evidence/${encodeURIComponent(im.file)}" alt="${esc_(im.label)}" style="width:132px;border-radius:8px;border:1px solid var(--line)"><figcaption class="muted-s num">${audTime(im.t)} · ${esc_(im.label)}</figcaption></figure>`).join('')}</div>`:''}
    <div class="row-c" style="gap:6px;flex-wrap:wrap;margin-top:14px"><button class="btn pri" id="rsReport">${ico('doc',14)}${TX('تقرير الحادثة','Incident report')}</button>${coreCan('incidents.handle')?`<button class="btn" id="rsAuth">${ico('alert',14)}${TX('إبلاغ جهة خارجية','Notify an authority')}</button>`:''}<a class="btn" href="#alerts" data-goinc="${i.ref}">${TX('القرار في التنبيهات','Decide in Alerts')}</a></div></div>`,'','','bolt');
}
async function rsReport(ref){
  let r; try{ r=await api(`incidents/${ref}/report`); }catch(e){ toast(e.message); return; }
  const i=r.incident, m=r.metrics, TM=TEAM_T(), TK=TASK_T(), SL=SEV_T(), SS=ST_T(), SR=SRC_T();
  const evs=[...(i.tl||[]).map(([t,x])=>({t,who:TX('النظام','System'),x:incLineH(i,x)})),...(i.notes||[]).map(n=>({t:n.t,who:esc_(n.by),x:TX('ملاحظة: ','Note: ')+esc_(n.text)})),...r.audit.map(a=>({t:a.t,who:esc_(a.actor),x:ARh(a.action)+(a.detail?' · '+ARh(a.detail):'')}))].sort((a,b)=>a.t-b.t);
  const sum=[TX(`${incTitleT(i)} في ${AR(i.zone)}.`,`${incTitleT(i)} at ${i.zone}.`), TX(`رُصدت ${audTime(i.createdAt)} بواسطة ${SR[i.source]||AR(i.source)}${i.simulated?' (سيناريو تدريبي)':''}.`,`Raised ${audTime(i.createdAt)} by ${SR[i.source]||i.source}${i.simulated?' (training scenario)':''}.`), TX(`الخطورة: ${SL[i.sev]}. الفريق المسؤول: ${TM[i.team]||i.team}.`,`Severity: ${SL[i.sev]}. Responsible team: ${TM[i.team]||i.team}.`), i.assignee?TX(`المستجيب: ${i.assignee} (${TK[i.taskStatus]||i.taskStatus}).`,`Responder: ${i.assignee} (${TK[i.taskStatus]||i.taskStatus}).`):TX('لم يُسند لمستجيب.','No responder was assigned.'), i.decidedBy?TX(`أُغلقت (${SS[i.status]}) بواسطة ${i.decidedBy}.`,`Closed as ${SS[i.status]} by ${i.decidedBy}.`):TX(`ما زالت مفتوحة (${SS[i.status]}).`,`Still open (${SS[i.status]}).`)];
  const tbl=(h,rows)=>`<table class="tbl"><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  const html=`<article class="rpt"><div class="rpt-h"><div><small>${TX('صون · تقرير حادثة','SAWN · Incident report')}</small><h2><span class="num">${i.ref}</span> · ${incTitleH(i)}</h2></div>${i.simulated?tg('sim',TX('تدريبي','Simulated')):''}</div>
    <h4>${TX('الملخص','Summary')}</h4><ul>${sum.map(x=>`<li>${x}</li>`).join('')}</ul>
    <h4>${TX('سبب التنبيه','Why it was flagged')}</h4><p>${i.reason?incReasonH(i):'—'}</p>
    <h4>${TX('التفاصيل','Details')}</h4>${kv([[TX('المكان','Zone'),ARh(i.zone)],[TX('المصدر','Source'),SR[i.source]||ARh(i.source)],[TX('الخطورة','Severity'),SL[i.sev]],[TX('الحالة','Status'),incStatusT(i)],[TX('الفريق','Team'),TM[i.team]||'—'],[TX('وقت الرصد','Raised'),`<span class="num">${audTime(i.createdAt)}</span>`],...(i.card?[[TX('البطاقة','Card'),`<span class="num">${esc_(i.card)}</span>`]]:[]),...Object.entries(i.extra||{}).map(([a,b])=>[ARh(a),ARh(String(b))])])}
    <h4>${TX('الاستجابة','Response')}</h4>${kv([[TX('المستجيب','Responder'),esc_(i.assignee||TX('لا أحد','Nobody'))],[TX('أسندها','Assigned by'),i.assignedBy?`${esc_(i.assignedBy)} · <span class="num">${audTime(i.assignedAt)}</span>`:'—'],[TX('أول استجابة','First response'),dur(m.toFirstResponse)],[TX('القبول','Accept'),dur(m.toAccept)],[TX('الإغلاق','Close'),dur(m.toClose)],[TX('أغلقها','Closed by'),i.decidedBy?esc_(i.decidedBy):'—']])}
    <h4>${TX('الأدلة','Evidence')}</h4>${[...(i.ev||[]),...(i.evx||[])].length?`<ul>${[...(i.ev||[]),...(i.evx||[])].map(e=>`<li>${incEvH(i,e)}</li>`).join('')}</ul>`:`<p>${TX('لا توجد أدلة مسجلة','No evidence recorded')}</p>`}
    <h4>${TX('الجهات الخارجية','Outside authorities')}</h4>${r.notices.length?tbl([TX('الوقت','Time'),TX('الجهة','Authority'),TX('المرجع','Reference'),TX('أبلغها','Reported by'),TX('ملاحظة','Note')],r.notices.map(n=>[`<span class="num">${audTime(n.t)}</span>`,esc_(n.agency),esc_(n.reference),esc_(n.author),esc_(n.note)])):`<p>${TX('لم تُبلّغ أي جهة','No authority was notified')}</p>`}
    <h4>${TX('التسلسل والإجراءات','Timeline and actions')}</h4>${tbl([TX('الوقت','Time'),TX('بواسطة','By'),TX('ماذا حدث','What happened')],evs.map(e=>[`<span class="num">${audTime(e.t)}</span>`,e.who,e.x]))}
    <p class="muted-s">${TX(`أعدّته صون لـ ${esc_(r.generatedBy)} · `,`Generated by SAWN for ${esc_(r.generatedBy)} · `)}<span class="num">${audTime(r.generatedAt)}</span></p></article>`;
  showInfo(TX('تقرير الحادثة','Incident report'), html);
  const f=document.querySelector('.core-ask .m-f'); const pb=document.createElement('button'); pb.className='btn'; pb.textContent=TX('طباعة أو حفظ PDF','Print / Save as PDF'); f.prepend(pb);
  pb.onclick=()=>{ const s=document.createElement('div'); s.className='print-sheet'; s.innerHTML=html; document.body.appendChild(s); document.body.classList.add('printing'); const done=()=>{ s.remove(); document.body.classList.remove('printing'); window.removeEventListener('afterprint',done); }; window.addEventListener('afterprint',done); window.print(); };
  logEvt({kind:'act', what:TX('عرض تقرير حادثة','Viewed incident report'), target:i.ref});
}
async function rsAuthority(i){
  const c=await api('response/contacts').catch(()=>({contacts:[]}));
  const brief=[TX(`المنشأة: صون · ${AR(i.zone)}`,`Facility: SAWN · ${i.zone}`),TX(`ماذا: ${incTitleT(i)} (${i.ref})`,`What: ${incTitleT(i)} (${i.ref})`),TX(`متى: ${audTime(i.createdAt)}`,`When: ${audTime(i.createdAt)}`),TX(`الخطورة: ${SEV_T()[i.sev]}`,`Severity: ${SEV_T()[i.sev]}`),TX(`التفاصيل: ${i.reason?incReasonT(i):'—'}`,`Details: ${i.reason?incReasonT(i):'—'}`)];
  const list=(c.contacts||[]);
  showInfo(TX(`إبلاغ جهة خارجية · ${i.ref}`,`Notify an authority · ${i.ref}`),`${list.length?xl(list.map(x=>({t:ARh(x.agency),s:esc_(x.note||''),e:x.phone?`<span class="num" dir="ltr">${esc_(x.phone)}</span>`:''}))):''}<div class="sub-h">${TX('نص البلاغ','Brief')}</div><div class="rcard" id="auBrief">${brief.map(b=>`<div>${esc_(b)}</div>`).join('')}</div>
    <form class="mform" id="auF"><label class="mf"><span>${TX('الجهة التي تم التواصل معها','Authority contacted')}</span><input class="inp" name="agency" list="auList" required maxlength="80"><datalist id="auList">${list.map(x=>`<option value="${esc_(x.agency)}">`).join('')}</datalist></label><label class="mf"><span>${TX('رقم البلاغ لديهم','Their reference')}</span><input class="inp" name="reference" maxlength="60"></label><label class="mf"><span>${TX('ملاحظة','Note')}</span><textarea class="inp" name="note" rows="2" maxlength="500"></textarea></label><div class="row-c" style="gap:6px"><button class="btn" type="button" id="auCopy">${TX('نسخ النص','Copy brief')}</button><button class="btn pri" type="submit">${TX('تسجيل البلاغ','Record notification')}</button></div></form>`);
  const w=document.querySelector('.core-ask');
  w.querySelector('#auCopy').onclick=()=>navigator.clipboard.writeText(w.querySelector('#auBrief').innerText).then(()=>toast(TX('تم النسخ','Copied')),()=>toast(TX('النسخ غير متاح هنا','Copy not available')));
  w.querySelector('#auF').onsubmit=async e=>{ e.preventDefault(); const f=new FormData(e.target); const r=await act(api(`incidents/${i.ref}/authority`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))}),TX('سُجّل البلاغ في ملف الحادثة','Recorded in the incident file')); if(r) w.remove(); };
}
function bindResponseCore(C){
  C.querySelectorAll('[data-rsf]').forEach(b=>b.onclick=()=>{rsF=b.dataset.rsf; render();});
  C.querySelectorAll('[data-rs]').forEach(r=>{const f=()=>{rsSel=r.dataset.rs; render();}; r.onclick=f; r.onkeydown=e=>{if(e.key==='Enter') f();};});
  const i=rsSel&&LIVE.inc.find(x=>x.ref===rsSel); if(!i) return;
  const refresh=()=>{pgDrop('rs'); coreRefresh(false);};
  const tm=C.querySelector('#rsTeam'); if(tm) tm.onchange=()=>act(api(`incidents/${i.ref}/route`,{method:'POST',body:JSON.stringify({team:tm.value})}),TX('تم تغيير الفريق','Team changed')).then(refresh);
  C.querySelectorAll('[data-tk]').forEach(b=>b.onclick=async()=>{ const a=b.dataset.tk; let note='';
    if(a==='decline'||a==='resolved'){ const r=await askForm(a==='decline'?TX('سبب الاعتذار (يعيد المشرف الإسناد)','Why (the supervisor reassigns it)'):TX('ما الذي تم (اختياري)','What was done (optional)'),[{name:'note',label:TX('ملاحظة','Note'),type:'textarea',required:a==='decline'}]); if(!r) return; note=r.note; }
    act(api(`incidents/${i.ref}/task`,{method:'POST',body:JSON.stringify({action:a,note})}),TX('تم التحديث','Updated')).then(refresh); });
  const as=C.querySelector('#rsAssign'); if(as) as.onclick=async()=>{ const pp=(await api('response/responders').catch(()=>({responders:[]}))).responders||[]; const TM=TEAM_T();
    if(!pp.length){ toast(TX('لا يوجد مستجيبون نشطون','No active responders')); return; }
    const r=await askForm(TX(`إسناد ${i.ref}`,`Assign ${i.ref}`),[{name:'username',label:TX('المستجيب','Responder'),type:'select',options:pp.map(x=>[x.username,`${esc_(x.displayName)} (${esc_(x.username)})${x.team?' · '+(TM[x.team]||x.team):''}`]),value:i.assignee||pp[0].username}],TX('إسناد','Assign'));
    if(r) act(api(`incidents/${i.ref}/assign`,{method:'POST',body:JSON.stringify({username:r.username})}),TX('تم الإسناد','Assigned')).then(refresh); };
  const rp=C.querySelector('#rsReport'); if(rp) rp.onclick=()=>rsReport(i.ref);
  const au=C.querySelector('#rsAuth'); if(au) au.onclick=()=>rsAuthority(i);
}
CORE_VIEWS.response={v:vResponseCore, b:bindResponseCore};

