const devPend = (set,d) => set.has(`${d.protocol} ${d.id}`);
const NEAR = n => !n?'—':/very close/.test(n)?TX('قريب جداً (1 إلى 3 م)','very close (1–3 m)'):/same room/.test(n)?TX('نفس الغرفة (3 إلى 8 م)','same room (3–8 m)'):/nearby/.test(n)?TX('قريب (8 إلى 20 م)','nearby (8–20 m)'):TX('بعيد (أكثر من 20 م)','far (20 m+)');
