  watch:'<rect x="-3" y="-3" width="6" height="6" rx="1.7"/><path d="M-1.6 -3v-2.3h3.2v2.3M-1.6 3v2.3h3.2v-2.3M0 -1.3v1.3l1 .8"/>',
  wearable:'<rect x="-3" y="-3" width="6" height="6" rx="1.7"/><path d="M-1.6 -3v-2.3h3.2v2.3M-1.6 3v2.3h3.2v-2.3"/>',
  audio:'<circle cx="-2.8" cy="2.2" r="1.9"/><circle cx="2.8" cy="2.2" r="1.9"/><path d="M-4.7 2.2v-3a4.7 4.7 0 0 1 9.4 0v3"/>',
