  hotspot:'<path d="M-5 -1a7 7 0 0 1 10 0M-3 1.5a4 4 0 0 1 6 0"/><circle cx="0" cy="3.7" r=".8"/>',
  iot:'<path d="M-4.6 1L0 -4.6 4.6 1v4.2h-9.2z"/>',
  accessory:'<rect x="-5" y="-3" width="10" height="6" rx="1"/><path d="M-3 -1h.1M0 -1h.1M3 -1h.1M-2 1.5h4"/>',
  drone:'<circle cx="-4" cy="-4" r="1.5"/><circle cx="4" cy="-4" r="1.5"/><circle cx="-4" cy="4" r="1.5"/><circle cx="4" cy="4" r="1.5"/><path d="M-2.7 -2.7L2.7 2.7M2.7 -2.7L-2.7 2.7"/><rect x="-1.6" y="-1.6" width="3.2" height="3.2" rx=".6"/>',
  camera:'<rect x="-5" y="-2.8" width="10" height="7" rx="1.2"/><circle cx="0" cy=".7" r="2"/><path d="M-3.4 -2.8l1-1.7h2.8l1 1.7"/>',
  glasses:'<circle cx="-2.7" cy="1" r="2.2"/><circle cx="2.7" cy="1" r="2.2"/><path d="M-.5 1h1M-4.9 -.4l1-.9M4.9 -.4l-1-.9"/>',
  attacktool:'<path d="M1 -5.6L-3.8 1H0l-1.2 5.6L3.8 -.4H0z"/>',
  devboard:'<rect x="-3.4" y="-3.4" width="6.8" height="6.8" rx=".8"/><path d="M-3.4 -1.4h-2M-3.4 1.4h-2M3.4 -1.4h2M3.4 1.4h2M-1.4 -3.4v-2M1.4 -3.4v-2M-1.4 3.4v2M1.4 3.4v2"/>',
  medical:'<path d="M-1.5 -4.6h3v3h3v3h-3v3h-3v-3h-3v-3h3z"/>',
  vehicle:'<path d="M-5 1.4l1.2-3.4a1.5 1.5 0 0 1 1.4-1h4.8a1.5 1.5 0 0 1 1.4 1L5 1.4v2.6h-10z"/><circle cx="-2.6" cy="4" r="1.1"/><circle cx="2.6" cy="4" r="1.1"/>',
