const DVI_DEFS = Object.entries(DVI).map(([k,p])=>`<symbol id="dvi-${k}" viewBox="-6 -6 12 12">${p}</symbol>`).join('');
const dviId = t => (t && DVI[t]) ? t : 'unknown';
function liveRadar(list){
  const cx=300,cy=210, rOf=rssi=>!Number.isFinite(rssi)?195:Math.max(18,Math.min(195,(-35-rssi)*4.2));
  const A=AIRX(), zw=A?A.zoneFor('Wi-Fi'):-65;
  return `<svg class="mrad" viewBox="0 0 600 420" role="img" aria-label="${TX('خريطة الأجهزة','Device map')}">
    <defs>${DVI_DEFS}</defs>
    ${[[-55,TX('1 إلى 3 م','1–3 m')],[-67,TX('3 إلى 8 م','3–8 m')],[-80,TX('8 إلى 20 م','8–20 m')]].map(([v,t])=>`<circle class="rr" cx="${cx}" cy="${cy}" r="${rOf(v)}"/><text class="rl" x="${cx+rOf(v)*0.72}" y="${cy+rOf(v)*0.72}">${t}</text>`).join('')}
    <circle class="gz" cx="${cx}" cy="${cy}" r="${rOf(zw)}"/><text class="gzt" x="${cx+rOf(zw)*0.6}" y="${cy-rOf(zw)-6}">${TX('منطقة البوابة','Gate zone')}</text>
    <circle class="rping" cx="${cx}" cy="${cy}" r="14"/><circle class="rping rping2" cx="${cx}" cy="${cy}" r="14"/>
    <rect class="esp" x="${cx-22}" y="${cy-9}" width="44" height="18" rx="4"/><text class="espt num" x="${cx}" y="${cy+4}">AS-1</text>
    ${(()=>{const pend=devPendSet();
      const pts=list.map(d=>{const a=hashA(d.id)*Math.PI/180, r=rOf(d.rssi), x=cx+r*Math.cos(a), y=cy+r*Math.sin(a), pd=devPend(pend,d), st=pd?'pend':d.status==='AUTHORIZED'?'auth':d.status==='VERIFIED_UNAUTHORIZED'?'bad':'unk', sel=axSel===d.key, rr=sel?11:8.5;
        const full=AR(String(d.name||d.typeLabel||'')), short=full.length>24?full.slice(0,23)+'…':full;
        return {d,x,y,st,sel,rr,full,short,r};});
      /* labels never overlap: highest priority first (selected, unauthorized, closest), above the dot, else below, else hidden (name stays on hover/selection) */
      const placed=[], boxOf=(p,above)=>{const w=p.short.length*6.2+6, h=13, ty=above?p.y-p.rr-4:p.y+p.rr+12; return {x0:p.x-w/2,x1:p.x+w/2,y0:ty-11,y1:ty+2,ty};};
      const hit=b=>placed.some(o=>b.x0<o.x1&&b.x1>o.x0&&b.y0<o.y1&&b.y1>o.y0)||pts.some(q=>Math.hypot(q.x-Math.max(b.x0,Math.min(q.x,b.x1)),q.y-Math.max(b.y0,Math.min(q.y,b.y1)))<q.rr-1);
      const rank=p=>(p.sel?0:p.st==='bad'?1:p.st==='pend'?2:p.st==='unk'?3:9)*1000+p.r;
      pts.filter(p=>(p.sel||p.st!=='auth')&&p.short).sort((a,b)=>rank(a)-rank(b)).forEach(p=>{for(const above of [true,false]){const b=boxOf(p,above); if(b.x0>2&&b.x1<598&&b.y0>2&&b.y1<418&&!hit(b)){placed.push(b); p.ty=b.ty; break;}}});
      return pts.map(p=>{const {d,x,y,st,sel,rr}=p, g=rr*0.95;
      return `<g class="dv ${st}${sel?' sel':''}" data-ax="${esc_(d.key)}" tabindex="0" role="button" aria-label="${esc_(p.full)}"><title>${esc_(p.full)}</title><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${rr}" ${d.randomized?'class="rnd"':''}/><use href="#dvi-${dviId(d.type)}" class="dvi" x="${(x-g).toFixed(1)}" y="${(y-g).toFixed(1)}" width="${(g*2).toFixed(1)}" height="${(g*2).toFixed(1)}"/>${p.ty!=null?`<text x="${x.toFixed(1)}" y="${p.ty.toFixed(1)}">${esc_(p.short)}</text>`:''}</g>`;}).join('');})()}
  </svg>`;
}
// Top-view aircraft silhouette (nose up / north), drawn at the plane's position and rotated by its track.
const PLANE='M0 -9 L1.4 -3.2 L9 1 L9 2.7 L1.4 1.3 L1.4 5.2 L4 7.2 L4 8.6 L0 7.4 L-4 8.6 L-4 7.2 L-1.4 5.2 L-1.4 1.3 L-9 2.7 L-9 1 L-1.4 -3.2 Z';
function airPlot(T){
  const cx=300,cy=200, s=T&&T.site, R=axRange*1000, S=185/R;
  const z=(T&&T.zones)||{}, ring=(m,c,t)=>m&&m<=R?`<circle class="${c}" cx="${cx}" cy="${cy}" r="${(m*S).toFixed(1)}"/><text class="rzt" x="${cx}" y="${(cy-m*S+12).toFixed(1)}">${t}</text>`:'';
  const pts=((T&&T.list)||[]).filter(a=>a.distanceM<=R&&s).map(a=>{const dy=(a.lat-s.lat)*111320, dx=(a.lon-s.lon)*111320*Math.cos(s.lat*Math.PI/180), x=cx+dx*S, y=cy-dy*S, thr=a.emergency?'crit':a.distanceM<=(z.restrictedM||5000)&&(a.altitudeFt??99999)<=(z.ceilingFt||3000)?'crit':a.distanceM<=(z.warningM||10000)?'high':'low';
    return `<g class="ac ${thr}${a.hex===axAcSel?' sel':''}" data-ac="${esc_(a.hex)}" tabindex="0" role="button" aria-label="${esc_(a.callsign||a.hex)}"><path class="plane" d="${PLANE}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${a.track||0})"/><text x="${(x+11).toFixed(1)}" y="${(y-6).toFixed(1)}" class="num">${esc_(a.callsign||a.hex)}</text><text x="${(x+11).toFixed(1)}" y="${(y+7).toFixed(1)}" class="num sub">${a.altitudeFt??'—'} ft</text></g>`;}).join('');
  return `<svg class="mrad air" viewBox="0 0 600 400" role="img" aria-label="${TX('الصورة الجوية','Air picture')}">
    ${ring(z.restrictedM,'rz',TX('مجال مقيّد','Restricted'))}${ring(z.warningM,'rr',TX('تحذير','Warning'))}${ring(z.monitorM,'rr',TX('مراقبة','Monitor'))}
    <text class="nN num" x="${cx}" y="14">N</text><circle class="rping" cx="${cx}" cy="${cy}" r="16"/><circle class="rping rping2" cx="${cx}" cy="${cy}" r="16"/><rect class="esp" x="${cx-16}" y="${cy-8}" width="32" height="16" rx="4"/><text class="espt num" x="${cx}" y="${cy+4}">SITE</text>${pts}</svg>
    <div class="mrng">${[5,10,25,50].map(k=>`<button data-axr="${k}" aria-pressed="${axRange===k}"><span class="num">${k}</span> ${TX('كم','km')}</button>`).join('')}</div>`;
}
// Drone radar: drones plotted around the site by their Remote-ID position, each linked to its operator (pilot) marker.
function droneRadar(T){
  const cx=300,cy=210, s=T&&T.site, drs=((T&&T.drones)||[]);
  const dists=[(s&&s.radiusM)||0]; drs.forEach(d=>{const r=d.remoteId; if(Number.isFinite(d.distance))dists.push(d.distance); if(d.pilot&&Number.isFinite(d.pilot.distanceToSiteM))dists.push(d.pilot.distanceToSiteM);});
  const maxM=Math.max(500,...dists)*1.18, R=185, S=R/maxM;
  const pos=(lat,lon)=>(!s||!Number.isFinite(lat)||!Number.isFinite(lon))?null:[cx+((lon-s.lon)*111320*Math.cos(s.lat*Math.PI/180))*S, cy-((lat-s.lat)*111320)*S];
  const ring=(m,c,t)=>m&&m<=maxM?`<circle class="${c}" cx="${cx}" cy="${cy}" r="${(m*S).toFixed(1)}"/>${t?`<text class="rzt" x="${cx}" y="${(cy-m*S+12).toFixed(1)}">${t}</text>`:''}`:'';
  const rr=[maxM*0.33,maxM*0.66].map(m=>`<circle class="rr" cx="${cx}" cy="${cy}" r="${(m*S).toFixed(1)}"/>`).join('');
  const marks=drs.map((d,i)=>{const r=d.remoteId||{}; const dp=pos(r.lat,r.lon)||[cx,cy]; const pp=d.pilot?pos(d.pilot.lat,d.pilot.lon):null; const selx=axDrSel===d.key; const nm=esc_(r.uasId||d.name||d.identifier);
    return `${pp?`<line class="drlink" x1="${dp[0].toFixed(1)}" y1="${dp[1].toFixed(1)}" x2="${pp[0].toFixed(1)}" y2="${pp[1].toFixed(1)}"/>`:''}
      ${pp?`<g class="pilot${selx?' sel':''}" data-dr="${esc_(d.key)}" tabindex="0" role="button" aria-label="${TX('مشغّل','operator')} ${nm}"><circle cx="${pp[0].toFixed(1)}" cy="${pp[1].toFixed(1)}" r="7"/><use href="#dvi-op" x="${(pp[0]-5).toFixed(1)}" y="${(pp[1]-5).toFixed(1)}" width="10" height="10"/><text x="${pp[0].toFixed(1)}" y="${(pp[1]+18).toFixed(1)}">${TX('المشغّل','Operator')}</text></g>`:''}
      <g class="drn${selx?' sel':''}" data-dr="${esc_(d.key)}" tabindex="0" role="button" aria-label="${TX('مسيّرة','drone')} ${nm}"><circle class="dco" cx="${dp[0].toFixed(1)}" cy="${dp[1].toFixed(1)}" r="${selx?11:9}"/><use href="#dvi-drone" x="${(dp[0]-7).toFixed(1)}" y="${(dp[1]-7).toFixed(1)}" width="14" height="14"/><circle class="drping" cx="${dp[0].toFixed(1)}" cy="${dp[1].toFixed(1)}" r="12"/><text x="${dp[0].toFixed(1)}" y="${(dp[1]-15).toFixed(1)}">${nm}${Number.isFinite(d.distance)?` · ${d.distance} م`:''}</text></g>`;}).join('');
  return `<svg class="mrad drad" viewBox="0 0 600 420" role="img" aria-label="${TX('رادار المسيّرات','Drone radar')}"><defs>${DVI_DEFS}<symbol id="dvi-op" viewBox="-6 -6 12 12"><circle cx="0" cy="-2.3" r="2.1"/><path d="M-3.6 5c.5-2.6 2-3.9 3.6-3.9s3.1 1.3 3.6 3.9"/></symbol></defs>
    ${rr}${ring((s&&s.radiusM)||0,'rz',TX('حدود الموقع','Site boundary'))}
    <text class="nN num" x="${cx}" y="14">N</text><circle class="rping" cx="${cx}" cy="${cy}" r="16"/><circle class="rping rping2" cx="${cx}" cy="${cy}" r="16"/><rect class="esp" x="${cx-16}" y="${cy-8}" width="32" height="16" rx="4"/><text class="espt num" x="${cx}" y="${cy+4}">SITE</text>
    ${marks||`<text class="rl" x="${cx}" y="${cy+R*0.6}" text-anchor="middle">${TX('لا توجد مسيّرات مرصودة الآن','No drones detected now')}</text>`}</svg>`;
}
// Wi-Fi strength bars from an RSSI value.
const sigBars=rssi=>{const n=!Number.isFinite(rssi)?0:rssi>=-50?4:rssi>=-65?3:rssi>=-80?2:1; return `<span class="sigb" title="${Number.isFinite(rssi)?rssi+' dBm':''}">${[1,2,3,4].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</span>`;};
// A small RF waveform strip for a radio sensor (stable per sensor; taller/red when a check is alerting).
function rfStrip(s){
  const l=s.last||{}, alert=Object.values(s.checks||{}).some(v=>v==='alert'); let seed=hashA(s.sensorId)+1;
  const amp=alert?11:s.learning?3:4+Math.min(6,Math.abs((l.noise??-90)+90)/3), n=46;
  const pts=Array.from({length:n},(_,i)=>{seed=(seed*1103515245+12345)&0x7fffffff; const y=14+((seed%1000)/1000-0.5)*amp*2; return `${(i/(n-1)*120).toFixed(1)},${y.toFixed(1)}`;}).join(' ');
  return `<svg class="rfstrip${alert?' al':''}" viewBox="0 0 120 28" preserveAspectRatio="none" aria-hidden="true"><polyline points="${pts}"/></svg>`;
}
function skyLive(S){
  const P=(az,el)=>{const r=88*(1-el/90), a=(az-90)*Math.PI/180; return [100+r*Math.cos(a),100+r*Math.sin(a)];};
  return `<svg class="msky" viewBox="0 0 200 200"><circle cx="100" cy="100" r="88" class="rr"/><circle cx="100" cy="100" r="58" class="rr"/><circle cx="100" cy="100" r="28" class="rr"/><path d="M100 12V188M12 100H188" class="ax"/>${['N','E','S','W'].map((t,i)=>`<text class="num" x="${[100,194,100,6][i]}" y="${[9,104,198,104][i]}">${t}</text>`).join('')}
  ${((S&&S.sky)||[]).filter(x=>x.imaging).slice(0,24).map(x=>{const [a,b]=P(x.az,x.el); const on=(S.overhead||[]).includes(x.name); return `<circle cx="${a.toFixed(1)}" cy="${b.toFixed(1)}" r="${on?4:2.5}" class="sp ${on?'on':''}"/>${on?`<text x="${(a+6).toFixed(1)}" y="${(b-4).toFixed(1)}" class="sl num">${esc_(x.name)}</text>`:''}`;}).join('')}</svg>`;
}
const hmClock=t=>{const d=new Date(t),q=n=>String(n).padStart(2,'0');return q(d.getHours())+':'+q(d.getMinutes());};
const hDur=ms=>{const m=Math.round(ms/60000);return m<1?'<1 '+TX('د','m'):m<60?m+' '+TX('د','m'):Math.floor(m/60)+' '+TX('س','h')+' '+(m%60)+' '+TX('د','m');};
function airHistoryView(AC){
  const span=(AIR_HRANGES.find(r=>r[0]===axHRange)||AIR_HRANGES[1])[2], now=Date.now();
  const key=`histA-${axHRange}-${axHAlerts?1:0}-${axHQ}`;
  const path=`airspace/history/aircraft?from=${now-span}&to=${now}${axHAlerts?'&only=alerts':''}${axHQ?'&q='+encodeURIComponent(axHQ):''}`;
  const d=pgLoad(key,[path]), H=d&&d[0]&&!d[0].__err?d[0]:null;
  const site=(AC&&AC.site)||(LIVE.thr&&LIVE.thr.site), zones=(AC&&AC.zones)||{};
  const sel=axRepKind==='air'&&axRepId!=null;
  let rd={kind:'air',det:null,title:'',site,zones};
  if(sel){ const dd=pgLoad(`repA-${axRepId}`,[`airspace/history/aircraft/${axRepId}`]); const det=dd&&dd[0]&&!dd[0].__err?dd[0]:null; if(det){ rd={kind:'air',id:axRepId,det,title:det.callsign||det.registration||(det.hex||'').toUpperCase(),site,zones}; repData=rd; } }
  const mapCard=mp(TX('الصورة الجوية — إعادة تشغيل المسار','Air picture — path replay')+(sel&&repData&&repData.title?` · <span class="num" dir="ltr">${esc_(repData.title)}</span>`:''),`<div class="rep-map-wrap"><svg class="mrad air rep-map" id="axRepSvg" viewBox="0 0 600 400" role="img" aria-label="${TX('إعادة تشغيل المسار','Path replay')}">${airReplayInner(rd,sel?axRepPos:0)}</svg></div>${sel&&repData&&repData.det?repAirFacts(repData.det):''}${sel?repControls():`<div class="muted-s" style="text-align:center;padding:8px">${TX('اختر رحلة من السجل أدناه لإعادة تشغيل مسارها على هذه الخريطة','Pick a flight below to replay its path on this map')}</div>`}`,'','flush','radar');
  const flt=`<div class="mflt"><select id="axHRange" aria-label="${TX('الفترة','Time range')}">${AIR_HRANGES.map(([v,t])=>`<option value="${v}" ${axHRange===v?'selected':''}>${t()}</option>`).join('')}</select><input type="search" id="axHQ" placeholder="${TX('نداء أو ICAO أو تسجيل…','Callsign, ICAO, registration…')}" value="${esc_(axHQ)}"><label class="mck"><input type="checkbox" id="axHAlerts" ${axHAlerts?'checked':''}> ${TX('التنبيهات فقط','Alerts only')}</label></div>`;
  const rows=H?H.list.map(a=>`<tr class="${axRepKind==='air'&&String(axRepId)===String(a.id)?'sel':''}" data-ha="${esc_(a.id)}" tabindex="0"><td class="num"><b dir="ltr">${esc_(a.callsign||a.hex)}</b> <span class="muted-s">${esc_(a.registration||'')}</span></td><td class="num">${esc_(a.type||'—')}</td><td class="num" dir="ltr">${hmClock(a.firstSeen)}–${hmClock(a.lastSeen)}</td><td class="num">${hDur(a.lastSeen-a.firstSeen)}</td><td class="num">${Number.isFinite(a.minDistanceM)?(a.minDistanceM/1000).toFixed(1)+' '+TX('كم','km'):'—'}</td><td>${a.restricted?XB('no',TX('دخل المقيّد','restricted')):(a.level==='warning'||a.level==='high')?XB('open',esc_(a.level)):XB('ok',TX('عادي','normal'))} ${ico('play',12)}</td></tr>`).join(''):'';
  const tableCard=mp(TX('سجل زيارات الطائرات','Aircraft visit history')+(H?` <span class="muted-s"><span class="num">${H.list.length}</span></span>`:''),flt+`<table class="tbl"><thead><tr><th>${TX('النداء','Callsign')}</th><th>${TX('النوع','Type')}</th><th>${TX('الفترة','Window')}</th><th>${TX('المدة','Duration')}</th><th>${TX('أقرب','Closest')}</th><th>${TX('الحالة','Level')}</th></tr></thead><tbody>${rows||emptyRow(6,H?TX('لا توجد طائرات في هذه الفترة. تُحفظ الزيارات من الآن عند رصد طائرة ضمن 50 كم','No aircraft in this period. Visits are stored from now on'):TX('جارٍ التحميل…','Loading…'))}</tbody></table>`,H?`<span class="muted-s">${TX('اختر رحلة لإعادة تشغيل مسارها على الخريطة · يُحفظ 30 يوماً','Pick a flight to replay its path on the map · kept 30 days')}</span>`:'','flush','radar');
  return mapCard+tableCard;
}
function spaceHistoryView(SP){
  const D=864e5, now=Date.now(), end=now-axSatDay*D;
  const key=`histS-${axSatDay}-${axSatAll?1:0}`;
  const path=`airspace/history/satellites?from=${end-D}&to=${end}${axSatAll?'&all=1':''}`;
  const d=pgLoad(key,[path]), H=d&&d[0]&&!d[0].__err?d[0]:null;
  const days=Array.from({length:7},(_,i)=>[String(i), i===0?TX('آخر 24 ساعة','Last 24 hours'):i===1?TX('اليوم السابق','The day before'):TX(`قبل ${i}–${i+1} يوم`,`${i}–${i+1} days ago`)]);
  repSatPasses=H?H.passes:[];
  const sel=axRepKind==='sat'&&axRepId!=null;
  const pass=sel?repSatPasses.find(x=>x.norad+'|'+x.aos===axRepId)||(repData&&repData.pass):null;
  if(sel&&pass&&(!repData||repData.id!==axRepId)) repData={kind:'sat',id:axRepId,pass,title:pass.name};
  const mapCard=mp(TX('مخطط السماء — إعادة تشغيل العبور','Sky chart — pass replay')+(sel&&pass?` · <span class="num">${esc_(pass.name)}</span>`:''),`<div class="rep-map-wrap sat"><svg class="mrad rep-map" id="axRepSvg" viewBox="0 0 300 300" role="img" aria-label="${TX('إعادة تشغيل العبور','Pass replay')}">${satReplayInner(pass,sel?axRepPos:0)}</svg></div>${sel&&pass?repSatFacts(pass)+repControls():`<div class="muted-s" style="text-align:center;padding:8px">${TX('اختر عبوراً من السجل أدناه لإعادة تشغيله على هذا المخطط','Pick a pass below to replay it on this chart')}</div>`}`,'','flush','sat');
  const flt=`<div class="mflt"><select id="axSatDay" aria-label="${TX('اليوم','Day')}">${days.map(([v,t])=>`<option value="${v}" ${String(axSatDay)===v?'selected':''}>${t}</option>`).join('')}</select><select id="axSatAll" aria-label="${TX('الأقمار','Satellites')}"><option value="0" ${!axSatAll?'selected':''}>${TX('أقمار التصوير','Imaging satellites')}</option><option value="1" ${axSatAll?'selected':''}>${TX('كل الأقمار المتتبّعة','All tracked satellites')}</option></select></div>`;
  const rows=H?H.passes.map(x=>`<tr class="${axRepKind==='sat'&&axRepId===x.norad+'|'+x.aos?'sel':''}" data-hs="${x.norad}|${x.aos}" tabindex="0"><td class="num"><b>${esc_(x.name)}</b> <span class="muted-s">NORAD ${x.norad}${x.imaging?' · '+TX('تصوير','imaging'):''}</span></td><td class="num" dir="ltr">${hmClock(x.aos)}–${hmClock(x.los)}</td><td class="num">${hDur(x.los-x.aos)}</td><td class="num">${x.maxElevationDeg}°</td><td>${x.alert?XB('open',esc_(x.alert.ref||String(x.alert.id))):`<span class="muted-s">${ico('play',12)}</span>`}</td></tr>`).join(''):'';
  const tableCard=mp(TX('سجل عبور الأقمار','Satellite pass history')+(H?` <span class="muted-s"><span class="num">${H.passes.length}</span></span>`:''),flt+`<table class="tbl"><thead><tr><th>${TX('القمر','Satellite')}</th><th>${TX('الشروق والغروب','Rise and set')}</th><th>${TX('المدة','Duration')}</th><th>${TX('أقصى ارتفاع','Max elevation')}</th><th>${TX('إنذار','Alert')}</th></tr></thead><tbody>${rows||emptyRow(5,H?(H.note?esc_(H.note):TX('لا توجد عبورات في هذه الفترة','No passes in this period')):TX('جارٍ الحساب…','Computing…'))}</tbody></table>`,H?`<span class="muted-s">${TX('اختر عبوراً لإعادة تشغيله على مخطط السماء','Pick a pass to replay it on the sky chart')}</span>`:'','flush','sat');
  return mapCard+tableCard;
}
/* Drones & radio history: every drone and radio-attack detection from the incident log. A row opens its
   details and replays it: the drone's path and its pilot (Remote ID), or its signal strength over time. */
const DH_SCEN=/^air-(?!unknown)/;
function droneHistoryView(){
  const inc=(LIVE.inc||[]).filter(i=>DH_SCEN.test(i.scenario||'')).sort((a,b)=>b.createdAt-a.createdAt).slice(0,100);
  const sel=axRepKind==='drone'?inc.find(i=>String(i.id)===String(axRepId)):null;
  let det='';
  if(sel){
    const A=sel.airspace||{}, key=A.protocol&&A.identifier?`${A.protocol}|${A.identifier}`:'';
    const from=sel.createdAt-5*60000, to=Math.min(Date.now(),Math.max(sel.lastSeenAt||0,sel.updatedAt||0,sel.createdAt)+5*60000);
    const dd=key?pgLoad(`droneT-${sel.id}`,[`airspace/history/drone?key=${encodeURIComponent(key)}&from=${from}&to=${Math.max(to,from+60000)}`]):null;
    const T=dd&&dd[0]&&!dd[0].__err?dd[0]:null;
    const site=(LIVE.thr&&LIVE.thr.site)||{lat:24.7136,lon:46.6753,radiusM:500};
    if(!repData||repData.kind!=='drone'||repData.id!==sel.id||(T&&repData.points!==T.points)) repData={kind:'drone',id:sel.id,inc:sel,points:T?T.points:null,site,title:A.name||sel.type};
    const R=(sel.drone&&sel.drone.remoteId)||null, P=sel.pilot||(sel.drone&&sel.drone.pilot)||null;
    const gm=(lat,lon)=>`<a href="https://www.google.com/maps?q=${lat},${lon}" target="_blank" rel="noopener noreferrer" class="num" dir="ltr">${(+lat).toFixed(6)}, ${(+lon).toFixed(6)}</a>`;
    const pts=(T&&T.points)||[], last=[...pts].reverse().find(p=>Number.isFinite(p[1]));
    const facts=kv([
      [TX('النوع','Type'),esc_(AR(sel.type)||sel.type||'—')],
      [TX('الجهاز','Device'),esc_(A.name||'—')],
      [TX('المعرّف','Identifier'),`<span class="num" dir="ltr">${esc_(A.identifier||'—')}</span> · ${esc_(A.protocol||'')}`],
      [TX('طريقة الرصد','How detected'),esc_(AR((sel.ev||[])[0])||(sel.ev||[])[0]||'—')],
      [TX('الإشارة','Signal'),Number.isFinite(A.rssi)?`<span class="num">${A.rssi} dBm</span>`:'—'],
      [TX('الحسّاس','Sensor'),`<span class="num">${esc_(A.sensorId||'—')}</span>`],
      [TX('أول رصد','First seen'),`<span class="num">${dShort(sel.createdAt)} ${hmsClock(sel.createdAt)}</span>`],
      [TX('آخر رصد','Last seen'),`<span class="num">${hmsClock(sel.lastSeenAt||sel.updatedAt||sel.createdAt)}</span>`],
      ...(R&&R.uasId?[[TX('رقم الطائرة (Remote ID)','Drone ID (Remote ID)'),`<span class="num" dir="ltr">${esc_(R.uasId)}</span>`]]:[]),
      ...(last?[[TX('آخر موقع للمسيّرة','Last drone position'),gm(last[1],last[2])+(Number.isFinite(last[3])?` · <span class="num">${Math.round(last[3])} m</span>`:'')]]:R&&Number.isFinite(R.lat)?[[TX('موقع المسيّرة','Drone position'),gm(R.lat,R.lon)]]:[]),
      ...(last&&Number.isFinite(last[6])?[[TX('موقع الطيّار','Pilot position'),gm(last[6],last[7])]]:P&&Number.isFinite(P.lat)?[[TX('موقع الطيّار','Pilot position'),gm(P.lat,P.lon)]]:[]),
      [TX('الحالة','State'),XB((INC_ST[sel.status]||['mut'])[0],AR((INC_ST[sel.status]||[0,sel.status])[1])||sel.status)],
    ]);
    const tl=(sel.tl||[]).slice(-8).map(([t,x])=>`<li><span class="num">${hmsClock(t)}</span> ${esc_(AR(x)||x)}</li>`).join('');
    const note=!key?TX('لا يوجد معرّف جهاز لهذا الرصد — لا مسار له','This detection has no device identifier — no track')
      :!T?TX('جارٍ تحميل المسار…','Loading the track…')
      :!pts.length?TX('لا يوجد مسار محفوظ لهذا الرصد (المسارات تُحفظ من الآن)','No track was recorded for this detection (tracks are kept from now on)')
      :pts.some(p=>Number.isFinite(p[1]))?TX('المسار من Remote ID · الخط المتقطع يصل الطيّار بالمسيّرة','Path from Remote ID · the dashed line links the pilot to the drone')
      :TX('بدون Remote ID: قوة الإشارة مع الزمن (أقرب = أقوى)','No Remote ID: signal strength over time (closer = stronger)');
    det=mp(TX('إعادة تشغيل الرصد','Detection replay')+` · <span class="num" dir="ltr">${esc_(sel.ref||'')}</span>`,
      `<div class="rep-map-wrap"><svg class="mrad air rep-map" id="axRepSvg" viewBox="0 0 600 400" role="img" aria-label="${TX('إعادة تشغيل الرصد','Detection replay')}">${droneReplayInner(repData,axRepPos)}</svg></div>${pts.length?repControls():''}<p class="muted-s" style="margin:8px 14px">${note}</p>`
      +`<div class="rep-facts">${facts}</div>${tl?`<ol class="dh-tl">${tl}</ol>`:''}`,`<button class="btn sm" id="axRepClose">${TX('إغلاق','Close')}</button>`,'','radar');
  }
  const rows=inc.map(i=>{const st=INC_ST[i.status]||['mut',i.status], A=i.airspace||{}; return `<tr class="${sel&&sel.id===i.id?'sel':''}" data-hd="${esc_(String(i.id))}" tabindex="0" style="cursor:pointer"><td class="num" dir="ltr">${esc_(i.ref||'')}</td><td>${esc_(AR(i.type)||i.type||'—')}${A.name?` <span class="muted-s">${esc_(A.name)}</span>`:''}</td><td>${tg(i.sev==='crit'?'crit':i.sev==='high'?'no':'open',AR(i.sev)||i.sev||'—')}</td><td class="num">${dShort(i.createdAt)} ${hmClock(i.createdAt)}</td><td>${XB(st[0],AR(st[1])||st[1])}</td></tr>`;}).join('');
  return det+mp(TX('سجل المسيّرات والراديو','Drones & radio history')+` <span class="muted-s"><span class="num">${inc.length}</span></span>`,`<p class="muted-s" style="margin:8px 14px">${TX('اضغط على أي سطر لعرض تفاصيله وإعادة تشغيل مساره','Click a row to see its details and replay its track')}</p><table class="tbl"><thead><tr><th>${TX('المرجع','Ref')}</th><th>${TX('النوع','Type')}</th><th>${TX('الخطورة','Severity')}</th><th>${TX('الوقت','Time')}</th><th>${TX('الحالة','State')}</th></tr></thead><tbody>${rows||emptyRow(5,TX('لا توجد رصود مسيّرات أو راديو','No drone or radio detections'))}</tbody></table>`,'','flush','radar');
}
/* What the sensor knows about a live drone besides Remote ID: its maker and model (from its name and its
   radio's company code), its address, how near it probably is (from signal strength only), whether it is
   coming closer (signal over the last 10 minutes, recorded by the platform) and how long it has been there. */
function droneSignalFacts(d){
  const name=String(d.name||''), m=/^DJI[-_ ]?([A-Za-z]+\d*[A-Za-z]*)/i.exec(name);
  const model=m?`DJI ${m[1].replace(/([a-z])(\d)/i,'$1 $2').replace(/^(\w)(\w*)/,(x,a,b)=>a.toUpperCase()+b.toLowerCase())}`:(d.remoteId&&d.remoteId.uaType)||'—';
  const maker=/DJI/i.test(name+' '+(d.detection||''))?'DJI (SZ DJI Technology)':(d.detection||'').replace(/^Bluetooth company /,'')||'—';
  const rssi=Number.isFinite(d.rssi)?d.rssi:null;
  const band=rssi===null?'—':rssi>=-60?TX('قريبة جداً (أقل من 5 م تقريباً)','very close (about < 5 m)'):rssi>=-72?TX('قريبة (5 إلى 30 م تقريباً)','near (about 5–30 m)'):rssi>=-84?TX('متوسطة (30 إلى 80 م تقريباً)','medium (about 30–80 m)'):TX('بعيدة (أكثر من 80 م تقريباً)','far (about > 80 m)');
  const now=Date.now(), dd=pgLoad(`drSig-${d.key}-${Math.floor(now/15000)}`,[`airspace/history/drone?key=${encodeURIComponent(d.key)}&from=${now-600000}&to=${now}`]);
  const pts=dd&&dd[0]&&!dd[0].__err?(dd[0].points||[]).filter(p=>Number.isFinite(p[8])):[];
  let trend='—', spark='';
  if(pts.length>=4){
    const n=Math.max(2,Math.floor(pts.length/3)), avg=a=>a.reduce((s,p)=>s+p[8],0)/a.length, delta=avg(pts.slice(-n))-avg(pts.slice(0,n));
    trend=delta>3?`<b style="color:#e05561">${TX('تقترب (الإشارة تقوى)','coming closer (signal rising)')}</b>`:delta<-3?TX('تبتعد (الإشارة تضعف)','moving away (signal falling)'):TX('ثابتة تقريباً','about steady');
    trend+=` <span class="muted-s num">${delta>0?'+':''}${delta.toFixed(1)} dB</span>`;
    const W=220,H=40,t0=pts[0][0],t1=Math.max(t0+1,pts[pts.length-1][0]),X=t=>(t-t0)/(t1-t0)*W,Y=r=>H-((Math.max(-100,Math.min(-30,r))+100)/70)*H;
    spark=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="${H}" style="display:block;margin-top:4px"><path d="${pts.map((p,i)=>`${i?'L':'M'}${X(p[0]).toFixed(1)} ${Y(p[8]).toFixed(1)}`).join('')}" fill="none" stroke="#f2b84b" stroke-width="1.6"/></svg>`;
  }
  const dur=Number.isFinite(d.firstSeen)&&Number.isFinite(d.lastSeen)?Math.max(0,Math.round((d.lastSeen-d.firstSeen)/1000)):null;
  const durT=dur===null?'—':dur<90?`<span class="num">${dur}</span> ${TX('ث','s')}`:`<span class="num">${Math.round(dur/60)}</span> ${TX('د','min')}`;
  return `<div class="dsel" style="margin-top:10px"><div class="dsel-h"><b>${ico('radar',13)} ${TX('ما يعرفه الحسّاس عنها','What the sensor knows')}</b></div>
    ${kv([[TX('الشركة المصنّعة','Maker'),esc_(maker)],[TX('الطراز (من اسمها)','Model (from its name)'),esc_(model)],[TX('الاسم الذي تبثّه','Name it broadcasts'),`<span class="num" dir="ltr">${esc_(name||'—')}</span>`],
      [TX('العنوان','Address'),`<span class="num" dir="ltr">${esc_(d.identifier||'—')}</span> · ${esc_(d.protocol||'')}`],[TX('الحسّاس الذي سمعها','Heard by sensor'),`<span class="num">${esc_(d.sensorId||'—')}</span>`],
      [TX('القرب التقريبي','Rough distance'),band],[TX('الاتجاه','Direction of travel'),trend],[TX('مدة وجودها','Time in range'),durT],[TX('قراءات آخر 10 دقائق','Readings, last 10 min'),`<span class="num">${pts.length}</span>`]])}
    ${spark?`<div class="muted-s">${TX('قوة الإشارة آخر 10 دقائق (أعلى = أقرب)','Signal, last 10 minutes (higher = closer)')}</div>${spark}`:''}
    ${!(d.remoteId&&Number.isFinite(d.remoteId.lat))?`<div class="muted-s" style="margin-top:8px">${TX('للوصول إليها: امشِ بالحسّاس أو بجوال وراقب الإشارة — كلما قويت فأنت أقرب. ابحث أيضاً عن شخص يمسك جهاز تحكّم أو جوالاً موجّهاً للسماء.','To find it: walk with the sensor or a phone and watch the signal — stronger means closer. Also look for someone holding a controller or a phone pointed at the sky.')}</div>`:''}
  </div>`;
}
/* The replay picture: a map around the site (path, pilot, flown part) or, without positions, the signal. */
function droneReplayInner(rd,pos){
  const W=600,H=400,cx=W/2,cy=H/2;
  const pts=(rd&&rd.points)||[];
  if(!pts.length) return `<text class="rl" x="${cx}" y="${cy}" text-anchor="middle">${rd&&rd.points?TX('لا يوجد مسار محفوظ','No recorded track'):TX('جارٍ التحميل…','Loading…')}</text>`;
  const k=Math.min(pts.length-1,Math.round(pos*(pts.length-1))), cur=pts[k];
  const geo=pts.filter(p=>Number.isFinite(p[1])&&Number.isFinite(p[2]));
  if(geo.length>=1){
    const s=rd.site||{lat:24.7136,lon:46.6753,radiusM:500}, m=111320, kk=Math.cos(s.lat*Math.PI/180);
    const en=(lat,lon)=>[(lon-s.lon)*m*kk,(lat-s.lat)*m];
    const all=[...geo.map(p=>en(p[1],p[2])),...geo.filter(p=>Number.isFinite(p[6])).map(p=>en(p[6],p[7]))];
    const span=Math.max(s.radiusM||500,...all.map(([e,n])=>Math.hypot(e,n)))*1.15, sc=(H/2-20)/span;
    const P=(lat,lon)=>{const [e,n]=en(lat,lon); return [cx+e*sc,cy-n*sc];};
    const rings=[0.33,0.66,1].map(f=>`<circle fill="none" stroke="rgba(140,150,170,.45)" stroke-width="1" cx="${cx}" cy="${cy}" r="${(span*f*sc).toFixed(1)}"/><text class="rl" x="${cx+4}" y="${(cy-span*f*sc+12).toFixed(1)}">${Math.round(span*f)} m</text>`).join('');
    const bound=`<circle cx="${cx}" cy="${cy}" r="${((s.radiusM||500)*sc).toFixed(1)}" fill="none" stroke="#e05561" stroke-width="1.5" stroke-dasharray="5 4"/>`;
    const d=arr=>arr.map((p,i)=>{const [x,y]=P(p[1],p[2]);return `${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`;}).join('');
    const flown=geo.filter(p=>p[0]<=cur[0]), here=[...flown].reverse()[0]||geo[0], [hx,hy]=P(here[1],here[2]);
    const pil=Number.isFinite(here[6])?P(here[6],here[7]):null;
    return `${rings}${bound}<circle class="esp" cx="${cx}" cy="${cy}" r="4"/><text class="rl" x="${cx+6}" y="${cy+14}">${TX('الموقع','Site')}</text>`
      +`<path class="rep-full" d="${d(geo)}"/>${flown.length>1?`<path class="rep-flown" d="${d(flown)}"/>`:''}`
      +(pil?`<line x1="${pil[0].toFixed(1)}" y1="${pil[1].toFixed(1)}" x2="${hx.toFixed(1)}" y2="${hy.toFixed(1)}" stroke="#f2b84b" stroke-dasharray="4 4"/><circle cx="${pil[0].toFixed(1)}" cy="${pil[1].toFixed(1)}" r="5" fill="#f2b84b"/><text class="rl" x="${(pil[0]+8).toFixed(1)}" y="${(pil[1]-6).toFixed(1)}">${TX('الطيّار','Pilot')}</text>`:'')
      +`<circle class="rep-mk-d" cx="${hx.toFixed(1)}" cy="${hy.toFixed(1)}" r="6"/><text class="rl" x="${(hx+9).toFixed(1)}" y="${(hy-8).toFixed(1)}">${esc_(rd.title||'')}${Number.isFinite(here[3])?' · '+Math.round(here[3])+' m':''}${Number.isFinite(here[9])?' · '+Math.round(here[9])+' m '+TX('من الموقع','from site'):''}</text>`;
  }
  // No positions: the signal strength over time.
  const sig=pts.filter(p=>Number.isFinite(p[8])); if(!sig.length) return `<text class="rl" x="${cx}" y="${cy}" text-anchor="middle">${TX('لا توجد قراءات','No readings')}</text>`;
  const t0=sig[0][0],t1=Math.max(t0+1,sig[sig.length-1][0]), lo=-100, hi=-30, X=t=>40+(t-t0)/(t1-t0)*(W-60), Y=r=>20+(hi-Math.max(lo,Math.min(hi,r)))/(hi-lo)*(H-50);
  const grid=[-40,-60,-80,-100].map(r=>`<line x1="40" x2="${W-20}" y1="${Y(r)}" y2="${Y(r)}" fill="none" stroke="rgba(140,150,170,.45)" stroke-width="1"/><text class="rl" x="4" y="${Y(r)+4}">${r}</text>`).join('');
  const line=sig.map((p,i)=>`${i?'L':'M'}${X(p[0]).toFixed(1)} ${Y(p[8]).toFixed(1)}`).join('');
  const c=sig.filter(p=>p[0]<=cur[0]).pop()||sig[0];
  return `${grid}<text class="rl" x="40" y="${H-8}">dBm · ${TX('أقرب = أقوى','closer = stronger')}</text><path class="rep-full" d="${line}"/><line x1="${X(c[0]).toFixed(1)}" x2="${X(c[0]).toFixed(1)}" y1="20" y2="${H-30}" stroke="#f2b84b"/><circle class="rep-mk-d" cx="${X(c[0]).toFixed(1)}" cy="${Y(c[8]).toFixed(1)}" r="6"/><text class="rl" x="${(X(c[0])+8).toFixed(1)}" y="${(Y(c[8])-8).toFixed(1)}">${Math.round(c[8])} dBm</text>`;
}
function deviceHistoryView(devs,ST){
  const list=devs.slice().sort((a,b)=>(b.firstSeen||0)-(a.firstSeen||0));
  const sel=devs.find(x=>x.key===axSel);
  const side=sel?`<div class="dsel"><div class="dsel-h"><b>${esc_(sel.name||sel.typeLabel||sel.masked)}</b>${XB(ST[sel.status][0]==='crit'?'no':ST[sel.status][0]==='warn'?'open':'ok',ST[sel.status][1])}</div>${kv([[TX('النوع','Type'),esc_(sel.typeLabel||'—')],[TX('العنوان','Address'),`<span class="num" dir="ltr">${esc_(sel.id)}</span>`],[TX('البروتوكول','Protocol'),esc_(sel.protocol)],[TX('المسافة وقت الرصد','Distance when seen'),NEAR(sel.near)],[TX('أول ظهور','First seen'),Number.isFinite(sel.firstSeen)?ago(sel.firstSeen):'—'],[TX('آخر ظهور','Last seen'),ago(sel.lastSeen)],[TX('الشركة','Vendor'),esc_(sel.vendor||'—')]])}</div>`:`<div class="muted-s" style="padding:12px 0">${TX('اختر جهازاً لرؤية أين ومتى رُصد','Pick a device to see where and when it was seen')}</div>`;
  const map=mp(TX('أين رُصدت الأجهزة','Where devices were seen'),`<div class="mmap"><div class="mmap-c scn-c">${scnHtml('dev',list.slice(0,80))}</div><aside class="mmap-s"><h3>${ico('clock',14)} ${TX('الجهاز المحدد','Selected device')}</h3>${side}</aside></div>`,`<span class="muted-s">${TX('المواقع تقديرية من قوة الإشارة وقت الرصد','Positions estimated from signal strength when seen')}</span>`,'flush','radar');
  const tbl=mp(TX('سجل ظهور الأجهزة','Device sighting log')+` <span class="muted-s"><span class="num">${list.length}</span></span>`,`<table class="tbl"><thead><tr><th>${TX('الجهاز','Device')}</th><th>${TX('الحالة','State')}</th><th>${TX('أول ظهور','First seen')}</th><th>${TX('آخر ظهور','Last seen')}</th><th>${TX('المسافة','Distance')}</th></tr></thead><tbody>${list.slice(0,200).map(x=>`<tr class="${axSel===x.key?'sel':''}" data-ax="${esc_(x.key)}" tabindex="0"><td><b>${esc_(x.name||x.typeLabel||x.masked)}</b> <span class="muted-s">${esc_(x.protocol)} · ${esc_(x.typeLabel||'')}</span></td><td><span class="dotst ${ST[x.status][0]==='crit'?'off':ST[x.status][0]}">${ST[x.status][1]}</span></td><td class="num" dir="ltr">${Number.isFinite(x.firstSeen)?ago(x.firstSeen):'—'}</td><td class="num" dir="ltr">${ago(x.lastSeen)}</td><td>${NEAR(x.near)}</td></tr>`).join('')||emptyRow(5,TX('لم يُرصد أي جهاز بعد','No devices seen yet'))}</tbody></table>`,`<span class="muted-s">${TX('الأجهزة المتتبّعة في هذه الجلسة، الأحدث ظهوراً أولاً','Devices tracked this session, newest first')}</span>`,'flush','wifi');
  return map+tbl;
}
// --- replay drawing (on each subsystem's own map) + transport ---
function airReplayInner(rd,pos){
  const cx=300,cy=200, s=rd.site, z=rd.zones||{}, pts=(rd.det&&rd.det.points)||[];
  if(!s) return `<text class="rl" x="${cx}" y="${cy}" text-anchor="middle">${TX('لا يوجد موقع','No site set')}</text>`;
  const kx=111320*Math.cos(s.lat*Math.PI/180), xy=(lat,lon)=>[(lon-s.lon)*kx,(lat-s.lat)*111320];
  const ext=pts.length?Math.max(...pts.map(p=>Math.hypot(...xy(p[1],p[2])))):0;
  const maxM=Math.min(55000, Math.max((z.warningM||10000)*1.15, ext*1.14, 3000)), S=185/maxM, P=(lat,lon)=>{const [x,y]=xy(lat,lon);return [cx+x*S,cy-y*S];};
  const ring=(m,c,t)=>m&&m<=maxM*1.03?`<circle class="${c}" cx="${cx}" cy="${cy}" r="${(m*S).toFixed(1)}"/><text class="rzt" x="${cx}" y="${(cy-m*S+12).toFixed(1)}">${t}</text>`:'';
  const base=`${ring(z.restrictedM,'rz',TX('مقيّد','Restricted'))}${ring(z.warningM,'rr',TX('تحذير','Warning'))}${ring(z.monitorM,'rr',TX('مراقبة','Monitor'))}<text class="nN num" x="${cx}" y="14">N</text><rect class="esp" x="${cx-16}" y="${cy-8}" width="32" height="16" rx="4"/><text class="espt num" x="${cx}" y="${cy+4}">SITE</text>`;
  if(!pts.length) return base+`<text class="rl" x="${cx}" y="${cy+160}" text-anchor="middle">${rd.det?TX('لا يوجد مسار مسجّل لهذه الرحلة','No recorded track for this flight'):TX('اختر رحلة لإعادة تشغيل مسارها','Pick a flight to replay its path')}</text>`;
  const d=(arr)=>arr.map((p,i)=>{const [x,y]=P(p[1],p[2]);return `${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`;}).join('');
  const t0=pts[0][0],t1=pts[pts.length-1][0],tNow=t0+(t1-t0)*pos;
  let i=pts.findIndex(p=>p[0]>tNow); if(i===-1)i=pts.length;
  const a=pts[Math.max(0,i-1)],b=pts[Math.min(pts.length-1,i)],f=b[0]>a[0]?(tNow-a[0])/(b[0]-a[0]):0;
  const lat=a[1]+(b[1]-a[1])*f,lon=a[2]+(b[2]-a[2])*f,trk=a[4]??b[4]??0,alt=a[3],[mx,my]=P(lat,lon);
  return `${base}${pts.length>1?`<path class="rep-full" d="${d(pts)}"/><path class="rep-flown" d="${d(pts.filter(p=>p[0]<=tNow))}"/>`:''}<path class="plane rep-mk" d="${PLANE}" transform="translate(${mx.toFixed(1)} ${my.toFixed(1)}) rotate(${trk})"/><text class="rl" x="${(mx+11).toFixed(1)}" y="${(my-8).toFixed(1)}">${esc_(rd.title||'')}${Number.isFinite(alt)?' · '+alt+' ft':''}</text>`;
}
function satReplayInner(pass,pos){
  const cx=150,cy=150,R=130;
  const rings=[0,30,60].map(e=>`<circle class="rr" cx="${cx}" cy="${cy}" r="${(R*(1-e/90)).toFixed(1)}"/>${e?`<text class="num" x="${cx+10}" y="${(cy-R*(1-e/90)+10).toFixed(1)}">${e}°</text>`:''}`).join('');
  const Pc=(az,el)=>{const r=R*(1-Math.max(0,el)/90),a=(az-90)*Math.PI/180;return [cx+r*Math.cos(a),cy+r*Math.sin(a)];};
  const comp=[['N',0],['E',90],['S',180],['W',270]].map(([t,az])=>{const [x,y]=Pc(az,0);return `<text class="num" x="${(cx+(x-cx)*1.1).toFixed(1)}" y="${(cy+(y-cy)*1.1+3).toFixed(1)}">${t}</text>`;}).join('');
  const base=`${rings}${comp}<circle class="esp" cx="${cx}" cy="${cy}" r="3.5"/>`;
  const path=(pass&&pass.path)||[];
  if(path.length<2) return base+`<text class="rl" x="${cx}" y="${cy+R+16}" text-anchor="middle">${pass?TX('لا يوجد مسار','No path'):TX('اختر عبوراً لإعادة تشغيله','Pick a pass to replay')}</text>`;
  const d=(arr)=>arr.map((p,i)=>{const [x,y]=Pc(p[0],p[1]);return `${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`;}).join('');
  const k=Math.round(pos*(path.length-1)),cur=path[k]||path[0],[mx,my]=Pc(cur[0],cur[1]);
  return `${base}<path class="rep-full" d="${d(path)}"/><path class="rep-flown" d="${d(path.slice(0,k+1))}"/><circle class="rep-mk-d" cx="${mx.toFixed(1)}" cy="${my.toFixed(1)}" r="5.5"/><text class="rl" x="${(mx+8).toFixed(1)}" y="${(my-6).toFixed(1)}">${esc_(pass.name)} · ${Math.round(cur[1])}°</text>`;
}
function repClock(pos){ if(!repData) return ''; if(repData.kind==='drone'){ const p=repData.points||[]; if(!p.length) return ''; const t0=p[0][0],t1=p[p.length-1][0]; return hmsClock(t0+(t1-t0)*pos); } if(repData.kind==='air'){const p=repData.det&&repData.det.points; if(!p||!p.length) return ''; const t0=p[0][0],t1=p[p.length-1][0]; return hmsClock(t0+(t1-t0)*pos);} const x=repData.pass; return x?hmsClock(x.aos+(x.los-x.aos)*pos):''; }
function repInner(pos){ if(!repData) return ''; if(repData.kind==='drone') return droneReplayInner(repData,pos); return repData.kind==='air'?airReplayInner(repData,pos):satReplayInner(repData.pass,pos); }
function repControls(){ return `<div class="rep-ctl"><button class="btn sm pri" id="axRepPlay" aria-label="${TX('تشغيل','Play')}">${axRepPlay?'❚❚':'▶'}</button><input type="range" id="axRepSlider" min="0" max="1000" value="${Math.round(axRepPos*1000)}" aria-label="${TX('موضع الإعادة','Replay position')}"><span class="num" id="axRepClock">${repClock(axRepPos)}</span><div class="mseg">${[1,2,4].map(sp=>`<button data-reps="${sp}" aria-pressed="${axRepSpeed===sp}"><span class="num">${sp}×</span></button>`).join('')}</div><button class="btn sm" id="axRepClose">${TX('إغلاق','Close')}</button></div>`; }
function repAirFacts(det){ return `<div class="rep-facts">${kv([[TX('النداء','Callsign'),`<span class="num" dir="ltr">${esc_(det.callsign||(det.hex||'').toUpperCase())}</span>`],[TX('النوع','Type'),esc_(det.type||'—')],[TX('التسجيل','Registration'),`<span class="num" dir="ltr">${esc_(det.registration||'—')}</span>`],['ICAO',`<span class="num" dir="ltr">${(det.hex||'').toUpperCase()}</span>`],[TX('أقرب مسافة','Closest'),Number.isFinite(det.minDistanceM)?`<span class="num">${(det.minDistanceM/1000).toFixed(1)}</span> ${TX('كم','km')}`:'—'],[TX('الارتفاع','Altitude'),det.minAltFt==null?TX('على الأرض','on ground'):`<span class="num">${det.minAltFt}–${det.maxAltFt}</span> ft`],[TX('الفترة','Window'),`<span class="num" dir="ltr">${hmsClock(det.firstSeen)} – ${hmsClock(det.lastSeen)}</span>`],...(det.squawks&&det.squawks.length?[[TX('الكود','Squawk'),`<span class="num" dir="ltr">${det.squawks.join(', ')}</span>`]]:[]),[TX('المصدر','Source'),`${esc_(det.source||'—')} · <span class="num">${(det.points||[]).length}</span> ${TX('نقطة','pts')}`]])}</div>`; }
function repSatFacts(pass){ return `<div class="rep-facts">${kv([['NORAD',`<span class="num">${pass.norad}</span>`],[TX('الشروق','Rise'),`<span class="num" dir="ltr">${hmsClock(pass.aos)}</span>${Number.isFinite(pass.azAos)?` · ${TX('سمت','az')} <span class="num">${pass.azAos}°</span>`:''}`],[TX('الذروة','Peak'),`<span class="num">${pass.maxElevationDeg}°</span> @ <span class="num" dir="ltr">${hmsClock(pass.tca)}</span>`],[TX('الغروب','Set'),`<span class="num" dir="ltr">${hmsClock(pass.los)}</span>${Number.isFinite(pass.azLos)?` · ${TX('سمت','az')} <span class="num">${pass.azLos}°</span>`:''}`],[TX('المدة','Duration'),hDur(pass.los-pass.aos)],[TX('نوع','Kind'),pass.imaging?TX('قمر تصوير','imaging satellite'):TX('قمر متتبَّع','tracked satellite')],...(pass.alert?[[TX('إنذار','Alert'),XB('open',esc_(pass.alert.ref||String(pass.alert.id)))]]:[])])}</div>`; }
function repRedraw(){ const svg=document.getElementById('axRepSvg'); if(!svg){ repStop(); return; } svg.innerHTML=repInner(axRepPos); const sl=document.getElementById('axRepSlider'); if(sl&&document.activeElement!==sl) sl.value=Math.round(axRepPos*1000); const ck=document.getElementById('axRepClock'); if(ck) ck.textContent=repClock(axRepPos); const pb=document.getElementById('axRepPlay'); if(pb) pb.textContent=axRepPlay?'❚❚':'▶'; }
function repStop(){ if(repTimer){clearInterval(repTimer); repTimer=null;} }
