  const A=AIRX(), d=pgLoad('air',['airspace/aircraft','airspace/space']), T=LIVE.thr||{}, AC=d&&d[0]&&!d[0].__err?d[0]:null, SP=d&&d[1]&&!d[1].__err?d[1]:null, ST=AST();
  const devs=A?A.devices():[], sens=A?A.sensors():[], feed=A?A.feed():'connecting';
