    <label class="mf"><span>${TX('الوجهة','Target')}</span><select id="drT">${DRN.targets.map(([n],i)=>`<option value="${i}" ${i===DRN.tgt?'selected':''}>${ARh(n)}</option>`).join('')}</select></label>
