function stExplain(){
  const L=exList().filter(x=>exCat==='all'||x[0]===exCat);
  const chips=`<div class="ex-chips">${exCats().map(([k,t])=>`<button type="button" data-excat="${k}" aria-pressed="${exCat===k}">${t} <span class="num">${k==='all'?exList().length:exList().filter(x=>x[0]===k).length}</span></button>`).join('')}</div>`;
  const cards=L.map(([cat,title,pics,out,what,sawn,you,snd,go])=>`<article class="ex ex-${cat}">
      <div class="ex-pic ${out}">${pics.map((p,i)=>`${i?'<span class="ex-ar" aria-hidden="true">→</span>':''}<span class="ex-ic${i===pics.length-1?' last':''}">${rdtIco(p,34)}</span>`).join('')}</div>
      <h3>${title}</h3>
      <dl><dt>${TX('ماذا يحدث','What happens')}</dt><dd>${what}</dd><dt>${TX('ماذا يفعل صون','What SAWN does')}</dt><dd>${sawn}</dd><dt>${TX('ماذا تفعل أنت','What you do')}</dt><dd>${you}</dd></dl>
      <div class="ex-acts">${snd?`<button type="button" class="btn sm${RDT.playing===snd?' pri':''}" data-rdts="${snd}">${rdtIco('sound',14)} ${RDT.playing===snd?TX('إيقاف','Stop'):snd==='abdullah'?TX('اسمع صوته','Hear his voice'):TX('اسمع الإنذار','Hear the alert')}</button>`:''}${go?`<a class="btn sm" href="${go}">${TX('افتح الصفحة','Open the page')}</a>`:''}</div>
    </article>`).join('');
  return chips+`<div class="ex-grid">${cards}</div>`;
}
function bindExplain(C){
  C.querySelectorAll('[data-excat]').forEach(b=>b.onclick=()=>{ exCat=b.dataset.excat; render(); });
  C.querySelectorAll('[data-rdts]').forEach(b=>b.onclick=()=>rdtPlay(b.dataset.rdts));
}
