const GM={ st:'idle', qs:[], i:0, score:0, lives:3, streak:0, right:0, pick:null, t0:0, timer:null };
const GM_SECS=15, GM_N=8;
const gmKey=()=>'sawn.game.best.'+((CORE.user&&CORE.user.username)||'me');
const gmBest=()=>{ try{ return +localStorage.getItem(gmKey())||0; }catch(e){ return 0; } };
