const notHuman=a=>a&&a.approvedBy&&['system','training-seed'].includes(a.approvedBy);
const notHumanBanner=a=>notHuman(a)?`<div class="ed-warn" role="note" style="margin:0"><b>${a.seeded?TX('سياسة تدريب مزروعة','Seeded training policy'):TX('لم يعتمدها شخص','Not approved by a person')}</b><span>${a.seeded?TX(`${a.ref} مزروعة لبيانات التدريب حتى تبدأ التمارين من النقطة نفسها، وليست اعتماداً بشرياً.`,`${a.ref} is seeded for training so exercises start from the same point; it is not a human approval.`):TX(`${a.ref} فُعّلت تلقائياً عند أول تشغيل في نسخة سابقة من صون. اعتمدوا مسودة حتى تصبح السياسة النشطة باعتماد بشري.`,`${a.ref} was activated automatically at first start by an earlier SAWN version. Approve a draft so the active policy has a human approval.`)}</span></div>`:'';

const ASM_STEPS=()=>[[TX('معلومات المنشأة','Facility information'),TX('المدخلات والناقص','Inputs and gaps')],[TX('الأساس والمتطلبات','Baseline and requirements'),TX('الحساسية مُدخلة يدوياً','Sensitivity is a manual input')],[TX('المراجعة والتعديل','Review and adjust'),TX('بسبب مكتوب','With a written reason')],[TX('أثر التغيير','Change impact'),TX('قبل الاعتماد','Before approval')],[TX('الاعتماد','Approval'),TX('نسخة محددة','One exact revision')],[TX('السياسة النشطة','Active policy'),TX('أثرها على الحوادث','Its effect on incidents')]];
