const ASM_CARD=()=>({prox125:TX('125 كيلوهرتز','125 kHz proximity'),smart:TX('ذكية مشفّرة','Encrypted smart card')});
const CLS_T=()=>({pub:TX('عام','Public'),res:TX('مقيّد','Restricted'),sec:TX('سري','Secret'),top:TX('سري للغاية','Top secret')});
