const ruleTitle=id=>{ const R=(POL.asm&&POL.asm.rules||{})[id]||(POL.asm&&POL.asm.zoneModel&&POL.asm.zoneModel.rules||{})[id]; return TX(RULE_AR[id]||(R&&R.title)||id,(R&&R.title)||id); };
/* what "critical system" records: the asset is a critical system or a supporting component within its scope */
function CSCC_NOTE(){ return TX('«ضمن نطاق نظام حساس» يشمل الأنظمة الحساسة ومكوّناتها الداعمة في هذا السيناريو. لا يشهد بالامتثال لضوابط CSCC، ولا يجعل كل أصل نظاماً حساساً مستقلاً، ولا يحدد صون منه نوع المنطقة أو مستواها.','“Within a critical-system scope” covers critical systems and their supporting components in this scenario. It does not certify CSCC compliance, does not make each asset a standalone critical system, and SAWN sets no zone type or level from it.'); }
const FIELD_T=()=>({factors:TX('عوامل التحقق','factors'),readerLink:TX('ربط القارئ','reader link'),camera:TX('الكاميرا','camera'),cardTech:TX('نوع البطاقة','card type'),visitor:TX('تصريح زائر','visitor pass')});
function missTxt(m){
  const f=m.field||'', p=f.split(':');
  const ar=f==='declaredLevel'?'لم يُعلن مستوى حساسية لهذه المنطقة'
    :f==='entrances'?'لا توجد حماية مداخل مسجّلة لهذه المنطقة: لا يمكن فحص نقاط الضعف ولا أثر تغيير المتطلبات'
    :p[0]==='entrance'?`المدخل ${p[1]}: بيانات حماية ناقصة`
    :p[0]==='asset'&&p[2]==='critical'?`الأصل ${p[1]}: حالة النظام الحساس غير مسجّلة (أمن المعلومات)`
    :p[0]==='asset'?`الأصل ${p[1]}: تصنيف البيانات غير مسجّل`:m.text;
  return TX(ar,m.text);
}
const sensExpl=s=>s.value==null?TX('غير محدد: ملف المنشأة لا يعطي مستوى لهذه المنطقة، ولا يُعامل كمنخفض.',s.explanation):TX(`المستوى ${s.value} كما أُدخل في ملف المنشأة: مستوى أساسي يدوي، لا مشتق من معلومات المنشأة.`,s.explanation);
const promptTxt=x=>TX(`تحتوي ${x.asset} المصنّف «${CLS_T()[x.classification]||x.classification}» وهو أعلى من مستوى المنطقة. راجع ما إذا كان المستوى يعكس ما تحميه المنطقة؛ التصنيف لا يحدد المستوى.`,x.text);
function checkTxt(c){
  const A=POL.asm, D=A&&A.draft, zn=c.zoneId?`${c.zoneId} (${zName(asmZone(c.zoneId))})`:'', F=FIELD_T(), SV=ASM_SEV();
  const P=D&&D.proposal&&D.proposal[c.zoneId];
  const tr=s=>String(s).replace(/^(factors|readerLink|camera)\b/,k=>F[k]).replace(/\btrue\b/g,TX('نعم','yes')).replace(/\bfalse\b/g,TX('لا','no'));
  const ar=(()=>{switch(c.rule){
    case 'NO-LEVEL': return `${zn}: لا يوجد مستوى حساسية. أعلنه في معلومات المنشأة أو حدّده بتعديل مع سبب.`;
    case 'ADJ-BELOW-PROPOSAL': return `${zn}: عُدّل إلى المستوى ${c.to}، أقل من المستوى الأساسي المعلن ${c.from}.`;
    case 'SENS-DECLARED': return /:active$/.test(c.id)?`${zn}: المستوى ${c.from} في السياسة النشطة ← ${c.to}.`:`${zn}: عُدّل من المستوى الأساسي المعلن ${c.from} إلى ${c.to}.`;
    case 'SENS-MISSING': return `${zn}: لا مستوى أساسي معلن؛ حُدّد ${c.to} بتعديل.`;
    case 'ADJ-BELOW-ACTIVE': return `${zn}: خفض من المستوى ${c.from} في السياسة النشطة إلى ${c.to}.`;
    case 'INCOMPLETE': return `${zn}: معلومات ناقصة — ${(P?P.missing.filter(m=>(c.missing||[]).includes(m.field)).map(missTxt):c.missing||[]).join('؛ ')}. لا تُعامل كحساسية منخفضة.`;
    case 'CSCC-SCOPE': return `${zn}: ${(P?P.missing.filter(m=>(c.missing||[]).includes(m.field)).map(missTxt):[]).join('؛ ')}. ضوابط الأنظمة الحساسة تُقرَّر لكل أصل لا بمستوى المنطقة.`;
    case 'ASSET-REVIEW': { const x=P&&P.prompts.find(y=>y.asset===c.key); return x?`${zn}: ${promptTxt(x)}`:null; }
    case 'REQ-BELOW-RULE': return `${zn}: ${(c.fields||[]).map(k=>F[k]||k).join('، ')} أقل مما يتطلبه المستوى.`;
    case 'AREA-MAP': return `${zn}: تتغير المتطلبات — ${(c.changes||[]).map(tr).join('، ')}.`;
    case 'NA-KIND': return `${zn}: لا يمكن تقييم الأثر — لا توجد حماية مداخل مسجّلة، فلا يُعرف أي المداخل ستقصر عن المتطلبات الجديدة.`;
    case 'PRIORITY-DOWN': return `${zn}: الحوادث الجديدة ستأخذ أولوية أقل — ${(c.shifts||[]).map(x=>`${SV[x.severity]}: من ${x.from} إلى ${x.to}`).join('، ')}.`;
    case 'PRIO-1': return `${zn}: الحوادث الجديدة ستأخذ أولوية أعلى — ${(c.shifts||[]).map(x=>`${SV[x.severity]}: من ${x.from} إلى ${x.to}`).join('، ')}.`;
    case 'GATE-DEVICES': return c.category==='unassessable'?`${zn}: لا يمكن تقييم الأثر — سياسة البوابة غير متاحة، فلا يُعرف تغيّر قيود الأجهزة عند بواباتها.`:`${zn}: فئات الأجهزة المقيدة عند بواباتها — ${[c.added&&c.added.length?`أُضيفت: ${c.added.join('، ')}`:null,c.removed&&c.removed.length?`لم تعد مقيدة: ${c.removed.join('، ')}`:null].filter(Boolean).join('؛ ')}.`;
    case 'ACCEPT-L5': case 'ACCEPT-L4-30': return `${c.key}: ${RULE_AR[c.rule]}.`;
    case 'ACCEPT-MAX-90': return c.category==='invalid'?`${c.key}: ${RULE_AR[c.rule]}.`:c.category==='info'?`${c.key}: لم تعد نقطة الضعف موجودة بمستويات المسودة، فلا يُنقل قبولها إلى السياسة.`:`${c.key}: مقبولة — ${c.reason||''} (${c.authorized||''})`;
    default: return zoneCheckAr(c); }})();
  return TX(ar||c.text,c.text);
}
const HIST_AR={'Draft started from the active policy and the current proposal':'بدأت المسودة من السياسة النشطة والمقترح الحالي','Assessment level adjusted':'تعديل مستوى منطقة','Assessment adjustment removed':'العودة للمستوى المقترح','Assessment requirement changed':'تعديل متطلب حماية','Assessment requirement reset':'إعادة المتطلب للقاعدة','Facility information changed':'تعديل معلومات المنشأة','Weakness accepted (exception)':'قبول نقطة ضعف (استثناء)','Requirement exception authorized':'اعتماد استثناء لمتطلب','Weakness acceptance withdrawn':'سحب قبول نقطة ضعف','Approved and activated':'اعتُمدت وأصبحت نشطة','Discarded':'أُلغيت'};
const histTxt=w=>TX(HIST_AR[w]||w,w);
/* a rule chip: id, version and basis; hover shows the rule and its reference */
function ruleChip(id,ver){
  const R=(POL.asm&&POL.asm.rules||{})[id]||(POL.asm&&POL.asm.zoneModel&&POL.asm.zoneModel.rules||{})[id]; if(!R) return id?`<span class="pill">${esc_(id)}</span>`:'';
  return `<span class="pill rchip ${R.basis}" title="${esc_(ruleTitle(id)+(R.ref?' — '+R.ref:''))}"><span class="num" dir="ltr">${esc_(id)} v${ver||R.v}</span> · ${BASIS()[R.basis]||R.basis}</span>`;
}
const lvx=l=>l==null?`<span class="xbdg no">${TX('غير محدد','Undetermined')}</span>`:lv(l);
const yes=b=>b==null?`<span class="xbdg mut">${TX('غير مسجّل','Not recorded')}</span>`:b?TX('نعم','Yes'):TX('لا','No');

/* ---------- views per step ---------- */
function asmInputs(){
  const A=POL.asm, S0=asmSrc(), I=S0.inputs, P=S0.proposal, ed=coreCan('policy.draft');
  const zr=A.zones.map(z=>{const p=P[z.id]; const ents=I.entrances.filter(e=>e.zone===z.id), as=I.assets.filter(a=>a.zone===z.id);
    return `<tr><td class="num"><b>${z.id}</b></td><td>${zName(z)}</td><td>${lvx(I.zones[z.id]?.declaredLevel??null)}</td><td>${ents.map(e=>`<span class="num">${e.gate}</span>`).join(' ')||'—'}</td><td>${as.map(a=>`<span class="num">${a.id}</span>`).join(' ')||'—'}</td><td style="white-space:normal;min-width:220px">${p.missing.length?p.missing.map(m=>`<div class="muted-s">⚠ ${esc_(missTxt(m))}</div>`).join(''):`<span class="xbdg ok">${TX('مكتملة','Complete')}</span>`}</td>${ed?`<td><button class="btn sm" data-in-zone="${z.id}">${TX('تعديل','Edit')}</button></td>`:''}</tr>`;}).join('');
  const er=I.entrances.map(e=>`<tr><td class="num"><b>${e.gate}</b></td><td class="num">${e.zone}</td><td class="num">${e.factors??'—'}</td><td>${e.cardTech?ASM_CARD()[e.cardTech]:yes(null)}</td><td>${e.readerLink?LINK_T[e.readerLink]:yes(null)}</td><td>${yes(e.camera)}</td>${ed?`<td><button class="btn sm" data-in-ent="${e.gate}">${TX('تعديل','Edit')}</button></td>`:''}</tr>`).join('');
  const ar=I.assets.map(a=>`<tr><td class="num"><b>${esc_(a.id)}</b></td><td>${esc_(typeof a.name==='object'?TX(a.name.ar,a.name.en):a.name)}</td><td class="num">${a.zone}</td><td>${a.classification?CLS_T()[a.classification]:yes(null)}</td><td>${yes(a.criticalSystem)}</td>${ed?`<td><button class="btn sm" data-in-asset="${esc_(a.id)}">${TX('تعديل','Edit')}</button></td>`:''}</tr>`).join('');
  const vr=I.visitorPasses.map(p=>`<tr><td class="num"><b>${esc_(p.id)}</b></td><td class="num">${p.zones.join('  ')}</td></tr>`).join('');
  const note=`<div class="muted-s" style="padding:10px 16px 0">${TX('المعلومة الناقصة تظهر كناقصة ولا تُعامل كحساسية منخفضة. تصنيف البيانات وحالة النظام الحساس لا يغيّران مستوى المنطقة.','Missing information is shown as missing and never treated as low sensitivity. Data classification and critical-system status do not change a zone’s level.')}</div>`;
  return panel(TX('المناطق والمعلومات الناقصة','Zones and missing information'),`<span class="cnt">${A.zones.length}</span>`,note+`<div class="feed"><table><thead><tr><th>${TX('الرمز','ID')}</th><th>${TX('المنطقة','Zone')}</th><th>${TX('المستوى المعلن','Declared level')}</th><th>${TX('المداخل','Entrances')}</th><th>${TX('الأصول','Assets')}</th><th>${TX('الناقص','Missing')}</th>${ed?'<th></th>':''}</tr></thead><tbody>${zr}</tbody></table></div>`)
    +panel(TX('حماية المداخل المسجّلة','Recorded entrance protection'),'',`<div class="feed"><table><thead><tr><th>${TX('المدخل','Entrance')}</th><th>${TX('المنطقة','Zone')}</th><th>${TX('عوامل التحقق','Factors')}</th><th>${TX('البطاقة','Card')}</th><th>${TX('ربط القارئ','Reader link')}</th><th>${TX('كاميرا','Camera')}</th>${ed?'<th></th>':''}</tr></thead><tbody>${er}</tbody></table></div>`)
    +panel(TX('الأصول (يسجّلها أمن المعلومات)','Assets (recorded by information security)'),'',`<div class="feed"><table><thead><tr><th>${TX('الرمز','ID')}</th><th>${TX('الأصل','Asset')}</th><th>${TX('المنطقة','Zone')}</th><th>${TX('تصنيف البيانات','Data classification')}</th><th>${TX('ضمن نطاق نظام حساس (CSCC)','Within a critical-system scope (CSCC)')}</th>${ed?'<th></th>':''}</tr></thead><tbody>${ar}</tbody></table></div><div class="muted-s" style="padding:8px 16px 12px">${ruleChip('CSCC-SCOPE')} ${TX('ضوابط الأنظمة الحساسة تتبع تصنيف الأصل نفسه، لا مستوى المنطقة.','Critical-system controls follow the asset’s own classification, not the zone level.')} ${CSCC_NOTE()}</div>`)
    +panel(TX('تصاريح الزوار','Visitor passes'),'',`<div class="feed"><table><thead><tr><th>${TX('التصريح','Pass')}</th><th>${TX('المناطق','Zones')}</th></tr></thead><tbody>${vr}</tbody></table></div>`);
}
function reqCells(r){
  if(!r) return `<td colspan="4"><span class="muted-s">${TX('لا تنطبق متطلبات المداخل','Entrance requirements do not apply')} ${ruleChip('NA-KIND')}</span></td>`;
  return `<td>${AREA_T()[r.area.value]} ${ruleChip(r.area.rule,r.area.ruleVersion)}</td><td class="num">${r.factors.value} ${ruleChip(r.factors.rule,r.factors.ruleVersion)}</td><td>${LINK_T[r.readerLink.value]} ${ruleChip(r.readerLink.rule)}</td><td>${r.camera.value?TX('مطلوبة','Required'):TX('غير مطلوبة','Not required')} ${ruleChip(r.camera.rule)}</td>`;
}
function asmProposal(){
  const A=POL.asm, S=asmSrc(), P=S.proposal;
  const honest=`<div class="ed-warn" role="note" style="margin:0"><b>${TX('الحساسية ليست ناتج تقييم آلي','Sensitivity is not an automated assessment')}</b><span>${TX('مستوى كل منطقة هنا هو المستوى الأساسي الذي أُدخل يدوياً في ملف المنشأة، يُنقل كما هو. الآلي في هذه الخطوة: المتطلبات لكل مستوى، ونقاط الضعف، والمعلومات الناقصة، وتنبيهات المراجعة. منهجية اقتراح الحساسية من معلومات المنشأة مطروحة للمراجعة ولم تُطبَّق (D1، docs/SENSITIVITY_METHODOLOGY.md).','Each zone’s level here is the baseline entered by hand in the facility profile, carried over unchanged. What is automatic in this step: the requirements for each level, weaknesses, missing information and review prompts. A methodology for proposing sensitivity from facility information is proposed for review and not implemented (D1, docs/SENSITIVITY_METHODOLOGY.md).')}</span></div>`;
  const rows=A.zones.map(z=>{const p=P[z.id]; return `<tr><td class="num"><b>${z.id}</b> ${zName(z)}</td><td>${lvx(p.sensitivity.value)} ${ruleChip(p.sensitivity.rule,p.sensitivity.ruleVersion)}<div class="muted-s">${esc_(sensExpl(p.sensitivity))}</div>${p.prompts.map(x=>`<div class="muted-s">↳ ${ruleChip(x.rule)} ${esc_(promptTxt(x))}</div>`).join('')}</td>${reqCells(p.requirements)}</tr>`;}).join('');
  const F=S.findings||[], SV=ASM_SEV();
  const fr=F.map(f=>`<tr><td>${XB(f.severity==='crit'||f.severity==='high'?'no':'ref',SV[f.severity])}</td><td class="num">${esc_(f.entrance||f.pass)} · ${f.zoneId}</td><td>${esc_(FIELD_T()[f.type]||f.type)}: <span class="num">${esc_(String(f.current))}</span> → <span class="num">${esc_(String(f.required))}</span></td><td>${ruleChip(f.rule,f.ruleVersion)}</td></tr>`).join('');
  return honest+panel(TX('المستوى الأساسي والمتطلبات لكل منطقة','Baseline and requirements per zone'),`<span class="muted-s">${TX('إصدار القواعد','Rules version')} <span class="num">${esc_(A.rulesVersion)}</span></span>`,`<div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('المستوى الأساسي المعلن (يدوي)','Declared baseline (manual)')}</th><th>${TX('نوع المنطقة','Area type')}</th><th>${TX('عوامل التحقق','Factors')}</th><th>${TX('ربط القارئ','Reader link')}</th><th>${TX('كاميرا المدخل','Entrance camera')}</th></tr></thead><tbody>${rows}</tbody></table></div>`)
    +panel(TX('نقاط الضعف: الحماية المسجّلة مقابل المطلوب','Weaknesses: recorded protection against the requirement'),`<span class="cnt">${F.length}</span>`,`<div class="feed"><table><thead><tr><th>${TX('الخطورة','Severity')}</th><th>${TX('الموقع','Where')}</th><th>${TX('الفرق','Gap')}</th><th>${TX('القاعدة','Rule')}</th></tr></thead><tbody>${fr||`<tr><td colspan="4">${TX('لا توجد','None')}</td></tr>`}</tbody></table></div>`)
    +asmRules();
}
function asmRules(){
  const R=POL.asm.rules||{};
  return panel(TX('القواعد ومراجعها','Rules and their references'),`<span class="cnt">${Object.keys(R).length}</span>`,`<div class="muted-s" style="padding:10px 16px 0">${TX('«من المرجع»: المتطلب منصوص عليه في المرجع المذكور. «قاعدة تصميم»: اختيار صون، والمرجع إن وُجد يدعم الموضوع لا الحد. لا يدّعي صون الامتثال أو الاعتماد لأي مرجع.','“From the reference”: the requirement is stated by the cited reference. “SAWN design rule”: SAWN’s choice; a cited reference supports the topic, not the threshold. SAWN claims no compliance with or certification against any reference.')}</div><div class="feed"><table><thead><tr><th>${TX('القاعدة','Rule')}</th><th>${TX('النص','Text')}</th><th>${TX('المرجع','Reference')}</th></tr></thead><tbody>${Object.entries(R).map(([id,r])=>`<tr><td>${ruleChip(id)}</td><td><bdi dir="auto">${esc_(ruleTitle(id))}</bdi>${r.note?`<div class="muted-s">${esc_(TX('تصنيف البيانات وحساسية المنطقة مقياسان مختلفان (القرار D1).',r.note))}</div>`:''}</td><td class="muted-s"><bdi dir="ltr">${esc_(r.ref||'—')}</bdi></td></tr>`).join('')}</tbody></table></div>`);
}
function asmReview(){
  const A=POL.asm, D=A.draft, act=asmAct(), ed=coreCan('policy.draft'), rk=coreCan('risk.accept');
  const S=asmSrc(), P=S.proposal;
  const rows=A.zones.map(z=>{const adj=D&&D.adjustments[z.id], ov=D&&D.overrides[z.id], lvl=D?D.levels[z.id]:act.zoneLevels[z.id];
    return `<tr${adj||ov?' class="ovr"':''}><td class="num"><b>${z.id}</b> ${zName(z)}</td><td>${lvx(P[z.id].sensitivity.value)}</td><td>${lvx(lvl??null)}${adj?`<div class="muted-s">${esc_(adj.by)}: ${esc_(adj.reason)}</div>`:''}</td><td>${lvx(act.zoneLevels[z.id]??null)}</td><td>${ov?`<span class="num">${esc_(JSON.stringify(ov.req))}</span><div class="muted-s">${esc_(ov.by)}: ${esc_(ov.reason)}${ov.exception?` · ${TX('استثناء معتمد من','exception by')} ${esc_(ov.exception)}`:''}</div>`:'—'}</td><td><div class="row-c" style="gap:4px;flex-wrap:wrap">${ed?`<button class="btn sm" data-adj="${z.id}">${TX('تعديل المستوى','Adjust level')}</button>${adj?`<button class="btn sm" data-adjclr="${z.id}">${TX('العودة للمقترح','Back to proposal')}</button>`:''}<button class="btn sm" data-req="${z.id}">${TX('المتطلبات','Requirements')}</button>`:''}${rk&&ov&&!ov.exception?`<button class="btn sm warn" data-excz="${z.id}">${TX('اعتماد استثناء','Authorize exception')}</button>`:''}</div></td></tr>`;}).join('');
  const F=S.findings||[], ex=(D&&D.exceptions)||{};
  const fr=F.map(f=>`<tr><td class="num">${esc_(f.key)}</td><td>${lvx(f.level)}</td><td>${ex[f.key]?`${XB('open',TX(`مقبولة ${ex[f.key].days} يوماً`,`Accepted ${ex[f.key].days} days`))}<div class="muted-s">${esc_(ex[f.key].by)}: ${esc_(ex[f.key].reason)}</div>`:XB('mut',TX('مفتوحة','Open'))}</td><td>${rk&&D?(ex[f.key]?`<button class="btn sm" data-excw="${esc_(f.key)}">${TX('سحب القبول','Withdraw')}</button>`:`<button class="btn sm" data-exca="${esc_(f.key)}" data-lvl="${f.level}">${TX('قبول مؤقت','Accept temporarily')}</button>`):''}</td></tr>`).join('');
  const who=!ed&&!rk?`<div class="muted-s" style="padding:12px 16px">${TX('دورك يسمح بالاطلاع فقط. يُعدّ التقييم مدير الأمن المادي ومدير أمن المعلومات، ويسجّل الاستثناءات مدير الأمن المادي، ويعتمد مدير الأمن.','Your role can view only. The physical security manager and the information security manager prepare the assessment, the physical security manager records exceptions, and the chief security officer approves.')}</div>`:'';
  return who+panel(TX('الأساسي المعلن والمعدّل والنشط','Declared baseline, adjusted and active'),D?`<span class="st draft">${D.ref} · ${TX('مراجعة','revision')} <span class="num">${D.revision}</span></span>`:`<span class="muted-s">${TX('أي تعديل يبدأ مسودة جديدة','Any change starts a new draft')}</span>`,`<div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('الأساسي المعلن','Declared baseline')}</th><th>${TX('المعدّل','Adjusted')}</th><th>${TX('النشط','Active')}</th><th>${TX('متطلبات معدّلة','Changed requirements')}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`)
    +panel(TX('قبول نقاط الضعف (استثناءات)','Weakness acceptance (exceptions)'),`<span class="muted-s">${ruleChip('ACCEPT-L5')} ${ruleChip('ACCEPT-L4-30')} ${ruleChip('ACCEPT-MAX-90')}</span>`,`<div class="feed"><table><thead><tr><th>${TX('نقطة الضعف','Weakness')}</th><th>${TX('المستوى','Level')}</th><th>${TX('الحالة','State')}</th><th></th></tr></thead><tbody>${fr||`<tr><td colspan="4">${TX('لا توجد','None')}</td></tr>`}</tbody></table></div>${!D&&rk?`<div class="muted-s" style="padding:8px 16px 12px">${TX('القبول يُسجَّل على مسودة، ويسري فقط عند اعتمادها.','Acceptance is recorded on a draft and takes effect only when it is approved.')}</div>`:''}`)
    +(D?panel(TX('سجل المسودة','Draft history'),`<span class="cnt">${D.history.length}</span>`,`<div class="feed"><table><thead><tr><th>${TX('الوقت','Time')}</th><th>${TX('المستخدم','User')}</th><th>${TX('التغيير','Change')}</th><th>${TX('المراجعة','Revision')}</th></tr></thead><tbody>${D.history.slice().reverse().map(h=>`<tr><td class="num">${dShort(h.at)} ${new Date(h.at).toTimeString().slice(0,5)}</td><td>${esc_(h.by)}</td><td>${esc_(histTxt(h.what))}${h.detail?`<div class="muted-s">${esc_(h.detail)}</div>`:''}</td><td class="num">${h.revision}</td></tr>`).join('')}</tbody></table></div>`):'');
}
function checkRows(list){
  const C=CAT();
  return list.map(c=>`<tr><td>${XB(C[c.category][0],C[c.category][1])}</td><td class="num">${esc_(c.zoneId||'—')}</td><td style="white-space:normal"><bdi dir="auto">${esc_(checkTxt(c))}</bdi>${c.reason?`<div class="muted-s">${TX('سبب التعديل','Adjustment reason')}: ${esc_(c.reason)}</div>`:''}</td><td>${ruleChip(c.rule,c.ruleVersion)}</td></tr>`).join('');
}
function asmImpact(){
  const D=POL.asm.draft;
  if(!D) return panel(TX('أثر التغيير','Change impact'),'',`<div class="empty"><span>${TX('لا توجد مسودة. التحقق من الأثر يظهر عند أول تعديل.','No draft. The impact checks appear with the first change.')}</span></div>`);
  const by=k=>D.checks.filter(c=>c.category===k);
  const counts=Object.entries(CAT()).map(([k,[cls,t]])=>`<span class="xbdg ${cls}">${t} <span class="num">${by(k).length}</span></span>`).join(' ');
  return panel(TX('أثر التغيير قبل الاعتماد','Change impact before approval'),`<span class="row-c" style="gap:4px;flex-wrap:wrap">${counts}</span>`,`<div class="muted-s" style="padding:10px 16px 0">${TX('يقارن المقترح الأصلي بالقيمة المعدّلة وبالسياسة النشطة، ويبيّن ما يتغيّر في المتطلبات وأولوية الحوادث الجديدة وقيود الأجهزة عند البوابات. ما لا يمكن تقييمه يُكتب صراحة ولا يُعرض كأنه آمن.','Compares the original proposal with the adjusted value and the active policy, and shows what changes in requirements, in the priority of new incidents and in device restrictions at gates. What cannot be evaluated says so and is never shown as safe.')}</div><div class="feed"><table><thead><tr><th>${TX('الفئة','Category')}</th><th>${TX('المنطقة','Zone')}</th><th>${TX('الأثر','Effect')}</th><th>${TX('القاعدة','Rule')}</th></tr></thead><tbody>${checkRows(D.checks)||`<tr><td colspan="4">${TX('لا يوجد أثر','No effect')}</td></tr>`}</tbody></table></div>`);
}
function asmApprove(){
  const D=POL.asm.draft, me=CORE.user&&CORE.user.username;
  if(!D) return panel(TX('الاعتماد','Approval'),'',`<div class="empty"><span>${TX('لا توجد مسودة لاعتمادها.','There is no draft to approve.')}</span></div>`);
  const warn=D.checks.filter(c=>c.category==='warning'), blk=D.blockers||[];
  const head=`<div class="sform"><div class="srow"><div><b>${D.ref} · ${TX('المراجعة','revision')} <span class="num">${D.revision}</span></b><span>${TX('عدّلها','Edited by')} ${esc_(D.editedBy.join(TX('، ',', ')))} · ${TX('إصدار القواعد','rules')} <span class="num">${esc_(D.rulesVersion||'')}</span> · ${TX('لا تؤثر على أي قرار قبل الاعتماد','affects no decision until approved')}</span></div><span class="dotst warn">${TX('مسودة','Draft')}</span></div></div>`;
  let body='';
  if(!coreCan('policy.approve')) body=`<div class="muted-s" style="padding:12px 16px">${TX('يعتمد السياسةَ مديرُ الأمن، ولا يعتمدها من عدّل المسودة.','The chief security officer approves the policy; nobody who edited the draft may approve it.')}</div>`;
  else if(D.editedBy.includes(me)) body=`<div class="muted-s" style="padding:12px 16px">${TX('عدّلتَ هذه المسودة، فيعتمدها شخص آخر يملك صلاحية الاعتماد (قاعدة الشخصين).','You edited this draft, so someone else with approval authority approves it (two-person rule).')}</div>`;
  else {
    ackRestore(D);
    const miss=new Set((POL.apErr&&POL.apErr.missing)||[]);
    body=(POL.apErr?`<div class="ed-warn" role="alert" id="apErr" style="margin:12px 16px"><b>${TX('لم تُعتمد السياسة','Not approved')}</b><span>${esc_(POL.apErr.text)}</span>${miss.size?`<span>${TX('تحذيرات بلا سبب','Warnings without a reason')}: <bdi dir="ltr">${[...miss].map(esc_).join(' · ')}</bdi></span>`:''}</div>`:'')
      +(blk.length?`<div class="ed-warn" role="alert" style="margin:12px 16px"><b>${TX('ما يمنع الاعتماد','What blocks approval')}</b>${blk.map(b=>{const c=D.checks.find(x=>x.id===b.id); return `<span><bdi dir="auto">${esc_(c?checkTxt(c):b.text)}</bdi>${b.why==='exception-missing'?` — ${TX('لم يُسجَّل استثناء من دور مخوّل','no exception recorded by an authorized role')}`:''}</span>`;}).join('')}</div>`:'')
      +(warn.length?`<div class="muted-s" style="padding:10px 16px 0">${TX('الإقرار بتحذير يسجّل أنك اطلعت عليه وسبب المضي في الاعتماد؛ ليس قبولاً لمخاطرة ولا استثناءً، ولا يغلق ثغرات الحماية المفتوحة.','Acknowledging a warning records that you read it and why approval proceeds; it is not a risk acceptance or an exception, and it closes no open protection gap.')} <b id="ackCount"></b></div><div class="sform">${warn.map(c=>`<label class="mf"><span>${XB('ref',TX('تحذير','Warning'))} <span class="num muted-s" dir="ltr">${esc_(c.id)}</span> <bdi dir="auto">${esc_(checkTxt(c))}</bdi> ${ruleChip(c.rule,c.ruleVersion)}</span><textarea class="inp" rows="2" data-ack="${esc_(c.id)}" aria-invalid="${miss.has(c.id)?'true':'false'}" placeholder="${TX('سبب الإقرار (5 أحرف على الأقل)','Reason for acknowledging (at least 5 characters)')}">${esc_(POL.acks[c.id]||'')}</textarea></label>`).join('')}</div>`:`<div class="muted-s" style="padding:12px 16px">${TX('لا توجد تحذيرات تحتاج إقراراً.','No warnings need acknowledgement.')}</div>`)
      +`<div class="m-f" style="padding:0 16px 16px"><button class="btn pri" id="asmApprove" ${blk.length?'disabled':''}>${TX(`اعتماد ${D.ref} (المراجعة ${D.revision}) كسياسة نشطة`,`Approve ${D.ref} (revision ${D.revision}) as the active policy`)}</button></div>`;
  }
  const disc=coreCan('policy.draft')?`<button class="btn sm" id="asmDiscard">${TX('إلغاء المسودة','Discard draft')}</button>`:'';
  return panel(TX('الاعتماد','Approval'),disc,head+body);
}
function asmActive(){
  const A=POL.asm, SV=ASM_SEV(), R=A.remediation||{}, rm=coreCan('remediation.manage');
  if(!A.active) return panel(TX('السياسة النشطة','Active policy'),'',`<div class="ed-warn" role="note" style="margin:12px 16px"><b>${NO_POLICY()}</b><span>${TX('لم يعتمد أحد سياسة بعد. حتى يحدث ذلك: لا تُضاف حساسية المنطقة إلى أولوية الحوادث (ويُكتب ذلك في عواملها)، وتعامل البوابة كل منطقة كمستوى 5. يعتمد المسودةَ من يملك صلاحية الاعتماد من الخطوة 5.','Nobody has approved a policy yet. Until then, zone sensitivity adds nothing to incident priority (the factors say so) and the gate treats every zone as Level 5. Someone with approval authority approves the draft in step 5.')}</span></div>`);
  const act=A.active;
  const mx=act.priorityMatrix.map(r=>{const z=asmZone(r.zoneId); return `<tr><td class="num"><b>${r.zoneId}</b> ${zName(z)}</td><td>${lvx(r.level)}</td>${['low','mid','high','crit'].map(s=>`<td class="num">${r.bySeverity[s]}</td>`).join('')}</tr>`;}).join('');
  const ap=act.approval;
  const hist=(A.versions||[]).map(v=>`<tr><td class="num"><b>${v.ref}</b></td><td>${v.status==='active'?XB('ok',TX('نشطة','Active')):v.status==='draft'?XB('ref',TX('مسودة','Draft')):XB('mut',TX('سابقة','Superseded'))}</td><td class="num">${v.revision}</td><td>${esc_((v.editedBy||[]).join(', ')||v.createdBy)}</td><td>${esc_(v.approvedBy||'—')}</td><td class="num">${v.approvedAt?dShort(v.approvedAt):'—'}</td><td class="num">${v.approval?v.approval.acknowledged.length:'—'}</td></tr>`).join('');
  const F=act.findings||[];
  const fr=F.map(f=>{const r=R[f.key], ex=(act.exceptions||{})[f.key]; return `<tr><td>${XB(f.severity==='crit'||f.severity==='high'?'no':'ref',SV[f.severity])}</td><td class="num">${esc_(f.key)}</td><td>${ex?XB('open',TX(`مقبولة ${ex.days} يوماً`,`Accepted ${ex.days} days`)):r?(r.status==='fixed'?XB('ref',TX('بُلّغ بالإصلاح · يُتحقق عند تحديث المعلومات','Reported fixed · verified when information is updated')):XB('ok',`${esc_(r.owner)}${r.due?` · ${r.due}`:''}`)):XB('mut',TX('مفتوحة','Open'))}</td><td>${rm&&!ex?`<div class="row-c" style="gap:4px">${!r?`<button class="btn sm" data-rmA="${esc_(f.key)}">${TX('إسناد','Assign')}</button>`:r.status==='assigned'?`<button class="btn sm" data-rmF="${esc_(f.key)}">${TX('تم الإصلاح','Fixed')}</button><button class="btn sm" data-rmO="${esc_(f.key)}">${TX('إلغاء الإسناد','Unassign')}</button>`:''}</div>`:''}</td></tr>`;}).join('');
  const closed=Object.entries(R).filter(([,v])=>v.status==='closed');
  return notHumanBanner(act)+panel(TX('كيف تؤثر السياسة النشطة على الحوادث الجديدة','How the active policy affects new incidents'),`<span class="num">${act.ref}</span>`,`<div class="muted-s" style="padding:10px 16px 0">${ruleChip('PRIO-1')} ${TX('الأولوية = خطورة الحادثة، +1 في المستوى 5، +0.5 في المستوى 4، −0.5 إذا كانت ثقة الكشف أقل من 60٪. حساسية المنطقة لا تثبت وقوع الحادثة ولا تجعل كل حادثة حرجة، والتحقق قرار بشري. الحوادث السابقة تحتفظ بنسخة السياسة وعوامل الأولوية التي سُجّلت بها.','Priority = incident severity, +1 at level 5, +0.5 at level 4, −0.5 when detection confidence is below 60 %. Zone sensitivity neither proves an incident happened nor makes every incident critical; verification is a person’s decision. Earlier incidents keep the policy version and priority factors they were recorded with.')}</div><div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('المستوى','Level')}</th><th>${SV.low}</th><th>${SV.mid}</th><th>${SV.high}</th><th>${SV.crit}</th></tr></thead><tbody>${mx}</tbody></table></div>`)
    +(ap?panel(TX('سجل اعتماد النسخة النشطة','Approval record of the active version'),'',`<div class="sform"><div class="srow"><div><b>${act.ref} · ${TX('المراجعة','revision')} <span class="num">${ap.revision}</span></b><span>${TX('اعتمدها','Approved by')} ${esc_(ap.approvedBy)} · <span class="num">${dShort(ap.approvedAt)} ${new Date(ap.approvedAt).toTimeString().slice(0,5)}</span> · ${TX('عدّلها','edited by')} ${esc_(ap.editors.join(', '))} · ${TX('القواعد','rules')} <span class="num">${esc_(ap.rulesVersion)}</span> · ${TX('بدلاً من','replaces')} ${esc_(ap.replaces)}</span></div></div>${ap.acknowledged.map(w=>`<div class="srow"><div><b>${ruleChip(w.rule)}</b><span><bdi dir="auto">${esc_(w.text)}</bdi> — ${TX('السبب','reason')}: ${esc_(w.reason)}</span></div></div>`).join('')}${ap.exceptions.map(w=>`<div class="srow"><div><b>${ruleChip(w.rule)} ${XB('open',TX('استثناء','Exception'))}</b><span>${esc_(w.id)} · ${esc_(w.authorizedBy||'')} · ${esc_(w.reason||'')}</span></div></div>`).join('')}</div>`):'')
    +panel(TX('معالجة نقاط الضعف في السياسة النشطة','Remediation of weaknesses in the active policy'),`<span class="cnt">${F.length}</span>`,`<div class="feed"><table><thead><tr><th>${TX('الخطورة','Severity')}</th><th>${TX('نقطة الضعف','Weakness')}</th><th>${TX('الحالة','State')}</th><th></th></tr></thead><tbody>${fr||`<tr><td colspan="4">${TX('لا توجد','None')}</td></tr>`}</tbody></table></div>${closed.length?`<div class="muted-s" style="padding:8px 16px 12px">${TX('أُغلقت بعد إعادة التقييم','Closed after reassessment')}: ${closed.map(([k])=>`<span class="num">${esc_(k)}</span>`).join(' ')}</div>`:''}`)
    +panel(TX('نسخ السياسة','Policy versions'),'',`<div class="feed"><table><thead><tr><th>${TX('النسخة','Version')}</th><th>${TX('الحالة','State')}</th><th>${TX('المراجعة','Revision')}</th><th>${TX('عدّلها','Edited by')}</th><th>${TX('اعتمدها','Approved by')}</th><th>${TX('التاريخ','Date')}</th><th>${TX('تحذيرات مُقرّة','Warnings acknowledged')}</th></tr></thead><tbody>${hist}</tbody></table></div>`);
}
function vAssessment(){
  if(!coreCan('assessment.view')) return ph(TX('المنشأة والسياسة','Facility & policy'),TX('تقييم المنشأة','Facility assessment'))+panel('','',`<div class="empty"><span>${TX('دورك لا يشمل الاطلاع على التقييم.','Your role does not include the assessment.')}</span></div>`);
  if(!POL.asm){ asmLoad().then(()=>{ if(POL.asm) safeRender(); }); return ph(TX('المنشأة والسياسة','Facility & policy'),TX('تقييم المنشأة','Facility assessment'))+panel('','',`<div class="empty"><span>${TX('جارٍ تحميل التقييم…','Loading the assessment…')}</span></div>`); }
  if(zmOn()) return vZoneModel();
  const A=POL.asm, D=A.draft, st=ASM_STEPS(), s=POL.step;
  const nav=`<section class="panel"><div class="vsteps">${st.map((x,i)=>`<button class="vs ${i===s?'cur':''}" data-asm="${i}" ${i===s?'aria-current="step"':''}><span class="b">${i+1}</span><span class="l">${x[0]}<span class="r">${x[1]}</span></span></button>`).join('')}</div>
    <dl class="as-m" style="padding:10px 16px">${[[TX('السياسة النشطة','Active policy'),A.active?`<span class="num">${A.active.ref}</span>${notHuman(A.active)?` ${XB('ref',A.active.seeded?TX('مزروعة','seeded'):TX('بلا اعتماد بشري','no human approval'))}`:''}`:XB('no',NO_POLICY())],[TX('المسودة','Draft'),D?`<span class="num">${D.ref} · r${D.revision}</span>`:'—'],[TX('ما يمنع الاعتماد','Blocking items'),D?`<span class="num">${(D.blockers||[]).length}</span>`:'—'],[TX('تحذيرات','Warnings'),D?`<span class="num">${D.checks.filter(c=>c.category==='warning').length}</span>`:'—']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section>`;
  const view=[asmInputs,asmProposal,asmReview,asmImpact,asmApprove,asmActive][s]();
  const stt=D?`<span class="st draft">${TX('مسودة','Draft')} ${D.ref}</span>`:A.active?`<span class="st ok">${TX('نشطة','Active')} ${A.active.ref}</span>`:`<span class="st draft">${NO_POLICY()}</span>`;
  return ph(TX('المنشأة والسياسة','Facility & policy'),TX('تقييم المنشأة','Facility assessment'),' '+stt)
    +zStartPanel()+`<div class="asx">${nav}<div style="display:grid;gap:12px;min-width:0">${view}<div style="display:flex;justify-content:space-between;gap:8px"><button class="btn" data-asm="${Math.max(0,s-1)}" ${s===0?'disabled':''}>${TX('السابق','Previous')}</button>${s<5?`<button class="btn pri" data-asm="${s+1}">${TX('التالي','Next')}</button>`:''}</div></div></div>`;
}

/* ---------- actions (the server checks every one of them) ---------- */
/* Approval acknowledgements. What the approver sees in each reason field is what is sent: the fields are read at the
   moment of approval. Unsent reasons are kept in this browser for this exact draft revision only (a reload keeps
   them; another revision never inherits them) and are cleared only when the server accepts the approval. Missing
   reasons are named before anything is sent; a refusal keeps every reason and the approval step, with the
   server's reason. An acknowledgement is not a risk acceptance or an exception. */
const ackKey=D=>`sawn.acks.${D.id}.${D.revision}`;
function ackRestore(D){ try{ const s=JSON.parse(localStorage.getItem(ackKey(D))||'null'); if(s&&typeof s==='object') for(const [k,v] of Object.entries(s)) if(typeof v==='string'&&!String(POL.acks[k]||'').trim()) POL.acks[k]=v; }catch(e){} }
function ackSave(D){ try{ if(D) localStorage.setItem(ackKey(D),JSON.stringify(POL.acks)); }catch(e){} }
function ackClear(D){ try{ const p=`sawn.acks.${D.id}.`; Object.keys(localStorage).filter(k=>k.startsWith(p)).forEach(k=>localStorage.removeItem(k)); }catch(e){} }
function bindAcks(C, D){
  const cnt=C.querySelector('#ackCount'), tot=C.querySelectorAll('[data-ack]').length;
  const paint=()=>{ if(cnt) cnt.textContent=TX(`أسباب مكتوبة: ${[...C.querySelectorAll('[data-ack]')].filter(t=>t.value.trim().length>=5).length} من ${tot}`,`Reasons written: ${[...C.querySelectorAll('[data-ack]')].filter(t=>t.value.trim().length>=5).length} of ${tot}`); };
  C.querySelectorAll('[data-ack]').forEach(t=>t.oninput=()=>{ POL.acks[t.dataset.ack]=t.value; ackSave(D); if(t.value.trim().length>=5) t.setAttribute('aria-invalid','false'); paint(); });
  paint();
}
/* returns 'approved' | 'missing' | 'refused' | 'cancelled' */
async function asmSubmitApproval(C, D, confirmText, okMsg){
  if(POL.busy) return 'cancelled';
  C.querySelectorAll('[data-ack]').forEach(t=>{ POL.acks[t.dataset.ack]=t.value; });
  ackSave(D);
  const warn=D.checks.filter(c=>c.category==='warning');
  const acks=Object.fromEntries(warn.map(c=>[c.id,String(POL.acks[c.id]||'').trim()]));
  const missing=warn.filter(c=>acks[c.id].length<5).map(c=>c.id);
  if(missing.length){ POL.apErr={missing, text:TX(`لم يُرسل طلب الاعتماد: ${missing.length} من ${warn.length} تحذيرات بلا سبب إقرار (5 أحرف على الأقل). أكمل الحقول المعلّمة ثم اعتمد.`,`The approval was not sent: ${missing.length} of ${warn.length} warnings have no acknowledgement reason (at least 5 characters). Complete the marked fields, then approve.`)}; return 'missing'; }
  POL.apErr=null;
  if(!(await confirmAsk(confirmText,TX('اعتماد','Approve')))) return 'cancelled';
  POL.busy=true;
  try{ await api('assessment/approve',{method:'POST',body:JSON.stringify({draftId:D.id,revision:D.revision,acknowledgements:acks})}); }
  catch(e){ POL.apErr={missing:[], text:TX('رفض الخادم الاعتماد ولم يتغير شيء. أسباب الإقرار باقية في الحقول. سبب الرفض: ','The server refused the approval; nothing changed. Your reasons are still in the fields. Reason: ')+e.message}; try{ await asmLoad(); }catch(x){} POL.busy=false; return 'refused'; }
  ackClear(D); POL.acks={}; POL.apErr=null;
  try{ await asmLoad(); await polLoad(); }catch(e){}
  POL.busy=false; toast(okMsg); return 'approved';
}
async function asmDo(path, body, ok){
  if(POL.busy) return; POL.busy=true;
  try{ await api(path,{method:'POST',body:JSON.stringify(body||{})}); await asmLoad(); await polLoad(); if(ok) toast(ok); }catch(e){ toast(e.message); await asmLoad(); }
  finally{ POL.busy=false; safeRender(); }
}
const asmRev=()=>POL.asm&&POL.asm.draft?POL.asm.draft.revision:null;
const REASON=()=>({name:'reason',label:TX('السبب (مطلوب)','Reason (required)'),type:'textarea',required:true});
function bindAssessment(C){
  if(POL.asm&&zmOn()){ bindZoneModel(C); return; }
  bindZoneStart(C);
  C.querySelectorAll('[data-asm]').forEach(b=>b.onclick=()=>{ POL.step=+b.dataset.asm; safeRender(); window.scrollTo(0,0); });
  const A=POL.asm; if(!A) return;
  const S=asmSrc(), I=S.inputs;
  const on=(sel,fn)=>C.querySelectorAll(sel).forEach(b=>b.onclick=()=>fn(b));
  on('[data-adj]',async b=>{ const z=b.dataset.adj, cur=A.draft?A.draft.levels[z]:asmAct().zoneLevels[z];
    const r=await askForm(TX(`تعديل مستوى ${z}`,`Adjust the level of ${z}`),[{name:'level',label:TX('المستوى','Level'),type:'select',options:[1,2,3,4,5].map(n=>[n,String(n)]),value:cur??''},REASON()],TX('حفظ في المسودة','Save to draft')); if(!r) return;
    asmDo('assessment/adjust',{zoneId:z,level:+r.level,reason:r.reason,revision:asmRev()},TX('حُفظ في المسودة · لا يؤثر قبل الاعتماد','Saved to the draft · no effect until approved')); });
  on('[data-adjclr]',async b=>{ const r=await askForm(TX('العودة للمستوى المقترح','Back to the proposed level'),[REASON()]); if(!r) return; asmDo('assessment/adjust',{zoneId:b.dataset.adjclr,level:null,reason:r.reason,revision:asmRev()}); });
  on('[data-req]',async b=>{ const z=b.dataset.req, ov=(A.draft&&A.draft.overrides[z]||{}).req||{};
    const r=await askForm(TX(`متطلبات ${z}`,`Requirements for ${z}`),[{name:'factors',label:TX('عوامل التحقق','Factors'),type:'select',options:[['',TX('حسب القاعدة','By rule')],[1,'1'],[2,'2'],[3,'3']],value:ov.factors??''},{name:'readerLink',label:TX('ربط القارئ','Reader link'),type:'select',options:[['',TX('حسب القاعدة','By rule')],...Object.entries(LINK_T)],value:ov.readerLink??''},{name:'camera',label:TX('كاميرا المدخل','Entrance camera'),type:'select',options:[['',TX('حسب القاعدة','By rule')],['1',TX('مطلوبة','Required')],['0',TX('غير مطلوبة','Not required')]],value:ov.camera==null?'':ov.camera?'1':'0'},REASON()],TX('حفظ في المسودة','Save to draft')); if(!r) return;
    const req={}; if(r.factors) req.factors=+r.factors; if(r.readerLink) req.readerLink=r.readerLink; if(r.camera) req.camera=r.camera==='1';
    asmDo('assessment/requirement',{zoneId:z,req:Object.keys(req).length?req:null,reason:r.reason,revision:asmRev()},TX('حُفظ · خفض المتطلب يحتاج استثناءً معتمداً','Saved · lowering a requirement needs an authorized exception')); });
  on('[data-excz]',async b=>{ const r=await askForm(TX('اعتماد استثناء للمتطلب','Authorize the requirement exception'),[REASON()],TX('اعتماد الاستثناء','Authorize')); if(!r) return; asmDo('assessment/exception',{zoneId:b.dataset.excz,reason:r.reason,revision:asmRev()},TX('سُجّل الاستثناء','Exception recorded')); });
  on('[data-exca]',async b=>{ const l=+b.dataset.lvl, opts=(l===4?[7,30]:[7,30,90]).map(n=>[n,TX(`${n} يوماً`,`${n} days`)]);
    const r=await askForm(TX('قبول نقطة ضعف مؤقتاً','Accept a weakness temporarily'),[{name:'days',label:TX('المدة','Duration'),type:'select',options:opts,value:30},REASON()],TX('قبول','Accept')); if(!r) return;
    asmDo('assessment/exception',{findingKey:b.dataset.exca,days:+r.days,reason:r.reason,revision:asmRev()},TX('سُجّل القبول في المسودة','Acceptance recorded on the draft')); });
  on('[data-excw]',b=>asmDo('assessment/exception/withdraw',{findingKey:b.dataset.excw,revision:asmRev()},TX('سُحب القبول','Acceptance withdrawn')));
  on('[data-in-zone]',async b=>{ const z=b.dataset.inZone, cur=I.zones[z]?.declaredLevel;
    const r=await askForm(TX(`المستوى المعلن لـ ${z}`,`Declared level of ${z}`),[{name:'level',label:TX('المستوى المعلن','Declared level'),type:'select',options:[['',TX('غير محدد','Undetermined')],...[1,2,3,4,5].map(n=>[n,String(n)])],value:cur??''},REASON()]); if(!r) return;
    asmDo('assessment/inputs',{inputs:{zones:{...I.zones,[z]:{declaredLevel:r.level===''?null:+r.level}}},reason:r.reason,revision:asmRev()}); });
  on('[data-in-ent]',async b=>{ const g=b.dataset.inEnt, e=I.entrances.find(x=>x.gate===g);
    const r=await askForm(TX(`حماية المدخل ${g}`,`Protection at entrance ${g}`),[{name:'factors',label:TX('عوامل التحقق','Factors'),type:'select',options:[['','—'],[1,'1'],[2,'2'],[3,'3']],value:e.factors??''},{name:'cardTech',label:TX('البطاقة','Card'),type:'select',options:[['','—'],...Object.entries(ASM_CARD())],value:e.cardTech??''},{name:'readerLink',label:TX('ربط القارئ','Reader link'),type:'select',options:[['','—'],['W','Wiegand'],['O','OSDP'],['OS',LINK_T.OS]],value:e.readerLink??''},{name:'camera',label:TX('كاميرا','Camera'),type:'select',options:[['','—'],['1',TX('نعم','Yes')],['0',TX('لا','No')]],value:e.camera==null?'':e.camera?'1':'0'},REASON()]); if(!r) return;
    const ne={gate:g,factors:r.factors===''?null:+r.factors,cardTech:r.cardTech||null,readerLink:r.readerLink||null,camera:r.camera===''?null:r.camera==='1'};
    asmDo('assessment/inputs',{inputs:{entrances:I.entrances.map(x=>x.gate===g?ne:x)},reason:r.reason,revision:asmRev()}); });
  on('[data-in-asset]',async b=>{ const id=b.dataset.inAsset, a=I.assets.find(x=>x.id===id);
    const r=await askForm(TX(`الأصل ${id}`,`Asset ${id}`),[{name:'classification',label:TX('تصنيف البيانات','Data classification'),type:'select',options:[['','—'],...Object.entries(CLS_T())],value:a.classification??''},{name:'criticalSystem',label:TX('ضمن نطاق نظام حساس (CSCC): نظام أو مكوّن داعم','Within a critical-system scope (CSCC): a system or a supporting component'),type:'select',options:[['',TX('غير مسجّل','Not recorded')],['1',TX('نعم','Yes')],['0',TX('لا','No')]],value:a.criticalSystem==null?'':a.criticalSystem?'1':'0'},REASON()]); if(!r) return;
    const na={...a,classification:r.classification||null,criticalSystem:r.criticalSystem===''?null:r.criticalSystem==='1'};
    asmDo('assessment/inputs',{inputs:{assets:I.assets.map(x=>x.id===id?na:x)},reason:r.reason,revision:asmRev()}); });
  bindAcks(C, A.draft);
  const ap=C.querySelector('#asmApprove'); if(ap) ap.onclick=async()=>{ const D=A.draft;
    const r=await asmSubmitApproval(C,D,TX(`اعتماد ${D.ref} (المراجعة ${D.revision})؟ ستُستخدم مستوياتها للحوادث الجديدة وقرارات البوابة، وتحتفظ الحوادث السابقة بنسختها.`,`Approve ${D.ref} (revision ${D.revision})? Its levels will be used for new incidents and gate decisions; earlier incidents keep their version.`),TX(`${D.ref} معتمدة ونشطة الآن`,`${D.ref} is approved and active`));
    if(r==='approved') POL.step=5; else if(r!=='cancelled') toast(TX('لم تُعتمد السياسة — التفاصيل في خطوة الاعتماد','Not approved — details on the approval step'));
    safeRender(); if(r==='missing'||r==='refused') setTimeout(()=>{ const e=document.getElementById('apErr'); if(e) e.scrollIntoView({block:'center'}); },60); };
  const ds=C.querySelector('#asmDiscard'); if(ds) ds.onclick=async()=>{ if(await confirmAsk(TX('إلغاء المسودة؟ تبقى السياسة النشطة كما هي.','Discard the draft? The active policy stays as it is.'),TX('إلغاء المسودة','Discard'))) asmDo('assessment/discard',{},TX('أُلغيت المسودة','Draft discarded')); };
  on('[data-rmA]',async b=>{ const r=await askForm(TX('إسناد المعالجة','Assign remediation'),[{name:'owner',label:TX('المسؤول','Owner'),required:true},{name:'due',label:TX('الموعد النهائي','Due date'),type:'date',attrs:'dir="ltr"'},{name:'note',label:TX('ملاحظة','Note'),type:'textarea'}]); if(!r) return; asmDo('assessment/remediation',{key:b.dataset.rma,status:'assigned',owner:r.owner,due:r.due||null,note:r.note},TX('أُسندت المعالجة','Remediation assigned')); });
  on('[data-rmF]',b=>asmDo('assessment/remediation',{key:b.dataset.rmf,status:'fixed'},TX('سُجّل الإصلاح · يُتحقق عند تحديث معلومات المنشأة واعتمادها','Recorded · verified when the facility information is updated and approved')));
  on('[data-rmO]',b=>asmDo('assessment/remediation',{key:b.dataset.rmo,status:'open'}));
}
/* ---------- Zone model (public, reception, operations, security, high security) ----------
   Everything here is read from and written to the server: /sawn-demo/api/assessment (zone-model draft, proposal,
   settings, checks), /sawn-demo/api/zone-access (need-to-access authorizations), /sawn-demo/api/gate/check (training).
   The page shows controls only for the permission; the server enforces every action. */
const ZM='zone-model-1';
const zmOn=()=>{ const A=POL.asm; if(!A) return false; return A.draft?A.draft.scheme===ZM:!!(A.active&&A.active.scheme===ZM); };
const ZT_FALLBACK={public:{ar:'منطقة عامة',en:'Public zone'},reception:{ar:'منطقة استقبال',en:'Reception zone'},operations:{ar:'منطقة عمليات',en:'Operations zone'},security:{ar:'منطقة أمنية',en:'Security zone'},high_security:{ar:'منطقة أمنية عالية',en:'High security zone'}};
const ZT=t=>{ const L=(POL.asm&&POL.asm.zoneModel&&POL.asm.zoneModel.labels||ZT_FALLBACK)[t]||ZT_FALLBACK[t]; return t?(L?TX(L.ar,L.en):t):TX('بلا نوع','No type'); };
const ZT_SHORT=t=>({public:TX('عامة','Public'),reception:TX('استقبال','Reception'),operations:TX('عمليات','Operations'),security:TX('أمنية','Security'),high_security:TX('أمنية عالية','High security')}[t]||TX('بلا نوع','No type'));
/* map and drawer labels: the active zone type under the zone model, the approved level otherwise */
/* with no approved policy the classification is pending: the sample levels are never shown as if decided */
const zTag=id=>{ if(!MAPSRV) return XB('mut',TX('بانتظار الاعتماد','Pending approval')); if(!MAPZM) return lv(levelOf(id)); const z=zones.find(q=>q.id===id); return ztBadge(z&&z.ztype); };
const zShort=id=>{ if(!MAPSRV) return TX('بانتظار الاعتماد','Pending approval'); if(!MAPZM) return `L${levelOf(id)}`; const z=zones.find(q=>q.id===id); return ZT_SHORT(z&&z.ztype); };
const ZT_CLS={public:'mut',reception:'ok',operations:'ref',security:'open',high_security:'no'};
const ztBadge=t=>`<span class="xbdg ${t?ZT_CLS[t]:'no'}">${ZT(t)}</span>`;
/* Access to the zone: the stored value `function` (public / reception / workspace) and its meaning are unchanged;
   rule ZT-FUNCTION reads it. Worded as a question about access, not about use or the security type. */
const FN_T=()=>({public:TX('مفتوحة للجمهور دون فحص (عامة)','Open to the public without screening (public)'),reception:TX('نقطة استقبال: يدخلها الزائر أولاً ويُتحقق منه قبل المناطق المقيدة','Reception point: visitors come here first and are checked before restricted areas'),workspace:TX('مقصورة على من يعملون فيها ومرافقيهم (منطقة عمل للموظفين)','Limited to the people who work there and escorted visitors (staff work area)')});
/* Actual use: documented uses from the server (ZONE_USES); recorded only, no rule reads it */
const USE_T=u=>{ const L=(POL.asm&&POL.asm.zoneModel&&POL.asm.zoneModel.uses)||{}; return u&&L[u]?TX(L[u].ar,L[u].en):''; };
const useCell=f=>f&&f.use?`${esc_(USE_T(f.use))}${f.useDetail?`<div>${esc_(f.useDetail)}</div>`:''}${f.useEvidence?`<div class="muted-s">${TX('المصدر','Source')}: ${esc_(f.useEvidence)}</div>`:''}`:XB('mut',TX('غير محدد','Not specified'));
const INJ_T=()=>({none:TX('لا ضرر','None'),limited:TX('محدود','Limited'),moderate:TX('متوسط','Moderate'),serious:TX('جسيم','Serious'),grave:TX('بالغ الخطورة','Grave')});
const CONS_T=()=>({confidentiality:TX('السرية','Confidentiality'),integrity:TX('تكامل المعلومات','Information integrity'),availability:TX('الإتاحة','Availability'),value:TX('القيمة','Value'),safety:TX('سلامة الأشخاص','People’s safety')});
const ZSTATE=()=>({'baseline-complete':['ok',TX('مقترح مكتمل','Complete proposal')],'lower-bound':['ref',TX('حد أدنى، ليس نهائياً','Lower bound, not final')],undetermined:['no',TX('غير محدد','Undetermined')]});
const ZM_STEPS=()=>[[TX('بيانات المنطقة والأصول','Zone data and assets'),TX('المدخلات والأدلة','Inputs and evidence')],[TX('إعدادات السياسة','Policy settings'),TX('ما يحتاج اعتماداً','What needs approval')],[TX('المقترح','Proposal'),TX('السبب والقاعدة','Reason and rule')],[TX('المراجعة والتعديل','Review and adjust'),TX('بسبب واستثناء','Reason and exception')],[TX('أثر التغيير','Change impact'),TX('قبل الاعتماد','Before approval')],[TX('الاعتماد','Approval'),TX('مراجعة محددة','Exact revision')],[TX('السياسة النشطة','Active policy'),TX('أثرها','Its effect')]];
POL.zstep=POL.zstep||0;
const zSrc=()=>{ const A=POL.asm; return A.draft&&A.draft.scheme===ZM?A.draft:A.active; };
const zCfg=()=>(zSrc()||{}).config||{};

/* Arabic wording for zone-model checks; the server's English text stays the record */
function zoneCheckAr(c){
  const z=c.zoneId?`${c.zoneId}`:'';
  switch(c.rule){
    case 'ZT-SETTING': return `الإعداد المطلوب «${c.setting}» غير محدد، فلا تُعتمد السياسة حتى يُحدَّد.`;
    case 'ZT-UNDETERMINED': return c.category==='invalid'?`${z}: لا نوع للمنطقة. سجّل المعلومات الناقصة أو حدّد النوع بسبب.`:`${z}: لا مقترح؛ حدّده شخص: ${ZT(c.to)}.`;
    case 'ZT-LOWER': return c.category==='exception'?`${z}: ${ZT(c.to)} أقل من المقترح ${ZT(c.from)}، باستثناء تخزين كمية صغيرة وقّعه ${c.authorized}.`:`${z}: ${ZT(c.to)} أقل من المقترح ${ZT(c.from)}. لا يقدّم المرجع مساراً لمنطقة تحوي أصلاً أعلى إلا تخزين كمية صغيرة (§6.2): صحّح الوقائع بدليل، أو سجّل ذلك الاستثناء.`;
    case 'ZT-FUNCTION': return `${z}: حُدّد ${ZT(c.to)}، أعلى من المقترح ${ZT(c.from)}.`;
    case 'ZT-INCOMPLETE': return `${z}: المقترح حد أدنى وليس نهائياً، فقد يرتفع بعد تقييم ما ينقص.`;
    case 'ZT-SAFETY': return `${z}: ضرر على سلامة الأشخاص مسجّل؛ لا قاعدة تحدد النوع منه، فيُراجع.`;
    case 'ZT-SCHEME': return c.key==='scheme'?'السياسة النشطة بالمستويات القديمة. اعتماد هذه المسودة ينقل المنشأة إلى نموذج المناطق، ولا تُقارن القيم بين المخططين، وتبقى السياسات والحوادث السابقة بمعناها القديم.':`${z}: ${ZT(c.from)} في السياسة النشطة ← ${ZT(c.to)}.`;
    case 'ZT-AUTH-NONE': return `${z}: منطقة مقيدة ولا يملك أحد تفويضاً لها؛ بعد الاعتماد لن يدخلها أحد.`;
    case 'ZT-PRIORITY': return `${z}: تعديل أولوية الحوادث الجديدة حسب إعداد السياسة.`;
    case 'ZT-PROTECTION': return c.category==='unassessable'&&c.unknown?`غير متحقق منه، فلا يمكن تقييم الأثر — ${zFindTxt({entrance:c.entrance,type:c.findingType,required:c.required,unassessable:true,unknown:true})}. لا يُحتسب مركّباً.`:c.category==='unassessable'?`لا يمكن تقييم الأثر — ${c.text.replace(/^Impact cannot be assessed — /,'')}`:c.category==='exception'?`نقص حماية مقبول باستثناء وقّعه ${c.authorized}.`:'نقص حماية بعد تحديد النوع: يُعالج أو يُقبل باستثناء، ولا يخفض النوع.';
    default: return null;
  }
}
const zLine=c=>`${esc_(TX(zoneCheckAr(c)||c.text,c.text))}${zoneCheckAr(c)?`<div class="muted-s" dir="ltr">${esc_(c.text)}</div>`:''}`;


/* Arabic sentences built from the structured proposal; the server's English text is the English view */
function zReasonTxt(r){
  if(r.rule==='ZT-FUNCTION'&&r.fn) return TX(`طبيعة الوصول المسجلة «${FN_T()[r.fn]}» ← ${ZT(r.type)}${r.evidence?` (المصدر: ${r.evidence})`:''}`,`Recorded access “${FN_T()[r.fn]}” → ${ZT(r.type)}${r.evidence?` (source: ${r.evidence})`:''}`);
  if(LANG!=='ar') return r.text;
  if(r.rule==='ZT-ASSET'&&r.outranks) return `أصل مقيد أعلى من الوظيفة المسجلة (${ZT(r.outranks)})`;
  if(r.rule==='ZT-ASSET'&&r.asset) return `${r.asset}: تصنيف ${r.classification} وضرر سرية ${INJ_T()[r.injury]||r.injury} ← ${ZT(r.type)} (جدول المقابلة في الإعدادات)`;
  if(r.rule==='ZT-HIGHEST'&&r.types) return `الأعلى بين ${r.types.map(ZT).join('، ')} ← ${ZT(r.type)}`;
  return r.text;
}
function zMissTxt(m){
  if(m.field==='function') return TX('طبيعة الوصول إلى المنطقة غير مسجلة','Access to the zone not recorded');
  if(LANG!=='ar') return m.text;
  const f=m.field||'', p=f.split(':'), CN=CONS_T();
  if(f==='inventory') return /incomplete/i.test(m.text)&&!/not confirmed/i.test(m.text)?'حصر الأصول مسجّل كناقص':'اكتمال حصر الأصول غير مؤكد';
  if(f==='function') return 'وظيفة المنطقة غير مسجلة';
  if(p[0]==='asset'&&p[2]==='classification') return `${p[1]}: التصنيف غير مسجل`;
  if(p[0]==='asset') return `${p[1]}: ضرر ${CN[p[2]]||p[2]} غير مقيَّم`;
  if(p[0]==='mapping') return `لا مقابلة معتمدة لـ ${p[1].replace('.',' + ')}`;
  if(f==='setting:zoneMapping.highestWins') return 'عدة أصول: اختيار «الأعلى يغلب» غير مؤكد في الإعدادات';
  return m.text;
}
function zFindTxt(f){
  if(LANG!=='ar') return f.text;
  if(f.unassessable&&f.unknown) return f.type==='monitoring'?`${f.entrance}: المراقبة عند المدخل غير متحقق منها (مجهولة)، والنوع يتطلب مراقبة ${f.required==='continuous-audited'?'مستمرة مع تدقيق الدخول':'مستمرة'}`:`${f.entrance}: عوامل التحقق المركّبة غير متحقق منها (مجهولة)، والنوع يتطلب ${f.required}`;
  if(f.unassessable) return `${f.entrance}: لا يمكن تقييم عوامل التحقق، لأن إعداد العوامل لهذا النوع غير محدد`;
  if(f.type==='factors') return `${f.entrance}: ${f.current} عامل تحقق، والنوع يتطلب ${f.required}`;
  if(f.type==='monitoring') return `${f.entrance}: النوع يتطلب مراقبة ${f.required==='continuous-audited'?'مستمرة مع تدقيق الدخول':'مستمرة'}، ولا كاميرا أو وسيلة أخرى مسجلة`;
  if(f.type==='visitor') return /prohibited/.test(f.text)?`تصريح زائر يشمل ${f.zoneId}، والزوار ممنوعون فيها`:`تصريح زائر يشمل ${f.zoneId}، ويلزم مرافق${/authorization/.test(f.text)?' وتفويض':''}، ولا يوجد ذلك في التصريح`;
  return f.text;
}
function zFlagTxt(f){
  if(LANG!=='ar') return f.text;
  const CN=CONS_T();
  if(f.rule==='ZT-RAISE') return /not rated/.test(f.text)?`${f.asset}: ضرر ${CN[f.consequence]} غير مقيَّم، وقد يرفع المنطقة`:`${f.asset}: ضرر ${CN[f.consequence]} أعلى من ضرر السرية، وقد يلزم نوع أعلى`;
  if(f.rule==='ZT-SAFETY') return /not rated/.test(f.text)?`${f.asset}: ضرر سلامة الأشخاص غير مقيَّم`:`${f.asset}: ضرر على سلامة الأشخاص؛ لا قاعدة تحدد النوع منه، فيُراجع`;
  return f.text;
}

/* ---------- step views ---------- */
function zFacts(){
  if(PL.open) return planReview();
  return planPanel()+zFactTables();
}
function zFactTables(){
  const A=POL.asm, S=zSrc(), I=S.inputs, ZI=I.zoneModel||{}, ed=coreCan('policy.draft')&&S.status==='draft', F=FN_T(), INJ=INJ_T(), CN=CONS_T();
  const PE=I.planEvidence||{}, pev=(list)=>(list||[]).length?`<div class="muted-s">${TX('في المخطط','In the plan')}: ${list.map(e=>`<bdi dir="auto">${esc_(e.label)}</bdi> <span class="num">${TX(`ص${e.page}`,`p${e.page}`)}</span>`).join('، ')}</div>`:'';
  const prov=a=>a.provenance?`<div>${XB('mut',a.provenance.source==='team'?TX('المصدر: الفريق','Source: team'):TX('المصدر: المخطط','Source: plan'))}${a.provenance.note?` <span class="muted-s">${esc_(a.provenance.note)}</span>`:''}</div>`:'';
  const zr=A.zones.filter(z=>!['airspace','system'].includes(z.kind)).map(z=>{const f=ZI[z.id]||{}; return `<tr><td class="num"><b>${z.id}</b> ${zName(z)}${pev((PE.zones||{})[z.id])}</td><td style="white-space:normal">${useCell(f)}</td><td style="white-space:normal">${f.function?F[f.function]:XB('mut',TX('غير محددة','Not recorded'))}${f.functionEvidence?`<div class="muted-s">${TX('المصدر','Source')}: ${esc_(f.functionEvidence)}</div>`:''}</td><td>${f.inventoryComplete==null?yes(null):f.inventoryComplete?XB('ok',TX('مكتملة','Complete')):XB('ref',TX('ناقصة','Incomplete'))}${f.inventoryEvidence?`<div class="muted-s">${esc_(f.inventoryEvidence)}</div>`:''}</td>${ed?`<td><button class="btn sm" data-zfact="${z.id}">${TX('تعديل','Edit')}</button></td>`:''}</tr>`;}).join('');
  const ar=I.assets.map(a=>`<tr><td class="num"><b>${esc_(a.id)}</b> ${esc_(typeof a.name==='object'?TX(a.name.ar,a.name.en):a.name)}${prov(a)}${pev((PE.assets||{})[a.id])}</td><td class="num">${a.zone}</td><td>${a.classification?esc_(a.classification):yes(null)}</td>${Object.keys(CN).map(k=>`<td>${a.injury&&a.injury[k]?INJ[a.injury[k]]:yes(null)}</td>`).join('')}<td>${a.criticalSystem==null?yes(null):a.criticalSystem?XB('ref',TX('ضمن النطاق','In scope')):TX('لا','No')}</td>${ed?`<td><button class="btn sm" data-zasset="${esc_(a.id)}">${TX('تعديل','Edit')}</button></td>`:''}</tr>`).join('');
  const note=`<div class="muted-s" style="padding:10px 16px 0">${TX('اسم الغرفة واستخدامها لا يحددان النوع الأمني. يقترح المحرك النوع لاحقاً من طبيعة الوصول المسجلة ومن الأصول وتصنيفها وضررها، ثم يُراجَع ويُعتمد. والنقص يبقى ظاهراً ولا يُعامل كنوع أدنى.','A zone’s name and use do not set its security type. The engine later proposes the type from the recorded access and from the assets, their classification and injury; it is then reviewed and approved. Missing information stays visible and is never read as a lower type.')}</div>`;
  return panel(TX('بيانات المناطق','Zone data'),'',note+`<div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('الاستخدام الفعلي للمنطقة','Actual use of the zone')}</th><th>${TX('طبيعة الوصول إلى المنطقة','Access to the zone')}<div class="muted-s" style="font-weight:400">${TX('يستخدمها المحرك','used by the engine')}</div></th><th>${TX('اكتمال حصر الأصول','Asset inventory')}</th>${ed?'<th></th>':''}</tr></thead><tbody>${zr}</tbody></table></div>`)
    +panel(TX('الأصول: التصنيف والضرر','Assets: classification and injury'),'',`<div class="feed"><table><thead><tr><th>${TX('الأصل','Asset')}</th><th>${TX('المنطقة','Zone')}</th><th>${TX('التصنيف','Classification')}</th>${Object.values(CN).map(t=>`<th>${t}</th>`).join('')}<th>${TX('ضمن نطاق نظام حساس (CSCC)','Critical-system scope (CSCC)')}</th>${ed?'<th></th>':''}</tr></thead><tbody>${ar}</tbody></table></div><div class="muted-s" style="padding:8px 16px 12px">${TX('سلامة الأشخاص منفصلة عن تكامل المعلومات، ولا قاعدة تحدد النوع منها.','People’s safety is separate from information integrity; no rule sets a type from it.')}<br>${CSCC_NOTE()}</div>`)
    +zPlanComponents(I);
}
/* components the plan mentions: recorded as mentioned, never as working; no rule reads them */
function zPlanComponents(I){
  const L=I.planComponents||[], ed=coreCan('policy.draft')&&POL.asm.draft; if(!L.length) return zPending(I);
  const rows=L.map(c=>`<tr><td><b class="num">${esc_(c.id)}</b> <bdi dir="auto">${esc_(c.name)}</bdi>${c.model?` <span class="pill" dir="ltr">${esc_(c.model)}</span>`:''}</td><td>${esc_((PL_CAT()[c.category])||c.category)}</td><td class="num">${c.zone||'—'}${c.gate?` · ${esc_(c.gate)}`:''}${c.zoneBasis?`<div class="muted-s">${esc_(AR(c.zoneBasis))}</div>`:''}${c.locationPending?`<div>${XB('ref',TX('الموقع بانتظار المراجعة','Location pending review'))}</div>`:''}</td><td>${zCompState(c)}${ed?` <button class="btn sm" data-zint="${c.id}">${TX('ربط بتكامل','Link integration')}</button>`:''}</td><td style="white-space:normal;max-width:320px">${c.provenance?`${XB('mut',c.provenance.source==='team'?TX('الفريق','Team'):TX('المخطط','Plan'))} ${plSrc(c.provenance.sources)}`:'—'}</td></tr>`).join('');
  return panel(TX('مكوّنات مذكورة في المخطط','Components mentioned in the plan'),`<span class="cnt">${L.length}</span>`,`<div class="muted-s" style="padding:10px 16px 0">${TX('ما يُظهره المخطط فقط. تُؤكَّد الحالة التشغيلية من التكامل الفعلي، ولا تؤثر هذه القائمة في نوع المنطقة.','Only what the plan shows. The operational state is confirmed by the live integration; this list does not affect the zone type.')}</div><div class="feed"><table><thead><tr><th>${TX('المكوّن','Component')}</th><th>${TX('الفئة','Category')}</th><th>${TX('المنطقة','Zone')}</th><th>${TX('الحالة','Status')}</th><th>${TX('المصدر','Source')}</th></tr></thead><tbody>${rows}</tbody></table></div>`)+zPending(I);
}
/* the state a component shows: only a linked live integration's report; otherwise mentioned and unconfirmed */
function zCompState(c){ const h=c.integration&&(coreHealth()||[]).find(x=>x.id===c.integration&&x.real); if(c.integration) return h?`${XB(h.status==='ok'?'ok':'no',`${TX('التكامل','Integration')} ${esc_(h.id)}: ${HST()[h.status]||h.status}`)}`:XB('ref',TX(`مربوط بـ ${c.integration} · لا تقرير منه الآن`,`Linked to ${c.integration} · no report from it now`)); return `${XB('mut',TX('مذكور في المخطط','Mentioned in the plan'))} ${XB('ref',TX('الحالة التشغيلية غير مؤكدة','Operational state unconfirmed'))}`; }
/* plan items kept out of the records until a person decides */
function zPending(I){ const P=((I.planEvidence||{}).pending)||[]; if(!P.length) return '';
  return panel(TX('بانتظار المراجعة من المخطط','Pending review from the plan'),`<span class="cnt warn">${P.length}</span>`,`<div class="muted-s" style="padding:10px 16px 0">${TX('لم تُسجَّل ولم تُدمج مع أي سجل: تشابه الاسم لا يعني أنها الكيان نفسه. تُحسم من «مراجعة» المخطط.','Not recorded and not merged with any record: an overlapping name does not make it the same entity. Decided from the plan “Review”.')}</div><div class="feed"><table><thead><tr><th>${TX('في المخطط','In the plan')}</th><th>${TX('المصدر','Source')}</th><th>${TX('قد يتعلق بـ','May relate to')}</th><th>${TX('السبب','Why')}</th></tr></thead><tbody>${P.map(e=>`<tr><td><b><bdi dir="auto">${esc_(e.label||e.key)}</bdi></b></td><td class="muted-s"><span class="num">${esc_(e.plan||'')} · ${TX(`ص${e.page}`,`p${e.page}`)}</span> <bdi dir="auto">“${esc_(e.snippet||'')}”</bdi></td><td class="num">${(e.candidates||[]).join('، ')||'—'}</td><td class="muted-s" style="white-space:normal">${esc_(e.reason||'')}</td></tr>`).join('')}</tbody></table></div>`); }
function zSettings(){
  const A=POL.asm, ZMd=A.zoneModel, S=zSrc(), cfg=S.config||{}, ed=coreCan('policy.draft')&&S.status==='draft';
  const miss=new Set(((A.draft&&A.draft.missingSettings)||[]).map(m=>m.id));
  const rows=ZMd.settings.map(s=>{const v=cfg[s.id]&&cfg[s.id].value, st=v&&!miss.has(s.id)?XB('ok',TX('محدد','Set')):XB('no',TX('مطلوب','Required'));
    const shown=v?Object.entries(v).filter(([,x])=>x!==''&&x!=null).map(([k,x])=>`<span class="pill"><span class="num" dir="ltr">${esc_(k)}</span>: ${esc_(String(x))}</span>`).join(' '):'—';
    return `<tr><td><b>${esc_(TX(s.title.ar,s.title.en))}</b><div class="muted-s">${esc_(TX(s.why.ar,s.why.en))}</div>${cfg[s.id]&&cfg[s.id].reason?`<div class="muted-s">${TX('السبب','Reason')}: ${esc_(cfg[s.id].reason)} · ${esc_(cfg[s.id].by||'')}</div>`:''}</td><td>${st}</td><td style="white-space:normal">${shown}</td>${ed?`<td><button class="btn sm" data-zset="${s.id}">${TX('تعديل','Edit')}</button></td>`:''}</tr>`;}).join('');
  return panel(TX('إعدادات السياسة','Policy settings'),`<span class="muted-s">${TX('لا يملأ صون أي قيمة بنفسه. والإعداد المطلوب الفارغ يمنع الاعتماد، وتبقى السياسة النشطة تعمل.','SAWN fills in no value itself. An empty required setting blocks approval; the active policy keeps working.')}</span>`,`<div class="feed"><table><thead><tr><th>${TX('الإعداد','Setting')}</th><th>${TX('الحالة','State')}</th><th>${TX('القيمة','Value')}</th>${ed?'<th></th>':''}</tr></thead><tbody>${rows}</tbody></table></div>`);
}
function zProposal(){
  const A=POL.asm, S=zSrc(), P=S.proposal||{}, ST=ZSTATE();
  const rows=A.zones.filter(z=>P[z.id]&&!P[z.id].outOfScheme).map(z=>{const p=P[z.id], s=ST[p.state];
    return `<tr><td class="num"><b>${z.id}</b> ${zName(z)}</td><td>${ztBadge(p.type)} ${XB(s[0],s[1])}</td><td style="white-space:normal">${p.reasons.map(r=>`<div>${ruleChip(r.rule,r.ruleVersion)} <span class="muted-s">${esc_(zReasonTxt(r))}</span></div>`).join('')||'—'}${(()=>{ const f=(S.inputs.zoneModel||{})[z.id]||{}; return f.use?`<div class="muted-s">${TX('الاستخدام الفعلي','Actual use')}: ${esc_(USE_T(f.use))}${f.useDetail?` — ${esc_(f.useDetail)}`:''} · ${TX('لا يدخل في اقتراح النوع','not an input to the type')}</div>`:''; })()}</td><td style="white-space:normal">${[...p.missing.map(m=>`<div class="muted-s">⚠ ${esc_(zMissTxt(m))}</div>`),...p.flags.map(f=>`<div class="muted-s">↑ ${ruleChip(f.rule)} ${esc_(zFlagTxt(f))}</div>`)].join('')||XB('ok',TX('لا شيء','Nothing'))}</td></tr>`;}).join('');
  const F=S.findings||[];
  const fr=F.map(f=>`<tr><td class="num">${esc_(f.zoneId)}</td><td>${esc_(zFindTxt(f))}</td><td>${f.unassessable&&f.unknown?XB('ref',TX('غير متحقق منه · مجهول','Not verified · unknown')):f.unassessable?XB('mut',TX('لا يمكن تقييمه','Cannot be assessed')):XB('ref',TX('نقص','Gap'))}</td></tr>`).join('');
  return panel(TX('المقترح لكل منطقة','Proposal per zone'),`<span class="muted-s">${TX('إصدار القواعد','Rules')} <span class="num">${esc_(A.zoneModel.rulesVersion)}</span></span>`,`<div class="muted-s" style="padding:10px 16px 0">${TX('«حد أدنى» يعني أن عوامل لم تُقيَّم قد ترفع النوع. لا يُسمى المقترح نهائياً إلا إذا قُيّمت كل العوامل المؤثرة.','“Lower bound” means unassessed factors could raise the type. A proposal is complete only when every relevant factor is rated.')}</div><div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('النوع المقترح','Proposed type')}</th><th>${TX('السبب والقاعدة','Reason and rule')}</th><th>${TX('الناقص وما قد يرفعه','Missing / may raise')}</th></tr></thead><tbody>${rows}</tbody></table></div>`)
    +panel(TX('الحماية بعد النوع','Protection after the type'),`<span class="cnt">${F.length}</span>`,`<div class="muted-s" style="padding:10px 16px 0">${TX('تُفحص الحماية الموجودة بعد اقتراح النوع، ولا تخفض أهمية المنطقة.','Existing protection is checked after the type is proposed and never lowers it.')}</div><div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('النقص','Gap')}</th><th></th></tr></thead><tbody>${fr||`<tr><td colspan="3">${TX('لا يوجد','None')}</td></tr>`}</tbody></table></div>`);
}
function zReview(){
  const A=POL.asm, D=A.draft&&A.draft.scheme===ZM?A.draft:null, act=A.active&&A.active.scheme===ZM?A.active:null, S=D||act, P=S.proposal||{}, ed=coreCan('policy.draft');
  const role=(zCfg().riskAcceptance&&zCfg().riskAcceptance.value||{}).role, signer=!!role&&CORE.user&&CORE.user.role===role&&!!D;
  const rows=A.zones.filter(z=>P[z.id]&&!P[z.id].outOfScheme).map(z=>{const p=P[z.id], adj=S.adjustments&&S.adjustments[z.id], t=(D?D.types:act.zoneTypes)[z.id];
    const lower=p.type&&t&&A.zoneModel&&['public','reception','operations','security','high_security'].indexOf(t)<['public','reception','operations','security','high_security'].indexOf(p.type);
    const sq=S.exceptions&&S.exceptions['sq:'+z.id];
    return `<tr${adj?' class="ovr"':''}><td class="num"><b>${z.id}</b> ${zName(z)}</td><td>${ztBadge(p.type)}</td><td>${ztBadge(t)}${adj?`<div class="muted-s">${esc_(adj.by)}: ${esc_(adj.reason)}</div>`:''}${sq?`<div class="muted-s">${TX('استثناء كمية صغيرة','Small-quantity exception')}: ${esc_(sq.by)} · TRA ${esc_(sq.traRef)}</div>`:''}</td><td><div class="row-c" style="gap:4px;flex-wrap:wrap">${ed?`<button class="btn sm" data-ztype="${z.id}">${TX('تحديد النوع','Set type')}</button>${adj?`<button class="btn sm" data-ztclr="${z.id}">${TX('العودة للمقترح','Back to proposal')}</button>`:''}`:''}${signer&&lower&&!sq?`<button class="btn sm warn" data-zsq="${z.id}">${TX('استثناء تخزين كمية صغيرة','Small-quantity exception')}</button>`:''}</div></td></tr>`;}).join('');
  const F=(S.findings||[]).filter(f=>!f.unassessable);
  const fr=F.map(f=>{const ex=S.exceptions&&S.exceptions[f.key]; return `<tr><td>${esc_(zFindTxt(f))}</td><td>${ex?XB('open',TX(`مقبول ${ex.days} يوماً`,`Accepted ${ex.days} days`))+`<div class="muted-s">${esc_(ex.by)} · TRA ${esc_(ex.traRef)}</div>`:XB('mut',TX('مفتوح','Open'))}</td><td>${signer&&!ex?`<button class="btn sm" data-zps="${esc_(f.key)}">${TX('قبول باستثناء','Accept by exception')}</button>`:''}</td></tr>`;}).join('');
  const who=`<div class="muted-s" style="padding:10px 16px 0">${role?TX(`يوقّع الاستثناءات دور ${role.toUpperCase()} (إعداد في السياسة)، ويصبح من محرري المسودة فلا يعتمدها.`,`Exceptions are signed by the ${role.toUpperCase()} role (policy setting); the signer becomes an editor and cannot approve.`):TX('من يوقّع الاستثناءات إعداد مطلوب لم يُحدَّد بعد.','Who signs exceptions is a required setting not yet set.')}</div>`;
  return panel(TX('المقترح والمحدَّد','Proposed and set'),D?`<span class="st draft">${D.ref} · r<span class="num">${D.revision}</span></span>`:'',`<div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('المقترح (يبقى ظاهراً)','Proposed (stays visible)')}</th><th>${TX('المحدَّد','Set')}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`)
    +panel(TX('نقص الحماية والاستثناءات','Protection gaps and exceptions'),'',who+`<div class="feed"><table><thead><tr><th>${TX('النقص','Gap')}</th><th>${TX('الحالة','State')}</th><th></th></tr></thead><tbody>${fr||`<tr><td colspan="3">${TX('لا يوجد','None')}</td></tr>`}</tbody></table></div>`);
}
function zImpact(){
  const D=POL.asm.draft;
  if(!D||D.scheme!==ZM) return panel(TX('أثر التغيير','Change impact'),'',`<div class="empty"><span>${TX('لا توجد مسودة.','No draft.')}</span></div>`);
  const C=CAT(), by=k=>D.checks.filter(c=>c.category===k);
  const counts=Object.entries(C).map(([k,[cls,t]])=>`<span class="xbdg ${cls}">${t} <span class="num">${by(k).length}</span></span>`).join(' ');
  return panel(TX('أثر التغيير قبل الاعتماد','Change impact before approval'),`<span class="row-c" style="gap:4px;flex-wrap:wrap">${counts}</span>`,`<div class="feed"><table><thead><tr><th>${TX('الفئة','Category')}</th><th>${TX('المنطقة','Zone')}</th><th>${TX('الأثر','Effect')}</th><th>${TX('القاعدة','Rule')}</th></tr></thead><tbody>${D.checks.map(c=>`<tr><td>${XB(C[c.category][0],C[c.category][1])}</td><td class="num">${esc_(c.zoneId||'—')}</td><td style="white-space:normal">${zLine(c)}</td><td>${ruleChip(c.rule,c.ruleVersion)}</td></tr>`).join('')}</tbody></table></div>`);
}
function zActive(){
  const A=POL.asm, act=A.active;
  if(!act||act.scheme!==ZM) return panel(TX('السياسة النشطة','Active policy'),'',`<div class="ed-warn" role="note" style="margin:12px 16px"><b>${act?TX(`النشطة ${act.ref} بالمستويات القديمة`,`Active ${act.ref} uses the legacy levels`):NO_POLICY()}</b><span>${TX('نموذج المناطق يُفعَّل عند اعتماد مسودته. وحتى ذلك تعمل السياسة النشطة كما هي، وتبقى الحوادث السابقة بنسختها ومعناها.','The zone model takes effect when its draft is approved. Until then the active policy works as it is, and earlier incidents keep their version and meaning.')}</span></div>`);
  const SV=ASM_SEV();
  const ap=act.approval||{}, PR=act.proposal||{}, PV=Object.fromEntries((ap.provisional||[]).map(x=>[x.zoneId,x]));
  /* assessment status of each ACTIVE type: final only when the proposal is complete with no raise flag; a lower bound
     stays a lower bound after approval (provisionally active by the recorded decision), never shown as final */
  const stat=id=>{ const p=PR[id]; if(!p||p.outOfScheme) return '—'; const pv=PV[id];
    if(p.state==='lower-bound') return `${XB('ref',TX('حد أدنى · مفعّل مؤقتاً','Lower bound · provisionally active'))}${pv?`<div class="muted-s">${TX('بقرار','by')} ${esc_(pv.decidedBy)}</div>`:`<div class="muted-s">${TX('لا يوجد قرار مسجّل','no recorded decision')}</div>`}`;
    if(p.state==='undetermined') return XB('no',TX('بلا مقترح · حدده شخص','No proposal · set by a person'));
    const at=(act.zoneTypes||{})[id], diff=p.type&&at&&at!==p.type?`<div class="muted-s">${TX('المقترح','Proposed')}: ${ZT(p.type)} · ${ZT_RANK[at]<ZT_RANK[p.type]?TX('النشط أقل منه باستثناء معتمد','active is lower, by an approved exception'):TX('النشط أعلى منه','active is higher')}</div>`:'';
    return ((p.flags||[]).some(f=>f.rule==='ZT-RAISE')?XB('ref',TX('حد أدنى','Lower bound')):XB('ok',TX('مقترح مكتمل','Complete proposal')))+diff; };
  const mx=(A.priorityMatrix||[]).filter(r=>r.type!==undefined).map(r=>`<tr><td class="num"><b>${r.zoneId}</b></td><td>${ztBadge(r.type)}</td><td>${stat(r.zoneId)}</td>${['low','mid','high','crit'].map(s=>`<td class="num">${r.bySeverity[s]}</td>`).join('')}</tr>`).join('');
  const open=Object.entries(PR).filter(([,p])=>p&&!p.outOfScheme&&p.state==='lower-bound');
  const prov=open.length?panel(TX('مناطق مفعّلة مؤقتاً وهي «حد أدنى»','Zones active provisionally as a lower bound'),XB('ref',String(open.length)),`<p class="muted-s" style="padding:8px 16px 0">${TX('النوع النشط يطبَّق على الدخول والحوادث، لكنه ليس تقييماً نهائياً: النواقص أدناه قد ترفعه. يزول التنبيه فقط عند إكمالها في مسودة جديدة واعتمادها.','The active type applies to entry and incidents, but it is not a final assessment: the gaps below could raise it. The notice clears only when they are completed in a new draft and approved.')}</p><div class="sform">${open.map(([id,p])=>{ const pv=PV[id]; return `<div class="srow"><div><b><span class="num">${id}</span> ${ztBadge((act.zoneTypes||{})[id])}</b><span>${pv?`${TX('قرار التفعيل المؤقت','Provisional activation decision')}: ${esc_(pv.decidedBy)} — ${esc_(pv.reason||'')}`:TX('لا يوجد قرار تفعيل مؤقت مسجّل لهذه المنطقة في سجل الاعتماد.','No provisional activation decision is recorded for this zone in the approval record.')}</span>${[...(p.missing||[]).map(zMissTxt),...(p.flags||[]).filter(f=>f.rule==='ZT-RAISE').map(zFlagTxt)].map(t=>`<span class="muted-s">• ${esc_(t)}</span>`).join('')}</div></div>`; }).join('')}</div>`):'';
  return notHumanBanner(act)+prov+panel(TX('أنواع المناطق النشطة وأثرها على الحوادث الجديدة','Active zone types and their effect on new incidents'),`<span class="num">${act.ref}</span>`,`<div class="feed"><table><thead><tr><th>${TX('المنطقة','Zone')}</th><th>${TX('النوع','Type')}</th><th>${TX('حالة التقييم','Assessment status')}</th><th>${SV.low}</th><th>${SV.mid}</th><th>${SV.high}</th><th>${SV.crit}</th></tr></thead><tbody>${mx}</tbody></table></div>`)
    +(ap.approvedBy?panel(TX('سجل الاعتماد','Approval record'),'',`<div class="sform"><div class="srow"><div><b>${act.ref} · ${TX('المراجعة','revision')} <span class="num">${ap.revision}</span></b><span>${TX('اعتمدها','Approved by')} ${esc_(ap.approvedBy)} · <span class="num">${dShort(ap.approvedAt)}</span> · ${TX('عدّلها','edited by')} ${esc_((ap.editors||[]).join(', '))} · ${esc_(ap.scheme||'')}</span></div></div>${(ap.acknowledged||[]).map(w=>`<div class="srow"><div><b>${ruleChip(w.rule)}</b><span dir="ltr">${esc_(w.text)} — ${esc_(w.reason)}</span></div></div>`).join('')}${(ap.exceptions||[]).map(w=>`<div class="srow"><div><b>${ruleChip(w.rule)} ${XB('open',TX('استثناء','Exception'))}</b><span>${esc_(w.authorizedBy||'')} · ${esc_(w.reason||'')}</span></div></div>`).join('')}</div>`):'');
}
function vZoneModel(){
  const A=POL.asm, D=A.draft&&A.draft.scheme===ZM?A.draft:null, s=POL.zstep, st=ZM_STEPS();
  const nav=`<section class="panel"><div class="vsteps">${st.map((x,i)=>`<button class="vs ${i===s?'cur':''}" data-zstep="${i}" ${i===s?'aria-current="step"':''}><span class="b">${i+1}</span><span class="l">${x[0]}<span class="r">${x[1]}</span></span></button>`).join('')}</div>
    <dl class="as-m" style="padding:10px 16px">${[[TX('المخطط','Scheme'),TX('نموذج المناطق','Zone model')],[TX('السياسة النشطة','Active policy'),A.active?`<span class="num">${A.active.ref}</span> · ${A.active.scheme===ZM?TX('نموذج المناطق','zone model'):TX('مستويات قديمة','legacy levels')}`:NO_POLICY()],[TX('المسودة','Draft'),D?`<span class="num">${D.ref} · r${D.revision}</span>`:'—'],[TX('إعدادات ناقصة','Missing settings'),D?`<span class="num">${(D.missingSettings||[]).length}</span>`:'—'],[TX('ما يمنع الاعتماد','Blocking'),D?`<span class="num">${(D.blockers||[]).length}</span>`:'—']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section>`;
  const view=[zFacts,zSettings,zProposal,zReview,zImpact,()=>D?asmApprove():panel(TX('الاعتماد','Approval'),'',`<div class="empty"><span>${TX('لا توجد مسودة.','No draft.')}</span></div>`),zActive][s]();
  const stt=D?`<span class="st draft">${TX('مسودة','Draft')} ${D.ref}</span>`:`<span class="st ok">${TX('نشطة','Active')} ${A.active.ref}</span>`;
  return ph(TX('المنشأة والسياسة','Facility & policy'),TX('تقييم المنشأة · نموذج المناطق','Facility assessment · zone model'),' '+stt)
    +`<div class="asx">${nav}<div style="display:grid;gap:12px;min-width:0">${view}<div style="display:flex;justify-content:space-between;gap:8px"><button class="btn" data-zstep="${Math.max(0,s-1)}" ${s===0?'disabled':''}>${TX('السابق','Previous')}</button>${s<6?`<button class="btn pri" data-zstep="${s+1}">${TX('التالي','Next')}</button>`:''}</div></div></div>`;
}
/* legacy page: offer to start a zone-model draft */
