const DG = { G1:{v:0,w:58,s:-1}, G2:{v:1,w:58,s:-1}, G3:{v:0,w:58,s:-1}, G4:{v:1,w:58,s:1}, G5:{v:1,w:43.5,s:1} };
const GATES = [
  {id:'G-A', name:'البوابة A', role:'نقطة التفتيش · الدخول من الشارع', how:'بطاقة + وجه + معادن + متفجرات', dev:'ESP32', zone:'Z1', pos:[688.25,514.25], today:142, blk:3, div:2, st:'on', hist:[4,9,22,31,18,12,20,26]},
];
const ALERT_AT = {'A-1041':'G3','A-1040':'Z4C','A-1039':'Z5C','A-1038':'G-A','A-1037':'G4','A-1036':'G1','A-1035':'G2'};
let feed = [];
const PEOPLE={'E-01':['خالد العمري','موظف'],'E-02':['نورة السبيعي','موظفة'],'E-03':['فهد الشمري','موظف'],'E-04':['سلمان القحطاني','موظف'],'C-01':['ماجد الزهراني','متعاقد'],'V-01':['عبدالله الغامدي','زائر'],'V-02':['هند العنزي','زائرة']};
