/* side rail: drag its edge to widen it (page names appear) or narrow it back to icons.
   Double-click the edge or press Enter on it to toggle; arrow keys resize; Ctrl+[ toggles. Width kept in this browser. */
(function railInit(){
  const app=document.querySelector('.app'), rail=document.querySelector('.rail'), g=$('railGrip'); if(!app||!rail||!g) return;
  const MIN=72, MAX=260, OPEN=232, SNAP=140;
  let w=MIN; try{ const v=+localStorage.getItem('sawn.railW'); if(v>=MIN&&v<=MAX) w=v; }catch(e){}
  const apply=(v,live)=>{ w=Math.round(Math.min(MAX,Math.max(MIN,v))); app.style.setProperty('--rail-w',w+'px'); app.classList.toggle('rail-open',w>=SNAP); g.setAttribute('aria-valuenow',String(w)); if(!live){ try{ localStorage.setItem('sawn.railW',String(w)); }catch(e){} } };
  const settle=()=>apply(w<SNAP?MIN:w,false);
  const toggle=()=>apply(w>=SNAP?MIN:OPEN,false);
  apply(w,true);
  g.addEventListener('pointerdown',e=>{
    if(e.button!==0) return; e.preventDefault(); g.setPointerCapture(e.pointerId); app.classList.add('rail-drag');
    const r=rail.getBoundingClientRect(), rtl=getComputedStyle(app).direction==='rtl';
    const move=ev=>apply(rtl?r.right-ev.clientX:ev.clientX-r.left,true);
    const up=()=>{ g.removeEventListener('pointermove',move); app.classList.remove('rail-drag'); settle(); };
    g.addEventListener('pointermove',move); g.addEventListener('pointerup',up,{once:true}); g.addEventListener('pointercancel',up,{once:true});
  });
  g.addEventListener('dblclick',toggle);
  g.addEventListener('keydown',e=>{
    const rtl=getComputedStyle(app).direction==='rtl', grow=rtl?'ArrowLeft':'ArrowRight', shrink=rtl?'ArrowRight':'ArrowLeft';
    if(e.key===grow){ e.preventDefault(); apply(w+16,false); } else if(e.key===shrink){ e.preventDefault(); apply(w-16,true); settle(); } else if(e.key==='Enter'||e.key===' '){ e.preventDefault(); toggle(); }
  });
  document.addEventListener('keydown',e=>{ if(e.key==='['&&(e.ctrlKey||e.metaKey)){ e.preventDefault(); toggle(); } });
})();
