    for(let lv=0;lv<4;lv++){ const y0=lv*HT/4, y1=(lv+1)*HT/4, len=Math.hypot(2*S,y1-y0), ang=Math.atan2(y1-y0,2*S), mid=(y0+y1)/2;
      [-S,S].forEach(face=>[1,-1].forEach(sg=>{ const bx=new T.Mesh(new T.BoxGeometry(len,1,1),steel); bx.rotation.z=sg*ang; bx.position.set(0,mid,face); tw.add(bx);
        const bz=new T.Mesh(new T.BoxGeometry(1,1,len),steel); bz.rotation.x=sg*ang; bz.position.set(face,mid,0); tw.add(bz); }));
      [-S,S].forEach(face=>{ const hx=new T.Mesh(new T.BoxGeometry(2*S,1.2,1.2),steel); hx.position.set(0,y1,face); tw.add(hx); const hz=new T.Mesh(new T.BoxGeometry(1.2,1.2,2*S),steel); hz.position.set(face,y1,0); tw.add(hz); }); }
