    const housing=new T.Mesh(new T.CylinderGeometry(5,5,4,24),M('#e9e6e0',{roughness:0.35})); head.add(housing);
    const dome=new T.Mesh(new T.SphereGeometry(4.6,24,12,0,Math.PI*2,Math.PI/2,Math.PI/2),M('#1c2026',{roughness:0.05,metalness:0.4,transparent:true,opacity:0.85})); dome.position.y=-2; head.add(dome);
    const lensT=new T.Mesh(new T.CylinderGeometry(1.4,1.4,3,12),M('#111',{metalness:0.6,roughness:0.1})); lensT.rotation.z=Math.PI/2; lensT.position.set(4,-3,0); head.add(lensT);
    const stat=new T.Mesh(new T.SphereGeometry(0.8,8,6),new T.MeshBasicMaterial({color:lin('#ff3b30')})); stat.position.set(0,2.6,0); head.add(stat);
    tw.add(head);
    const vg=new T.Group(); const view=new T.Mesh(sector(TWR.len,TWR.half*Math.PI/180),new T.MeshBasicMaterial({color:lin('#c8242b'),transparent:true,opacity:0.11,depthWrite:false})); view.rotation.x=-Math.PI/2; view.position.y=0.7; vg.add(view);
    const edgeM=new T.LineBasicMaterial({color:lin('#c8242b'),transparent:true,opacity:0.45}); [-1,1].forEach(sg=>{ const a=sg*TWR.half*Math.PI/180; const geo=new T.BufferGeometry().setFromPoints([new T.Vector3(0,0.9,0),new T.Vector3(TWR.len*Math.cos(a),0.9,-TWR.len*Math.sin(a))]); vg.add(new T.Line(geo,edgeM)); });
    tw.add(vg);
