/* 3D: driveway, kerbs, barrier with a pivoting arm, ANPR pole, and a car that comes in now and then (arm lifts for it) */
function fp3Vgate(ctx){
  const {T,root,M,box,lin,tag,TM,TX0,yy,sy,glass}=ctx, x0=VG.x0, x1=VG.x1, cx=VG.cx, w=x1-x0, top=yy+62;
  const drive=new T.Mesh(new T.PlaneGeometry(w,sy-top),TM(TX0.asphalt,[1,2],'#ffffff',{roughness:0.95})); drive.rotation.x=-Math.PI/2; drive.position.set(cx,0.08,(sy+top)/2); drive.receiveShadow=true; root.add(drive);
  for(let z=top+10;z<sy-8;z+=22) box(1.2,0.2,10,M('#efe9d8',{roughness:0.6}),cx,0.2,z,false);
  [x0-1.5,x1+1.5].forEach(x=>box(3,2.4,sy-top,M('#bdb7ad'),x,1.2,(sy+top)/2,false));
  const g=new T.Group(); g.position.set(x0+3,0,sy+4);
  const post=new T.Mesh(new T.BoxGeometry(6,14,6),M('#e9e6e0',{roughness:0.5})); post.position.y=7; post.castShadow=true; g.add(post);
  const stripe=new T.Mesh(new T.BoxGeometry(6.2,2,6.2),M('#c8242b')); stripe.position.y=12; g.add(stripe);
  const pivot=new T.Group(); pivot.position.y=12.5; g.add(pivot);
  const armLen=w-4, arm=new T.Group(); pivot.add(arm);
  for(let i=0;i<6;i++){ const seg=new T.Mesh(new T.BoxGeometry(armLen/6,1.6,1.6),M(i%2?'#c8242b':'#f3f1ee',{roughness:0.5})); seg.position.x=armLen/12+i*armLen/6; seg.castShadow=true; arm.add(seg); }
  const rest=new T.Mesh(new T.BoxGeometry(2,11,2),M('#7b828c',{metalness:0.5})); rest.position.set(armLen+1,5.5,0); g.add(rest);
  const pole=new T.Mesh(new T.CylinderGeometry(0.8,0.8,26,10),M('#4d545e',{metalness:0.6})); pole.position.set(w-2,13,-6); g.add(pole);
  const anpr=new T.Mesh(new T.BoxGeometry(5,3,7),M('#e9e6e0',{roughness:0.4})); anpr.position.set(w-2,26,-3); g.add(anpr);
  const ir=new T.Mesh(new T.CircleGeometry(1.2,12),new T.MeshBasicMaterial({color:lin('#ff3b30')})); ir.position.set(w-2,26,0.6); g.add(ir);
  root.add(g); tag(g,`vgate:${VG.id}`,`${VG.id} · ${VG.name} · ${VG.st==='open'?'الحاجز مفتوح':'يفتح تلقائياً للوحات المصرّحة'}`);
  /* the visiting car: comes along the street, waits at the barrier, drives in to the parking, then fades */
  const car=new T.Group(); const col=M('#3c4a5c',{metalness:0.6,roughness:0.35,transparent:true});
  const body=new T.Mesh(new T.BoxGeometry(12,5,25),col); body.position.y=4.5; body.castShadow=true; car.add(body);
  const cab=new T.Mesh(new T.BoxGeometry(10.5,4,12),M('#1c2026',{metalness:0.5,roughness:0.2,transparent:true})); cab.position.set(0,8.5,1); car.add(cab);
  [[-6,-8],[6,-8],[-6,8],[6,8]].forEach(([wx,wz])=>{ const wh=new T.Mesh(new T.CylinderGeometry(2.4,2.4,1.6,16),M('#111',{transparent:true})); wh.rotation.z=Math.PI/2; wh.position.set(wx,2.4,wz); car.add(wh); });
  [-4,4].forEach(dx=>{ const hl=new T.Mesh(new T.BoxGeometry(2.6,1.2,0.4),new T.MeshBasicMaterial({color:lin('#fff6d8')})); hl.position.set(dx,5,-12.6); car.add(hl); });
  car.visible=false; root.add(car);
  const lane=cx+(w>30?7:0), stopZ=sy+22, startX=x1+380, parkZ=top+8;
  const ease=q=>q<0.5?2*q*q:1-Math.pow(-2*q+2,2)/2, lerp=(a,b,q)=>a+(b-a)*q;
  const setOp=o=>car.traverse(n=>{ if(n.material&&n.material.transparent) n.material.opacity=o; });
  ctx.anim.push(t=>{
    let up=VG.st==='open'?1:0;
    if(noMotion()){ car.visible=false; }
    else { const c=t%26; car.visible=c<17;
      if(c<5){ const q=ease(c/5); car.position.set(lerp(startX,lane+20,q),0,stopZ+14); car.rotation.y=Math.PI/2; setOp(1); }
      else if(c<6.5){ const q=ease((c-5)/1.5); car.position.set(lerp(lane+20,lane,q),0,lerp(stopZ+14,stopZ,q)); car.rotation.y=lerp(Math.PI/2,0,q); }
      else if(c<8.5){ car.position.set(lane,0,stopZ); car.rotation.y=0; up=Math.max(up,Math.min(1,(c-7)/1)); }
      else if(c<14){ const q=ease((c-8.5)/5.5); car.position.set(lane,0,lerp(stopZ,parkZ,q)); up=Math.max(up,c<11?1:Math.max(0,1-(c-11)/1)); }
      else if(c<17){ car.position.set(lane,0,parkZ); setOp(1-(c-14)/3); }
    }
    pivot.rotation.z=up*Math.PI*0.46;
  });
}
