const ssel=(k,lab,opts,sub)=>`<div class="srow"><div><b>${lab}</b>${sub?`<span>${sub}</span>`:''}</div><select data-ss="${k}">${opts.map(o=>`<option value="${o[0]}" ${ST[k]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div>`;
