function renderUser(){
  const cu=MODE==='core'&&CORE.user; const job=ACCTS[acct];
  const nm=cu?(CORE.preview&&/^preview-/.test(cu.username)?(CORE.training?TX('حساب معاينة','Preview account'):TX('حساب الدور','Role account')):(cu.displayName||cu.username)):'';
  const ini=(nm||'?').trim().split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase();
  const rl=cu?(job?TX(job.n,cu.roleLabel):AR(cu.roleLabel)):'';  /* the role is the position */
  $('whoBtn').innerHTML=cu?`<span class="av">${esc_(ini)}</span><div><b>${esc_(nm)}</b><small>${esc_(rl)}</small></div><span class="wch">${ico('chev',12)}</span>`:'';
  $('umenu').innerHTML=`<div class="um-h"><b>${esc_(nm)}</b><small>${cu?`${esc_(rl)} · <span class="num">${esc_(job?job.id.split('-')[0]:cu.role)}</span>`:''}</small></div>
   <div class="um-r"><span>${TX('المظهر','Theme')}</span><div class="seg"><button data-th="light" aria-pressed="${theme==='light'}">${TX('فاتح','Light')}</button><button data-th="dark" aria-pressed="${theme==='dark'}">${TX('داكن','Dark')}</button></div></div>
   <div class="um-r"><span>${TX('اللغة','Language')}</span><div class="seg"><button data-lg="ar" aria-pressed="${lang==='ar'}">العربية</button><button data-lg="en" aria-pressed="${lang==='en'}">EN</button></div></div>
   ${cu&&!CORE.preview?`<button class="um-a" id="mypw">${TX('تغيير كلمة المرور','Change password')}</button><button class="um-a out" id="logout">${TX('تسجيل الخروج','Sign out')}</button>`:''}`;
  const sb=document.querySelector('.rail .bottom'); if(sb) sb.hidden=!canSee('settings');
  const M=$('umenu');
  M.querySelectorAll('[data-th]').forEach(b=>b.onclick=()=>{theme=b.dataset.th; document.documentElement.setAttribute('data-theme',theme); try{ localStorage.setItem('sawn.theme',theme); }catch(e){} renderUser();});
  M.querySelectorAll('[data-lg]').forEach(b=>b.onclick=()=>{ if(b.dataset.lg!==LANG) setLang(b.dataset.lg); });
  const lo=$('logout'); if(lo) lo.onclick=()=>{closeUM(); signOut();};
  const pw=$('mypw'); if(pw) pw.onclick=()=>{closeUM(); changeOwnPassword();};
}
/* signing out ends the session on the server and returns to the sign-in screen */
async function signOut(){
  if(MODE==='core'){ clearInterval(CORE.timer); try{ CORE.ws&&CORE.ws.close(); }catch(e){} try{ await api('logout',{method:'POST',body:'{}'}); }catch(e){} CORE.user=null; }
  location.hash=''; location.reload();
}
function closeUM(){$('umenu').hidden=true; $('whoBtn').setAttribute('aria-expanded','false');}
$('whoBtn').onclick=e=>{e.stopPropagation(); const m=$('umenu'); m.hidden=!m.hidden; $('whoBtn').setAttribute('aria-expanded',String(!m.hidden));};
document.addEventListener('click',e=>{if(!e.target.closest('.um')) closeUM();});
document.addEventListener('keydown',e=>{if(e.key==='Escape') closeUM();});


/* ---------- shift report ---------- */
function reportData(){
  const P=PER[period];
  const al=alerts.map(a=>({...a,s:alertSev(a)}));
  const tot=period==='d'?{crit:0,high:0,med:0,low:0}:{...P.al}; if(period==='d') al.forEach(a=>tot[a.s[0]]++);
  const cross=period==='d'?GATES.reduce((t,g)=>t+g.today,0):P.cross, blk=period==='d'?GATES.reduce((t,g)=>t+g.blk,0):P.blk, dv=period==='d'?GATES.reduce((t,g)=>t+g.div,0):P.div;
  return {P,al,tot,cross,blk,dv};
}
function shiftReport(){
  const {P,al,tot,cross,blk,dv}=reportData(); const d=new Date(),p=n=>String(n).padStart(2,'0'), ds=`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
  const done=al.filter(a=>acked[a.id]);
  return `<div class="modal-bg" id="rbg"><div class="modal" role="dialog" aria-modal="true" aria-label="تقرير الوردية">
    <div class="m-h"><div><div class="over">تقرير الوردية · ${P.lab}</div><h3>مركز البيانات الرئيسي</h3><div class="muted-s">أُعدّ بواسطة ${ACCTS[acct].n} · <span class="num">${ds}</span></div></div><button class="ib" id="rclose" aria-label="إغلاق">✕</button></div>
    <div class="m-b">
      <div class="rgrid">
        <div><span>إجمالي التنبيهات</span><b class="num">${tot.crit+tot.high+tot.med+tot.low}</b></div>
        <div><span>حرجة</span><b class="num" style="color:var(--alert)">${tot.crit}</b></div>
        <div><span>العبور</span><b class="num">${cross.toLocaleString('en-US')}</b></div>
        <div><span>مرفوض · تحقق يدوي</span><b class="num">${blk} · ${dv}</b></div>
      </div>
      <div class="sub-h">التنبيهات حسب الخطورة</div>
      <table class="tbl"><thead><tr><th>الخطورة</th><th>العدد</th></tr></thead><tbody>${SEVS.slice().reverse().map(s=>`<tr><td>${sev(s)}</td><td class="num">${tot[s[0]]}</td></tr>`).join('')}</tbody></table>
      <div class="sub-h">البوابات</div>
      <table class="tbl"><thead><tr><th>البوابة</th><th>الحالة</th><th>عبور اليوم</th><th>منع</th></tr></thead><tbody>${GATES.map(g=>`<tr><td>${g.name} · ${g.role}</td><td><span class="dotst ${g.st==='on'?'ok':'off'}">${g.st==='on'?'تعمل':'مغلقة'}</span></td><td class="num">${g.today}</td><td class="num">${g.blk}</td></tr>`).join('')}</tbody></table>
      <div class="sub-h">التنبيهات المفتوحة الآن</div>
      <table class="tbl"><thead><tr><th>الرقم</th><th>التنبيه</th><th>المنطقة</th><th>الخطورة</th></tr></thead><tbody>${al.filter(a=>!DONE(a)).map(a=>`<tr><td class="num">${a.id}</td><td>${a.what}</td><td>${zoneName(a.zone)}</td><td>${sev(a.s)}</td></tr>`).join('')}</tbody></table>
      <div class="sub-h">قرارات الوردية</div>
      ${done.length?`<table class="tbl"><tbody>${done.map(a=>`<tr><td class="num">${a.id}</td><td>${a.what}</td><td>${ACK_TXT[acked[a.id]]}</td></tr>`).join('')}</tbody></table>`:'<div class="muted-s">لم تُتخذ قرارات بعد</div>'}
      <div class="sub-h">الأجهزة</div>
      <div class="muted-s">غير متصل: قارئ G2 (المكاتب) منذ 48 ساعة</div>
    </div>
    <div class="m-f"><button class="btn" id="rprint">طباعة</button><button class="btn pri" id="rdl">${ico('dl',14)}تنزيل CSV</button></div>
  </div></div>`;
}
function bindReport(C){
  const bg=$('rbg'); if(!bg) return;
  const close=()=>{reportOpen=false; render();};
  $('rclose').onclick=close; bg.onclick=e=>{if(e.target===bg) close();};
  $('rprint').onclick=()=>{try{window.print();}catch(e){toast('الطباعة غير متاحة هنا');}};
  $('rdl').onclick=()=>{
    const {P,al,tot,cross,blk,dv}=reportData();
    const rows=[['تقرير الوردية',P.lab],['المنشأة','مركز البيانات الرئيسي'],[],['حرج',tot.crit],['عالي',tot.high],['متوسط',tot.med],['منخفض',tot.low],['العبور',cross],['عبور مرفوض',blk],['تحقق يدوي',dv],[],['الرقم','التنبيه','المنطقة','الخطورة','القرار'],...al.map(a=>[a.id,a.what,zoneName(a.zone),a.s[1],acked[a.id]?ACK_TXT[acked[a.id]]:'مفتوح'])];
    const csv='﻿'+rows.map(r=>r.map(c=>`"${String(c??'').replace(/"/g,'""')}"`).join(',')).join('\n');
    const fn=`sawn-shift-report-${period}.csv`;
    (async()=>{ let dl=null; try{ dl = window.claude&&window.claude.use ? await window.claude.use('downloads') : null; }catch(e){}
      if(dl){ try{ await dl.save({filename:fn, data:csv}); toast('تم تنزيل التقرير وتسجيله في سجل التدقيق'); }catch(e){ if(e&&e.code!=='declined') toast('التنزيل غير متاح هنا'); } return; }
      try{const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})); a.download=fn; document.body.appendChild(a); a.click(); a.remove(); toast('تم تنزيل التقرير وتسجيله في سجل التدقيق');}catch(e){toast('التنزيل غير متاح هنا');}
    })();
  };
}

