/* ---------- board health: each gate board reports every 30 s (no serial cable at the booth) ---------- */
const RESET_T={poweron:'تشغيل الكهرباء', external:'زر الإعادة', software:'إعادة تشغيل برمجية', panic:'تعطّل البرنامج', 'int-wdt':'توقف البرنامج (watchdog)', 'task-wdt':'توقف البرنامج (watchdog)', wdt:'توقف البرنامج (watchdog)', deepsleep:'استيقاظ من السكون', brownout:'انخفاض الكهرباء', sdio:'SDIO', unknown:'غير معروف'};
const RESET_BAD=new Set(['brownout','panic','int-wdt','task-wdt','wdt']);
const DEV_T={nfc:'قارئ NFC', keypad:'لوحة الأرقام', fingerprint:'حسّاس البصمة', tof:'حسّاس المسافة VL53L0X', accel:'حسّاس الاهتزاز ADXL345'};
// Gate B parts planned but not wired yet: "missing" is expected, not a fault.
const PLANNED_DEV=new Set(['tof','accel']);
const VAULT_T={'laser-1':'ليزر 1','laser-2':'ليزر 2','reed-vault':'ريد باب الخزنة','reed-lid':'ريد الغطاء','pir':'حساس الحركة','pressure':'حساس الضغط'};
const DEV_S={ok:['ok','موجود'], missing:['off','غير موجود'], 'not-learned':['alarm','موجودة · تحتاج تعليم (المفتاح k)'], collision:['alarm','تعارض عنوان مع قارئ NFC (0x24)']};
const rssiT=r=>!Number.isFinite(r)||!r?'—':`${r} dBm · ${r>=-60?'ممتاز':r>=-70?'جيد':'ضعيف'}`;
// Lock guard (firmware): a request longer than the cap is clamped; one during the rest is refused.
const LOCK_EV_T={clamped:'طلب أطول من الحد — فُتح بالحد الأقصى فقط', 'refused-rest':'رُفض الفتح — القفل في فترة راحة', 'refused-busy':'رُفض الفتح — القفل مفتوح أصلاً', 'refused-fault':'عطل في مؤقّت الأمان — القفل لن يُفتح'};
const LOCK_SRC_T={card:'بطاقة', offline:'قرار بدون المنصة', remote:'فتح عن بُعد', test:'مفتاح اختبار'};
const lockLast=b=>{ const e=((b&&b.lockEvents)||[])[0]; return e?`${LOCK_EV_T[e.event]||e.event} (${LOCK_SRC_T[e.source]||e.source}) ${hm(e.receivedAt)}`:''; };
const lockFault=b=>((b&&b.lockEvents)||[]).some(e=>e.event==='refused-fault');
function boardLamp(b,name){
  if(!b||!b.known) return [name,'pulse','off','لم يصل تقرير صحة بعد'];
  if(!b.fresh) return [name,'pulse','off',`آخر تقرير ${hm(b.receivedAt)} · اللوحة لا ترسل`];
  const miss=Object.entries(b.dev||{}).filter(([k,s])=>s!=='ok'&&!(PLANNED_DEV.has(k)&&s==='missing')).map(([k])=>DEV_T[k]||k);
  const bad=RESET_BAD.has(b.reset)||miss.length||lockFault(b);
  const last=lockLast(b);
  return [name,'pulse',bad?'alarm':'ok',`آخر إعادة تشغيل: ${RESET_T[b.reset]||'—'} · Wi-Fi ${rssiT(b.wifiRssi)}${miss.length?' · يحتاج انتباه: '+miss.join('، '):''}${last?' · القفل: '+last:''}`];
}
function boardHealthBody(b){
  const devs=Object.entries(b.dev||{}).map(([k,s])=>{ if(PLANNED_DEV.has(k)&&s==='missing') return [DEV_T[k]||k,'key','off','لم يُركّب بعد']; const [st,t]=DEV_S[s]||['off',s]; return [DEV_T[k]||k,'key',st,t]; });
  const comps=[boardLamp(b,'اللوحة ESP32'), ...devs];
  if(b.lock){ const L=b.lock, last=lockLast(b);
    comps.push(['القفل · حماية الملف','key',lockFault(b)?'alarm':'ok',`أقصى فتح ${(L.maxMs||0)/1000} ث · راحة ${(L.restMs||0)/1000} ث · قُصّ ${L.clamped||0} · رُفض ${L.refused||0}${last?' · آخر: '+last:''}`]); }
  // The vault alarm: which sensors are armed (a sensor arms once it has shown its normal state).
  if(b.vault!==undefined){ const armed=String(b.vault||'').split(',').filter(Boolean);
    for(const [k,t] of Object.entries(VAULT_T)) comps.push([t,'eye',armed.includes(k)?'ok':'off',armed.includes(k)?'شغّال · مفعّل في إنذار الخزنة':'مو موصول أو ما استقر بعد']); }
  return `<div class="gcomp">${comps.map(([n,i,s,t])=>`<div class="gcomp-i ${s}"><span class="lamp ${s}"></span><span class="gcomp-ic">${ico(i,18)}</span><div class="gcomp-tx"><b>${esc_(n)}</b><small>${esc_(t)}</small></div></div>`).join('')}</div>
    <p class="muted-s" style="margin:10px 14px">${esc_(b.fw||'')} · يعمل منذ ${Math.round((b.uptimeMs||0)/60000)} دقيقة${b.i2c&&b.i2c.length?' · أجهزة I2C: '+b.i2c.map(a=>'0x'+a.toString(16).toUpperCase()).join(' '):''}</p>`;
}

