const VERD=S=>S.some(s=>s[3][0]==='no')?['no','مرفوض','لا يُفتح الباب']:S.some(s=>s[3][0]==='ref')?['ref','تحقق يدوي','يتحقق الضابط يدوياً قبل الفتح']:['ok','سماح','يُفتح الباب'];
const sel_=(id,label,opts,v)=>`<label class="mf"><span>${label}</span><select data-gin="${id}">${opts.map(([k,t])=>`<option value="${k}" ${v===k?'selected':''}>${t}</option>`).join('')}</select></label>`;
