let airRaf=0, airLast=0;
function airLoop(){
  if(airRaf) return;
  const step=t=>{
    const svg=document.querySelector('.rscope.air svg'); if(!svg){ airRaf=0; return; }
    const dt=Math.min(0.25,(t-(airLast||t))/1000); airLast=t;
    if(!airPaused&&!noMotion()) airStep(dt);
    const {cx,cy,R}=AIRC, S=R/asRange, W=1000, mx=asRange, X=k=>30+Math.min(k,mx)/mx*(W-40);
    AIR.forEach(a=>{ const s=airSt(a), [x,y]=airXY(s), g=svg.querySelector(`[data-asel="${a.id}"]`), k=airKm(s);
      if(g){ g.setAttribute('transform',`translate(${x.toFixed(1)} ${y.toFixed(1)})`); const ic=g.querySelector('.aicon'); if(ic) ic.setAttribute('transform',`rotate(${s.hdg.toFixed(1)})`); if(k>asRange*1.02) g.setAttribute('visibility','hidden'); else g.removeAttribute('visibility'); g.classList.toggle('inz',airIn(a,s)); }
      const tr=svg.querySelector(`[data-atr="${a.id}"]`); if(tr) tr.setAttribute('points',s.trail.concat([[s.x,s.y]]).map(p=>`${(cx+p[0]*S).toFixed(1)},${(cy-p[1]*S).toFixed(1)}`).join(' '));
      const pg=document.querySelector(`[data-aprof="${a.id}"]`); if(pg){ pg.setAttribute('transform',`translate(${X(k).toFixed(1)} 0)`); if(k>mx) pg.setAttribute('visibility','hidden'); else pg.removeAttribute('visibility'); }
      const lk=document.querySelector(`[data-airk="${a.id}"]`); if(lk) lk.textContent=k.toFixed(1);
    });
    const a=AIR.find(x=>x.id===asSelA); if(a){ const s=airSt(a), set=(k,v)=>{const e=document.querySelector(`[data-airf="${k}"]`); if(e&&e.textContent!==v) e.textContent=v;};
      set('km',airKm(s).toFixed(2)); set('brg',Math.round(airBrg(s))+'°'); set('hdg',Math.round(s.hdg)+'°'); set('zone',airIn(a,s)?'داخل':'خارج'); }
    const ck=document.querySelector('.rscope.air [data-rclock]'); if(ck&&t-(airLoop.ck||0)>1000){ airLoop.ck=t; ck.textContent=new Date().toLocaleTimeString('en-GB'); }
    airRaf=requestAnimationFrame(step);
  };
  airLast=0; airRaf=requestAnimationFrame(step);
}
